// resolveApiBase: --api-base flag > PIEZAS_API_BASE env > fallback (the
// default recorded in piezas.manifest.json's apiBaseUrl).
export function resolveApiBase(options, env, fallback = DEFAULT_API_BASE_URL) {
  const flagBase = typeof options.apiBase === 'string' && options.apiBase.trim()
    ? options.apiBase.trim()
    : undefined;
  const envBase = typeof env.PIEZAS_API_BASE === 'string' && env.PIEZAS_API_BASE.trim()
    ? env.PIEZAS_API_BASE.trim()
    : undefined;
  return (flagBase || envBase || fallback).replace(/\/+$/, '');
}

export function adminBaseUrl(apiBase) {
  return `${apiBase}${ADMIN_PATH_PREFIX}`;
}

// credentialsFilePath honors PIEZAS_HOME (used by tests) and defaults to
// ~/.piezas/credentials.json.
export function credentialsFilePath(env = process.env) {
  const home = typeof env.PIEZAS_HOME === 'string' && env.PIEZAS_HOME.trim()
    ? env.PIEZAS_HOME.trim()
    : join(homedir(), '.piezas');
  return join(home, 'credentials.json');
}

// readCredentials returns the stored CLI session or undefined. Corrupt or
// token-less files read as "logged out" — never throw.
export function readCredentials(env = process.env) {
  const filePath = credentialsFilePath(env);
  if (!existsSync(filePath)) return undefined;
  try {
    const parsed = JSON.parse(readFileSync(filePath, 'utf-8'));
    if (!parsed || typeof parsed !== 'object' || typeof parsed.cliToken !== 'string' || !parsed.cliToken) {
      return undefined;
    }
    return parsed;
  } catch {
    return undefined;
  }
}

export function writeCredentials(credentials, env = process.env) {
  const filePath = credentialsFilePath(env);
  mkdirSync(dirname(filePath), { recursive: true, mode: 0o700 });
  writeFileSync(filePath, `${JSON.stringify(credentials, null, 2)}\n`, { mode: 0o600 });
  // writeFileSync's mode only applies on create — enforce on rewrite too.
  chmodSync(filePath, 0o600);
  return filePath;
}

// fetchJson: built-in fetch with a hard timeout and JSON parse guards.
// Non-2xx statuses are returned (not thrown); network errors/timeouts throw.
// form sends a form-encoded body instead, as the OAuth endpoints require.
export async function fetchJson(fetchFn, url, { method = 'GET', body, form, token, timeoutMs = HTTP_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const headers = { accept: 'application/json' };
    let payload;
    if (form !== undefined) {
      headers['content-type'] = 'application/x-www-form-urlencoded';
      payload = new URLSearchParams(form).toString();
    } else if (body !== undefined) {
      headers['content-type'] = 'application/json';
      payload = JSON.stringify(body);
    }
    if (token) headers.authorization = `Bearer ${token}`;
    const response = await netFetch(fetchFn, url, {
      method,
      headers,
      body: payload,
      signal: controller.signal,
    });
    let data;
    try {
      data = await response.json();
    } catch {
      data = undefined;
    }
    return { status: response.status, data };
  } finally {
    clearTimeout(timer);
  }
}

// noBrowserHere — a session with no screen to open a browser on: over SSH, or
// Linux with no display (xdg-open could start a text browser inside this very
// terminal).
export function noBrowserHere(env = process.env, platform = process.platform) {
  if (env.SSH_CONNECTION || env.SSH_TTY) return true;
  return platform !== 'darwin' && platform !== 'win32' && !env.DISPLAY && !env.WAYLAND_DISPLAY;
}

function onPath(command, env = process.env) {
  return String(env.PATH ?? '').split(process.platform === 'win32' ? ';' : ':').filter(Boolean)
    .some((d) => existsSync(join(d, command)));
}

// openInBrowser best-effort opens a URL. Returns false when it cannot (no
// screen, or no opener on this machine), so the caller says "open the link
// above"; the URL is always printed either way.
export function openInBrowser(url, env = process.env) {
  try {
    if (noBrowserHere(env)) return false;
    const [command, args] = process.platform === 'darwin'
      ? ['open', [url]]
      : process.platform === 'win32'
        ? ['cmd', ['/c', 'start', '', url]]
        : ['xdg-open', [url]];
    if (process.platform !== 'win32' && !onPath(command, env)) return false;
    const child = spawn(command, args, { stdio: 'ignore', detached: true });
    child.on('error', () => {});
    child.unref();
    return true;
  } catch {
    return false;
  }
}

export function printUserCode(userCode) {
  const inner = `   ${userCode}   `;
  const line = '─'.repeat(inner.length);
  log(`      ╭${line}╮`);
  log(`      │${inner}│`);
  log(`      ╰${line}╯`);
}

export const LOGIN_RETRY_HINT = 'Run `npx piezas login` to get a new code.';

// The CLI is admin-api's `piezas-cli` public client (RFC 8628 device grant).
export const CLI_CLIENT_ID = 'piezas-cli';
export const DEVICE_CODE_GRANT = 'urn:ietf:params:oauth:grant-type:device_code';
// RFC 8628 §3.5: every slow_down adds 5 seconds to the polling interval.
export const SLOW_DOWN_STEP_MS = 5000;

// A device flow starts a sign-in and polls it. start() resolves to
// { status, device }, device set only on success. poll() resolves to { state }:
// 'ok' (with credentials), 'pending', 'slow_down', 'gone' or 'failed' (with
// the HTTP status).

// oauthDeviceFlow speaks RFC 8628 to admin-api's OAuth server.
export function oauthDeviceFlow(fetchFn, admin, timeoutMs) {
  return {
    async start() {
      const res = await fetchJson(fetchFn, `${admin}/oauth/device_authorization`, {
        method: 'POST',
        form: { client_id: CLI_CLIENT_ID },
        timeoutMs,
      });
      const data = res.status === 200 ? res.data : undefined;
      return {
        status: res.status,
        device: data && {
          deviceCode: data.device_code,
          userCode: data.user_code,
          verificationUri: data.verification_uri,
          interval: data.interval,
          expiresIn: data.expires_in,
        },
      };
    },
    async poll(deviceCode) {
      const res = await fetchJson(fetchFn, `${admin}/oauth/token`, {
        method: 'POST',
        form: { grant_type: DEVICE_CODE_GRANT, device_code: deviceCode, client_id: CLI_CLIENT_ID },
        timeoutMs,
      });
      if (res.status === 200 && typeof res.data?.access_token === 'string') {
        return {
          state: 'ok',
          credentials: {
            cliToken: res.data.access_token,
            tenantId: res.data.tenant_id,
            tenantName: res.data.tenant_name,
            email: res.data.email,
          },
        };
      }
      if (res.status === 429 || res.status >= 500) return { state: 'pending' }; // transient
      // A 401/403 (e.g. invalid_client) cannot succeed on a later poll.
      if (res.status !== 400) return { state: 'failed', status: res.status };
      if (res.data?.error === 'authorization_pending') return { state: 'pending' };
      if (res.data?.error === 'slow_down') return { state: 'slow_down' };
      return { state: 'gone' }; // expired_token, invalid_grant, access_denied, ...
    },
  };
}

// legacyDeviceFlow is admin-api's /v1/portal/device-codes API, for a server
// without /oauth/device_authorization. Remove it with those routes.
export function legacyDeviceFlow(fetchFn, admin, timeoutMs) {
  return {
    async start() {
      const res = await fetchJson(fetchFn, `${admin}/v1/portal/device-codes`, { method: 'POST', timeoutMs });
      return { status: res.status, device: res.status === 201 ? res.data : undefined };
    },
    async poll(deviceCode) {
      const res = await fetchJson(fetchFn, `${admin}/v1/portal/device-codes/token`, {
        method: 'POST',
        body: { deviceCode },
        timeoutMs,
      });
      if (res.status === 200 && res.data?.status === 'ok' && typeof res.data.cliToken === 'string') {
        return {
          state: 'ok',
          credentials: {
            cliToken: res.data.cliToken,
            tenantId: res.data.tenantId,
            tenantName: res.data.tenantName,
            email: res.data.email,
          },
        };
      }
      if (res.status === 200) return { state: 'pending' };
      if (res.status === 404 || res.status === 400) return { state: 'gone' };
      return { state: 'pending' }; // transient
    },
  };
}

export async function login(options = {}) {
  const previousEmit = io.emit;
  if (options.json) {
    io.emit = (message) => process.stderr.write(`${message}\n`);
  }
  let outcome;
  try {
    outcome = await runLogin(options);
  } finally {
    io.emit = previousEmit;
  }
  if (options.json) {
    console.log(JSON.stringify(outcome.summary, null, 2));
  }
  return { exitCode: outcome.exitCode, ...outcome.summary };
}

// beginSignIn asks Piezas for a device code (the OAuth device grant, falling
// back to the older device-code route on a server without it). Returns
// { ok: true, flowKind, flow, device, confirmUrl, apiBase } or
// { ok: false, outcome } with the plain-language failure already logged.
export async function beginSignIn(options) {
  const env = options.env ?? process.env;
  const fetchFn = options.fetchFn ?? fetch;
  // --staging / --production choose which Piezas to sign in to, and the choice
  // is saved with the sign-in so every later command follows it.
  const hosts = options.target ? TARGET_HOSTS[options.target] : TARGET_HOSTS[savedTarget(env)] ?? TARGET;
  const apiBase = resolveApiBase(options, env, hosts.api);
  const admin = adminBaseUrl(apiBase);

  let flowKind = 'oauth';
  let flow = oauthDeviceFlow(fetchFn, admin, options.httpTimeoutMs);
  let start;
  try {
    start = await flow.start();
    // Only a missing route falls back; any other refusal is reported as is.
    if (start.status === 404) {
      flowKind = 'legacy';
      flow = legacyDeviceFlow(fetchFn, admin, options.httpTimeoutMs);
      start = await flow.start();
    }
  } catch (error) {
    log(`  Could not reach ${apiBase} (${error?.message || 'network error'}). Check your connection and try again.`);
    return { ok: false, outcome: { exitCode: 1, summary: { command: 'login', status: 'error', error: 'unreachable', apiBase } } };
  }

  if (start.status === 429) {
    log('  Too many sign-in requests are pending right now - wait a few minutes and try again.');
    return { ok: false, outcome: { exitCode: 1, summary: { command: 'login', status: 'error', error: 'rate-limited', apiBase } } };
  }
  const { device } = start;
  if (!device || typeof device.deviceCode !== 'string' || typeof device.userCode !== 'string') {
    log(`  Sign-in could not be started (HTTP ${start.status}). Try again in a moment.`);
    return { ok: false, outcome: { exitCode: 1, summary: { command: 'login', status: 'error', error: `http-${start.status}`, apiBase } } };
  }

  const verificationUri = device.verificationUri || `${hosts.console}/device`;
  const confirmUrl = `${verificationUri}${verificationUri.includes('?') ? '&' : '?'}code=${encodeURIComponent(device.userCode)}`;
  return { ok: true, flowKind, flow, device, confirmUrl, apiBase };
}

// pollSignIn polls until the code is approved, expires or is refused, then
// saves the sign-in (and the --staging/--production choice). deadline is a
// timestamp in milliseconds.
export async function pollSignIn({ flow, device, apiBase, target, deadline, codeExpiresAt }, options) {
  const env = options.env ?? process.env;
  let intervalMs = options.pollIntervalMs
    ?? (Number(device.interval) > 0 ? Number(device.interval) : 5) * 1000;
  const slowDownMs = options.slowDownMs ?? SLOW_DOWN_STEP_MS;

  while (Date.now() < deadline) {
    await new Promise((resolveDelay) => setTimeout(resolveDelay, intervalMs));
    let poll;
    try {
      poll = await flow.poll(device.deviceCode);
    } catch {
      continue; // transient network trouble — keep polling until expiry
    }

    if (poll.state === 'ok') {
      const credentials = { ...poll.credentials, apiBase };
      const credentialsPath = writeCredentials(credentials, env);
      if (target) saveTarget(target, env);
      log('');
      log(`  Logged in as ${credentials.email}${credentials.tenantName ? ` (${credentials.tenantName})` : ''}.`);
      log(`  Session saved to ${credentialsPath}`);
      log('  Next: run `npx piezas init` in your project folder.\n');
      return {
        exitCode: 0,
        summary: {
          command: 'login',
          status: 'ok',
          tenantId: credentials.tenantId ?? null,
          tenantName: credentials.tenantName ?? null,
          email: credentials.email ?? null,
          apiBase,
          credentialsPath,
        },
      };
    }
    if (poll.state === 'failed') {
      log(`  Sign-in failed (HTTP ${poll.status}). ${LOGIN_RETRY_HINT}`);
      return { exitCode: 1, summary: { command: 'login', status: 'error', error: `http-${poll.status}`, apiBase } };
    }
    if (poll.state === 'slow_down') {
      intervalMs += slowDownMs;
      continue;
    }
    if (poll.state === 'gone') {
      log(`  This sign-in code is no longer valid (expired or already used). ${LOGIN_RETRY_HINT}`);
      return { exitCode: 1, summary: { command: 'login', status: 'expired', apiBase } };
    }
    // Pending, including a transient 429/5xx — keep polling until expiry.
  }

  if (codeExpiresAt !== undefined && Date.now() < codeExpiresAt) {
    log('  Not approved yet. The code is still valid: run `piezas login --wait` again.');
    return { exitCode: 1, summary: { command: 'login', status: 'waiting', apiBase } };
  }
  log(`  The sign-in code expired before it was approved. ${LOGIN_RETRY_HINT}`);
  return { exitCode: 1, summary: { command: 'login', status: 'expired', apiBase } };
}

export async function runLogin(options) {
  log(`\n  🧱 Piezas login${options.target === 'staging' ? ' (staging)' : ''}\n`);
  const begun = await beginSignIn(options);
  if (!begun.ok) return begun.outcome;
  const { flow, device, confirmUrl, apiBase } = begun;

  log('  Confirm this code in your browser to sign in:');
  log('');
  printUserCode(device.userCode);
  log('');
  log(`  ${confirmUrl}`);
  log('');
  const opener = options.openBrowserFn ?? openInBrowser;
  // Never "Press ENTER" (Spec Part 2, #1): a person at a terminal (or --open)
  // gets the browser opened straight away; the code and link above stay
  // printed either way. --json and interactive:false stay hands-off.
  const wantOpen = options.open || (
    options.interactive !== false &&
    !options.json &&
    (options.interactive === true || (options.promptFn !== undefined && options.promptFn !== null)));
  // Over SSH or with no display, nothing is opened (a text browser could take
  // over this terminal): the link above is the way.
  const autoOpen = wantOpen && (options.open === true || options.openBrowserFn !== undefined || !noBrowserHere(options.env ?? process.env));
  if (wantOpen && !autoOpen) {
    log('  Open the link above to sign in. Check the code matches, then click Approve.');
    log('');
  }
  if (autoOpen) {
    const opened = opener(confirmUrl);
    log(opened === false
      ? '  Open the link above to sign in. Check the code matches, then click Approve.'
      : '  Your browser is opening. Check the code matches, then click Approve (if it does not open, use the link above).');
    log('');
  }
  log('  Waiting for approval...');

  const lifetimeMs = (Number(device.expiresIn) > 0 ? Number(device.expiresIn) : 900) * 1000;
  return await pollSignIn({ flow, device, apiBase, target: options.target, deadline: Date.now() + lifetimeMs }, options);
}

// --- Two-step sign-in, for AI tools -------------------------------------------
// An AI tool can only pass on a command's output once the command ends, and a
// sandbox may not be able to open a browser. So `login --start` prints the
// approval link and exits at once (the tool shows it as a clickable link), and
// `login --wait` then waits for the approval. The pending code is saved, owner
// readable only, between the two.

// The longest `login --wait` waits in one run.
export const LOGIN_WAIT_MAX_MS = 10 * 60 * 1000;

export function pendingLoginPath(env = process.env) {
  return join(piezasHomeDir(env), 'pending-login.json');
}

function readPendingLogin(env) {
  try {
    const parsed = JSON.parse(readFileSync(pendingLoginPath(env), 'utf-8'));
    return parsed && typeof parsed.deviceCode === 'string' ? parsed : undefined;
  } catch {
    return undefined;
  }
}

function clearPendingLogin(env) {
  try { unlinkSync(pendingLoginPath(env)); } catch { /* already gone */ }
}

export async function loginStart(options = {}) {
  const env = options.env ?? process.env;
  const begun = await beginSignIn(options);
  if (!begun.ok) {
    if (options.json) console.log(JSON.stringify(begun.outcome.summary, null, 2));
    return { exitCode: begun.outcome.exitCode, ...begun.outcome.summary };
  }
  const { flowKind, device, confirmUrl, apiBase } = begun;
  const expiresIn = Number(device.expiresIn) > 0 ? Number(device.expiresIn) : 900;
  const file = pendingLoginPath(env);
  mkdirSync(dirname(file), { recursive: true, mode: 0o700 });
  writeFileSync(file, `${JSON.stringify({
    deviceCode: device.deviceCode,
    userCode: device.userCode,
    interval: Number(device.interval) > 0 ? Number(device.interval) : 5,
    expiresAt: Date.now() + expiresIn * 1000,
    flowKind,
    apiBase,
    target: options.target ?? null,
    url: confirmUrl,
  }, null, 2)}\n`, { mode: 0o600 });
  chmodSync(file, 0o600);

  const opener = options.openBrowserFn ?? openInBrowser;
  if (options.open === true || (options.open !== false && !(options.openBrowserFn === undefined && noBrowserHere(options.env ?? process.env)))) opener(confirmUrl);

  const summary = { command: 'login', status: 'started', url: confirmUrl, code: device.userCode, expiresIn, apiBase };
  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log(`  Open this link to sign in to Piezas: ${confirmUrl}  (code ${device.userCode})`);
    console.log('  Then run `piezas login --wait`.');
  }
  return { exitCode: 0, ...summary };
}

export async function loginWait(options = {}) {
  const env = options.env ?? process.env;
  const pending = readPendingLogin(env);
  const fail = (status, message) => {
    log(`  ${message}`);
    const summary = { command: 'login', status };
    if (options.json) console.log(JSON.stringify(summary, null, 2));
    return { exitCode: 1, ...summary };
  };
  if (!pending) return fail('no-pending', 'No sign-in is waiting. Run `piezas login --start` first.');
  if (Date.now() >= pending.expiresAt) {
    clearPendingLogin(env);
    return fail('expired', 'That sign-in code has expired. Run `piezas login --start` for a new one.');
  }

  const fetchFn = options.fetchFn ?? fetch;
  const admin = adminBaseUrl(pending.apiBase);
  const flow = pending.flowKind === 'legacy'
    ? legacyDeviceFlow(fetchFn, admin, options.httpTimeoutMs)
    : oauthDeviceFlow(fetchFn, admin, options.httpTimeoutMs);
  log(`  Waiting for you to approve code ${pending.userCode}...`);
  const maxWaitMs = options.maxWaitMs ?? LOGIN_WAIT_MAX_MS;
  const deadline = Math.min(pending.expiresAt, Date.now() + maxWaitMs);

  const previousEmit = io.emit;
  if (options.json) io.emit = (message) => process.stderr.write(`${message}\n`);
  let outcome;
  try {
    outcome = await pollSignIn({
      flow,
      device: { deviceCode: pending.deviceCode, interval: pending.interval },
      apiBase: pending.apiBase,
      target: pending.target ?? undefined,
      deadline,
      codeExpiresAt: pending.expiresAt,
    }, options);
  } finally {
    io.emit = previousEmit;
  }
  // Keep the code only while it can still be approved; a later --wait resumes it.
  if (outcome.summary.status !== 'waiting') clearPendingLogin(env);
  if (options.json) console.log(JSON.stringify(outcome.summary, null, 2));
  return { exitCode: outcome.exitCode, ...outcome.summary };
}

// How long logout waits for the server-side session revocation before giving
// up and deleting the local credentials anyway.
export const LOGOUT_REVOKE_TIMEOUT_MS = 2000;

export async function logout(options = {}) {
  const env = options.env ?? process.env;
  const credentialsPath = credentialsFilePath(env);
  const credentials = readCredentials(env);

  // Best-effort server-side revocation BEFORE deleting the local file: the
  // 30-day cliToken is bound to a revocable server session, so logging out
  // kills any copy of the token, not just this machine's file. Failures
  // (offline, expired, 5xx, hung server) never block the local logout.
  let revoked = false;
  if (credentials?.cliToken) {
    const fetchFn = options.fetchFn ?? fetch;
    const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
    try {
      const response = await fetchJson(fetchFn, `${adminBaseUrl(apiBase)}/v1/portal/cli-sessions/revoke`, {
        method: 'POST',
        token: credentials.cliToken,
        timeoutMs: options.revokeTimeoutMs ?? LOGOUT_REVOKE_TIMEOUT_MS,
      });
      revoked = response.status === 200;
    } catch {
      // ignore — logout is local-first
    }
  }

  let removed = false;
  if (existsSync(credentialsPath)) {
    unlinkSync(credentialsPath);
    removed = true;
  }
  const summary = { command: 'logout', removed, revoked, credentialsPath };
  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log(removed ? '  Logged out of Piezas.' : '  Not logged in - nothing to remove.');
  }
  return { exitCode: 0, ...summary };
}

// signInStatus: is this computer signed in to the Piezas this setup talks to?
// A session for a different Piezas (say production, when this build targets
// staging) does not count: commands would send its token to the wrong place.
export function signInStatus(env = process.env) {
  const credentials = readCredentials(env);
  const target = resolveApiBase({}, env, TARGET_HOSTS[savedTarget(env)].api);
  if (!credentials) return { signedIn: false, target };
  const apiBase = (credentials.apiBase ?? DEFAULT_API_BASE_URL).replace(/\/+$/, '');
  return {
    signedIn: apiBase === target,
    otherPiezas: apiBase === target ? undefined : apiBase,
    email: credentials.email ?? null,
    tenantName: credentials.tenantName ?? null,
    target,
  };
}

// signInMismatch: the saved sign-in is for one Piezas (production or staging)
// while this computer is set to use the other. Commands must not quietly use
// the other environment, so they stop and ask for a fresh sign-in. Only the
// two real environments count; other hosts (development, tests) never match.
export function signInMismatch(env = process.env, options = {}) {
  const credentials = readCredentials(env);
  if (!credentials || typeof credentials.apiBase !== 'string') return null;
  const known = Object.values(TARGET_HOSTS).map((h) => h.api);
  const saved = credentials.apiBase.replace(/\/+$/, '');
  if (!known.includes(saved)) return null;
  const target = savedTarget(env);
  const active = resolveApiBase(options, env, TARGET_HOSTS[target].api);
  if (!known.includes(active) || active === saved) return null;
  return { signedInTo: saved, active, loginFlag: target === 'staging' ? ' --staging' : ' --production' };
}

// signInNeededLine: the one plain line commands print when they need an account.
export function signInNeededLine(env = process.env, options = {}) {
  const mismatch = signInMismatch(env, options);
  if (mismatch) {
    return `You're signed in to ${mismatch.signedInTo}, but this computer is set to use ${mismatch.active}. ` +
      `Sign in again for that Piezas: run \`npx piezas login${mismatch.loginFlag}\`, then retry.`;
  }
  return 'You need to sign in first: run `npx piezas login`, then retry.';
}

export function whoami(options = {}) {
  const env = options.env ?? process.env;
  const credentials = readCredentials(env);
  if (!credentials) {
    if (options.json) {
      console.log(JSON.stringify({ command: 'whoami', loggedIn: false }, null, 2));
    } else {
      console.log('  Not logged in. Run `npx piezas login` to sign in.');
    }
    return { exitCode: 1, command: 'whoami', loggedIn: false };
  }

  // Never include the cliToken here — whoami output is safe to paste anywhere.
  const summary = {
    command: 'whoami',
    loggedIn: true,
    tenantId: credentials.tenantId ?? null,
    tenantName: credentials.tenantName ?? null,
    email: credentials.email ?? null,
    apiBase: credentials.apiBase ?? DEFAULT_API_BASE_URL,
    matchesThisSetup: signInStatus(env).signedIn,
  };
  if (options.json) {
    console.log(JSON.stringify(summary, null, 2));
  } else {
    console.log('\n  🧱 Piezas CLI session\n');
    console.log(`  Tenant: ${summary.tenantName ?? 'unknown'}${summary.tenantId ? ` (${summary.tenantId})` : ''}`);
    console.log(`  Email:  ${summary.email ?? 'unknown'}`);
    console.log(`  API:    ${summary.apiBase}\n`);
    if (!summary.matchesThisSetup) {
      console.log(`  This setup uses ${resolveApiBase({}, env)}. Run \`piezas login\` to sign in there.\n`);
    }
  }
  return { exitCode: 0, ...summary };
}

// slugifyAppName mirrors the Go control plane's slugify (and the dashboard
// BFF): lowercase, [a-z0-9] runs joined by single hyphens, trimmed.
export function slugifyAppName(name) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// defaultAppName — what to call a new app without asking: the manifest's
// name, else package.json's (when it is not a template's), else the folder.
export function defaultAppName(projectDir) {
  try {
    const name = readJsonFile(resolve(projectDir, 'piezas.manifest.json'))?.appName;
    if (typeof name === 'string' && name.trim()) return { name: name.trim(), from: 'its name in this project' };
  } catch { /* no manifest */ }
  try {
    const pkg = readJsonFile(resolve(projectDir, 'package.json'));
    const raw = typeof pkg?.name === 'string' ? pkg.name.replace(/^@[^/]+\//, '') : '';
    // A package.json named after the folder (as init writes it) says nothing more.
    if (raw && raw !== packageNameFromDir(projectDir) && !/^(?:vite[_-]react[_-]|my-|app$|vite-project$|piezas-app$)/i.test(raw)) {
      return { name: raw.replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()), from: 'from the app\'s own name' };
    }
  } catch { /* no package.json */ }
  return { name: basename(projectDir), from: 'from the folder name' };
}

// isCI — a CI run (CI set to anything but "false" / "0" / ""), or a build
// server that sets no CI variable, by its per-build variables (Azure
// Pipelines; Jenkins only with a build number, since developers export
// JENKINS_URL in their own shells for the Jenkins CLI).
export function isCI(env = process.env) {
  const v = String(env.CI ?? '').trim().toLowerCase();
  if (v !== '' && v !== 'false' && v !== '0') return true;
  const set = (k) => String(env[k] ?? '').trim() !== '';
  return set('TF_BUILD') || set('BUILD_BUILDID') || (set('JENKINS_URL') && set('BUILD_NUMBER')) || (set('JENKINS_HOME') && set('BUILD_ID'));
}

// initAtOwnerTerminal — init runs at a person's own terminal: a terminal on
// stdin, no sign of ANY AI tool (Claude Code, Codex, Cursor, Windsurf, Copilot,
// Aider, a generic AGENT variable, an AI tool in the process chain), not CI.
// `--i-am-the-owner` answers for CI and a piped output, never for an AI sign.
// `--from-login` alone is not a person (hands-off like any non-person run).
// A simulated (sandbox) app is never a real app or key, so it is exempt.
export function initAtOwnerTerminal(options, env = options.env ?? process.env, projectDir = options.cwd) {
  if (options.sandbox || (projectDir && isSandboxProject(projectDir))) return true;
  if (inAiTool(env)) return false;
  if (options.iAmTheOwner === true) return true;
  if (isCI(env)) return false;
  // `--from-login` names where the key comes from, not who runs it: it never
  // counts as a person at the terminal on its own.
  return options.atTerminal === true || Boolean(options.promptFn) || options.interactive === true;
}

// signedInAiInit — a NAMED AI tool (Claude Code or Codex by their own
// variables, or an AI tool in the process chain; never a generic marker such
// as AGENT or AGENT_ID, which build servers set too) runs init outside CI.
// Reached only with a saved CLI session, so the owner's own sign-in stands
// behind it. `--i-am-the-owner` plays no part here.
function signedInAiInit(env) {
  if (isCI(env)) return false;
  return Boolean(agentHost(env)) || aiHostSignals(env).some((s) => s.startsWith('process:'));
}

// aiRunForOwner — init (or its test copy) runs on the AI path: an AI tool for
// a signed-in owner, not a person at their own terminal. On this path a name
// that is already taken never reuses that app.
export function aiRunForOwner(options, env = options.env ?? process.env, projectDir = options.cwd) {
  return !initAtOwnerTerminal(options, env, projectDir) && signedInAiInit(env);
}

// earlierLinkTrace — on the AI path a folder counts as linked when any trace
// of an earlier link is left in it or a folder above it: a deploy link or key
// record in .piezas/, or a manifest that names its app. A deleted manifest
// leaves the records. Above the folder, the global Piezas folder (the
// credentials' folder, PIEZAS_HOME or ~/.piezas) holds no project's records.
// Returns the folder that holds the trace, or null.
function earlierLinkTrace(projectDir, env) {
  const hasId = (v) => typeof v === 'string' && v.trim() !== '';
  const here = resolve(projectDir);
  const globalDirs = new Set([piezasHomeDir(env), piezasHomeDir({})].map(realish));
  for (let dir = here; ; dir = dirname(dir)) {
    let link = null;
    try { link = readJsonFile(join(dir, STATE_DIR, DEPLOY_LINK_FILE)); } catch { /* none */ }
    const recorded = [link?.appId, readKeyMint(dir)?.appId].some(hasId)
      && (dir === here || !globalDirs.has(realish(join(dir, STATE_DIR))));
    if (recorded || hasId(readManifestSafe(dir)?.deploy?.appId)) return dir;
    if (dirname(dir) === dir) return null;
  }
}

// One init at a time per folder: a second one running at once would mint a
// key that nothing records. The lock holds the pid of its run; it is let go
// on exit and on Ctrl-C, and a lock whose run is gone (or that is older than
// two minutes) is stale.
const INIT_LOCK_FILE = 'init.lock';
const INIT_LOCK_STALE_MS = 2 * 60 * 1000;
const INIT_LOCK_WAIT_MS = 3000;
async function takeInitLock(projectDir) {
  const dir = join(projectDir, STATE_DIR);
  const file = join(dir, INIT_LOCK_FILE);
  try { mkdirSync(dir, { recursive: true }); } catch { return () => {}; }
  const take = () => {
    try { const fd = openSync(file, 'wx'); writeFileSync(fd, String(process.pid)); closeSync(fd); return true; } catch (e) { return e?.code === 'EEXIST' ? false : null; }
  };
  const drop = () => { try { rmSync(file, { force: true }); } catch { /* best effort */ } };
  const onSignal = (signal) => { drop(); process.exit(signal === 'SIGINT' ? 130 : 143); };
  const held = () => {
    process.on('exit', drop);
    process.once('SIGINT', onSignal);
    process.once('SIGTERM', onSignal);
    return () => {
      process.off('exit', drop);
      process.off('SIGINT', onSignal);
      process.off('SIGTERM', onSignal);
      drop();
    };
  };
  const stale = () => {
    try {
      const pid = Number.parseInt(readFileSync(file, 'utf-8'), 10);
      if (pid > 0 && pid !== process.pid) {
        try { process.kill(pid, 0); } catch (e) { if (e?.code === 'ESRCH') return true; }
      }
      return Date.now() - statSync(file).mtimeMs > INIT_LOCK_STALE_MS;
    } catch {
      return false;
    }
  };
  const got = take();
  if (got === null) return () => {}; // the folder cannot hold a lock: go on as before
  if (got) return held();
  if (stale()) { drop(); if (take()) return held(); }
  const until = Date.now() + INIT_LOCK_WAIT_MS;
  while (Date.now() < until) {
    await new Promise((r) => setTimeout(r, 100));
    if (existsSync(file)) continue;
    break;
  }
  return null;
}

// resolveKeyViaLogin: when no key was found by the normal intake chain but a
// CLI session exists, create the app (or reuse it on a name conflict) and
// mint a live key bound to it — the same composition the dashboard's
// onboarding performs. Every failure degrades to "no key" with a friendly
// message; init never crashes because of this step.
export async function resolveKeyViaLogin(projectDir, options) {
  const env = options.env ?? process.env;
  const credentials = platformCredentials(projectDir, env);
  if (!credentials) return resolveKeyViaLoginLocked(projectDir, options);
  const release = await takeInitLock(projectDir);
  if (!release) {
    log('  Another Piezas setup is running in this folder, so this one stopped without creating anything. Run init again once it finishes.');
    return undefined;
  }
  try {
    return await resolveKeyViaLoginLocked(projectDir, options);
  } finally {
    release();
  }
}

async function resolveKeyViaLoginLocked(projectDir, options) {
  const env = options.env ?? process.env;
  const credentials = platformCredentials(projectDir, env);
  if (!credentials) {
    if (signInMismatch(env, options)) log(`  ${signInNeededLine(env, options)}`);
    return undefined;
  }

  // Hands-off unless a person runs it at their own terminal, or an AI tool
  // runs it for a signed-in owner (the browser sign-in is the owner's
  // consent; a linked folder still only gets a key for its own app, below).
  // In CI, or with no terminal and no AI tool (a script, a container), no app
  // is created and no key is minted.
  if (!initAtOwnerTerminal(options, env, projectDir) && !signedInAiInit(env)) {
    log(isCI(env)
      ? '  No one is at a terminal here, so no app was created and no key was minted. Run init in your own terminal to create them.'
      : '  Not run at your own terminal, so no app was created and no key was minted. Run init in your own terminal to create them.');
    return undefined;
  }

  // Already linked (deploy.appId in the manifest; a fresh clone has no .env):
  // mint a key for THAT app, never create one or re-point the project by name.
  let linkedManifest = null;
  try { linkedManifest = readJsonFile(resolve(projectDir, 'piezas.manifest.json')); } catch { /* no manifest */ }
  const linkedAppId = typeof linkedManifest?.deploy?.appId === 'string' && linkedManifest.deploy.appId.trim() ? linkedManifest.deploy.appId.trim() : null;
  if (linkedAppId) return mintForLinkedApp(projectDir, options, credentials, linkedManifest, linkedAppId);

  // On the AI path, a folder with any trace of an earlier link (or inside a
  // linked project) gets no new app and no key.
  const aiPath = aiRunForOwner(options, env, projectDir);
  const linkedAt = aiPath ? earlierLinkTrace(projectDir, env) : null;
  if (linkedAt) {
    log('  This folder belongs to a project already linked to an app, so no new app was created and no key was minted.');
    log(linkedAt === resolve(projectDir)
      ? '  (For the AI: this folder\'s own records link it to an app; never create a second app for it or delete piezas.manifest.json; ask the owner.)'
      : `  (For the AI: never create a second app for this project or delete piezas.manifest.json; the link is recorded in ${linkedAt}; run init in the linked project's own folder, or ask the owner.)`);
    return undefined;
  }

  // Signed in: create the app and mint its key, never "create or paste?"
  // (Spec Part 2, #7). The name is never asked either: --app, else what the
  // project says (its manifest, its package.json), else the folder; said in
  // one line and changeable in the console.
  const flagApp = (typeof options.app === 'string' && options.app.trim())
    ? options.app.trim()
    : undefined;
  let appName = flagApp;
  if (!appName) {
    const guess = defaultAppName(projectDir);
    appName = guess.name;
    log(`  Calling the app "${appName}" (${guess.from}). You can rename it any time in the Piezas console.`);
  }

  const fetchFn = platformFetch(projectDir, options);
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const admin = adminBaseUrl(apiBase);
  const tenantPath = `${admin}/v1/tenants/${credentials.tenantId}`;
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const sessionExpired = () => {
    log('  Your Piezas session has expired - run `npx piezas login`, then rerun init.');
    return undefined;
  };

  try {
    let app;
    const created = await fetchJson(fetchFn, `${tenantPath}/partitions`, {
      ...httpOptions,
      method: 'POST',
      body: { name: appName },
    });
    if (created.status === 201 && created.data?.id) {
      app = created.data;
      const account = credentials.email
        ? `the Piezas account you signed in with (${credentials.email}${credentials.tenantName ? `, ${credentials.tenantName}` : ''})`
        : `your Piezas account${credentials.tenantName ? ` (${credentials.tenantName})` : ''}`;
      // A practice (sandbox) app is in no real account: said only in detail.
      (isSandboxProject(projectDir) ? detail : log)(`  Created the app "${app.name}" in ${account}.`);
    } else if (created.status === 409 && aiPath) {
      // The name is taken. From an AI run that app is never used: the AI
      // picks another name.
      log(`  You already have an app called "${appName}", so no new app was created and no key was minted.`);
      log(`  (For the AI: never use that app from here. Tell the owner in one sentence that an app called "${appName}" already exists, and ask whether to use a different name; run init again with --app and the name they give. If they say this project is that app, the deploy links it, asking them first if it is live.)`);
      return { key: undefined, source: 'name-taken' };
    } else if (created.status === 409) {
      // The app already exists — find it by the same slug the platform
      // derived (or by exact name) and reuse it, exactly like the dashboard.
      // LIST via my-apps (an admin sees all; create already proved admin here).
      const listed = await fetchJson(fetchFn, `${tenantPath}/my-apps`, httpOptions);
      if (listed.status === 401) return sessionExpired();
      const slug = slugifyAppName(appName);
      const existing = Array.isArray(listed.data?.data)
        ? listed.data.data.find((p) => p?.slug === slug || p?.name === appName)
        : undefined;
      if (!existing) {
        log('  An app with that name already exists but could not be found - continuing without a key.');
        return undefined;
      }
      app = existing;
      log(`  Reusing existing app "${app.name}"`);
    } else if (created.status === 401) {
      return sessionExpired();
    } else if (created.status === 403) {
      // Creating an app is admin-only — don't pretend a developer can self-serve.
      log('  Only an admin can create an app — ask an admin to create it and grant you');
      log('  access, then rerun init (or paste an existing key). Continuing without a key.');
      return undefined;
    } else {
      log(`  Could not create the app (HTTP ${created.status}) - continuing without a key.`);
      return undefined;
    }

    const minted = await fetchJson(fetchFn, `${tenantPath}/api-keys`, {
      ...httpOptions,
      method: 'POST',
      body: { name: appName, environment: 'live', partitionId: app.id },
    });
    if (minted.status === 401) return sessionExpired();
    if (minted.status !== 201 || typeof minted.data?.key !== 'string' || !minted.data.key) {
      log(`  Could not mint an API key (HTTP ${minted.status}) - continuing without a key.`);
      return undefined;
    }
    detail(`  Minted a live API key for "${app.name}"`);

    // Provision the HOSTED environment at birth: stage the freshly-minted key
    // into the apps server's cloud env store, bound to the app's durable id.
    // Best-effort — hosting may not be provisioned in every install — and the
    // local .env copy remains for LOCAL development only; deploys never read it.
    try {
      const appsBase = appsBaseUrl(options, env);
      const stagedRes = await fetchJson(fetchFn,
        `${appsBase}/v1/deployments/${slugifyAppName(app.name)}/env?appId=${encodeURIComponent(app.id)}`,
        { token: credentials.cliToken, method: 'PATCH', body: { set: { PIEZAS_API_KEY: minted.data.key } }, timeoutMs: 4000 });
      if (stagedRes.status === 200) {
        detail('  Hosted env provisioned — PIEZAS_API_KEY is already staged for deploys');
      }
    } catch { /* hosting is optional at init time */ }

    // The app this init created is this project's from birth: keep the
    // project's link record now, so a removed manifest still counts as linked.
    // Only in this folder itself: never over the link of a project above it.
    if (created.status === 201 && deployRecordRoot(projectDir) === resolve(projectDir)) {
      try { deployLinkFor(projectDir, app.id); } catch { /* best effort */ }
    }
    return { key: minted.data.key, source: 'login', appName: app.name, appId: app.id };
  } catch (error) {
    log(`  Could not reach Piezas (${error?.message || 'network error'}) - continuing without a key.`);
    return undefined;
  }
}

// mintForLinkedApp — a key for the app this project is already linked to
// (bound to its durable id), staged where its deploys read their settings.
async function mintForLinkedApp(projectDir, options, credentials, manifest, appId) {
  const env = options.env ?? process.env;
  const fetchFn = platformFetch(projectDir, options);
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const tenantPath = `${adminBaseUrl(apiBase)}/v1/tenants/${credentials.tenantId}`;
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const appName = typeof manifest?.appName === 'string' && manifest.appName.trim() ? manifest.appName.trim() : appId;
  try {
    const minted = await fetchJson(fetchFn, `${tenantPath}/api-keys`, {
      ...httpOptions,
      method: 'POST',
      body: { name: appName, environment: 'live', partitionId: appId },
    });
    if (minted.status === 401) {
      log('  Your Piezas sign-in has run out. Sign in again (piezas login), then run init again.');
      return undefined;
    }
    if (minted.status !== 201 || typeof minted.data?.key !== 'string' || !minted.data.key) {
      log(`  Could not get a key for ${appName === appId ? 'this project\'s app' : `"${appName}"`} just now, so init went on without one.`);
      detail(`  (the control plane answered HTTP ${minted.status})`);
      return undefined;
    }
    detail(`  Minted a live API key for this project's app "${appName}"`);
    try {
      const stagedRes = await fetchJson(fetchFn,
        `${appsBaseUrl(options, env)}/v1/deployments/${deploySlugFor(projectDir, {})}/env?appId=${encodeURIComponent(appId)}`,
        { token: credentials.cliToken, method: 'PATCH', body: { set: { PIEZAS_API_KEY: minted.data.key } }, timeoutMs: 4000 });
      if (stagedRes.status === 200) detail('  Hosted env provisioned — PIEZAS_API_KEY is already staged for deploys');
    } catch { /* hosting is optional at init time */ }
    return { key: minted.data.key, source: 'login', appName, appId, linked: true };
  } catch (error) {
    log(`  Could not reach Piezas (${error?.message || 'network error'}) - continuing without a key.`);
    return undefined;
  }
}

// --- End platform auth ---------------------------------------------------

// --- piezas deploy: ship the built app to the shared apps server ----------

export const DEFAULT_APPS_URL = TARGET.apps;
export const DEPLOY_TIMEOUT_MS = 10 * 60 * 1000; // uploads can be slow; be patient
// Client-side artifact cap — a FAST-FAIL courtesy so an oversized bundle is
// caught before a slow upload. Piezas hosting enforces its own limit
// server-side and is the authoritative check; this only exists to save
// a doomed round-trip. Configurable via PIEZAS_MAX_ARTIFACT_MB so it tracks the
// server default and can be raised without a CLI release. A full Piezas app
// (Next standalone) is ~10 MB compressed, so blowing this almost always means
// node_modules or media that belongs in the Documents service.
export function resolveMaxArtifactMB(env = process.env) {
  const raw = Number(env.PIEZAS_MAX_ARTIFACT_MB);
  return Number.isFinite(raw) && raw > 0 ? raw : 60;
}

export function appsBaseUrl(options, env) {
  const flag = typeof options.appsUrl === 'string' && options.appsUrl.trim()
    ? options.appsUrl.trim() : undefined;
  const fromEnv = typeof env.PIEZAS_APPS_URL === 'string' && env.PIEZAS_APPS_URL.trim()
    ? env.PIEZAS_APPS_URL.trim() : undefined;
  return (flag || fromEnv || DEFAULT_APPS_URL).replace(/\/+$/, '');
}

// deploySlugFor mirrors the server's base slugify so status/logs/delete can
// address the deployment. The authoritative (possibly suffixed) slug returned
// by a deploy is persisted into piezas.manifest.json for later commands.
export function deploySlugFor(projectDir, options) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  let manifest = null;
  try { manifest = readJsonFile(manifestPath); } catch { /* absent/corrupt is fine */ }
  if (manifest?.deploy?.slug && !options.app) return manifest.deploy.slug;
  const name = (typeof options.app === 'string' && options.app.trim())
    ? options.app.trim()
    : manifest?.appName || basename(projectDir);
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

// Source-ish folders: they hold examples, fixtures, tests and tooling, never
// the build that ships, even when one of them has a server.js + package.json.
const BUNDLE_SOURCE_DIRS = new Set([
  'examples', 'example', 'fixtures', 'fixture', 'test', 'tests', '__tests__', '__mocks__',
  'mocks', 'spec', 'specs', 'docs', 'samples', 'sample', 'scripts', 'src',
]);

// findServerBundles: build tools write a server bundle wherever their config
// says (esbuild -> build/runtime, tsup -> dist-server, ...). What they share
// is the pair at the folder's root: server.js AND package.json. Next
// standalone output has exactly that pair too; source folders almost never do
// (server/server.js alone is source, not a bundle). Walks to depth 3, skipping
// node_modules, dot-folders, the noise folders and source-ish folders
// (examples, fixtures, tests, src, ...) — but NOT build/dist/out, which is
// where bundles land. The project root itself is never a bundle.
// Bounded (entry budget) like detectStaleBuild. Returns relative paths, sorted.
export function findServerBundles(projectDir) {
  const skip = new Set([
    ...[...DEFAULT_EXCLUDED_DIRS].filter((d) => !['build', 'dist', 'out'].includes(d)),
    ...BUNDLE_SOURCE_DIRS,
  ]);
  const found = [];
  let budget = 3000;
  const walk = (dir, depth) => {
    if (budget <= 0 || depth > 3) return;
    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (budget-- <= 0) return;
      if (!entry.isDirectory() || entry.isSymbolicLink()) continue;
      if (entry.name.startsWith('.') || skip.has(entry.name)) continue;
      const full = join(dir, entry.name);
      if (existsSync(join(full, 'server.js')) && existsSync(join(full, 'package.json'))) {
        found.push(relative(projectDir, full).split(sep).join('/'));
        continue; // a bundle's insides are not further candidates
      }
      walk(full, depth + 1);
    }
  };
  walk(projectDir, 1);
  return found.sort();
}

// manifestDeployDir: the folder the project recorded as its build output
// (deploy.dir in piezas.manifest.json), or null.
export function manifestDeployDir(projectDir) {
  try {
    const dir = readJsonFile(resolve(projectDir, 'piezas.manifest.json'))?.deploy?.dir;
    return typeof dir === 'string' && dir.trim() ? dir.trim() : null;
  } catch { return null; }
}

// projectRelativeDir: `dir` (relative to the project, or absolute) as a
// project-relative POSIX path ('.' for the project itself), or null when it
// resolves outside the project. The manifest is committed: an absolute or
// outside path would break every other checkout.
export function projectRelativeDir(projectDir, dir) {
  const rel = relative(resolve(projectDir), resolve(projectDir, dir));
  if (rel === '') return '.';
  if (isAbsolute(rel) || rel === '..' || rel.startsWith(`..${sep}`)) return null;
  return rel.split(sep).join('/');
}

// persistDeployDir records the build folder in the manifest, so the choice is
// made once (an expert --dir, or the owner's answer to "which one?"). Stores a
// project-relative POSIX path; a folder outside the project is never recorded.
// Returns the recorded value, or null when nothing was recorded.
export function persistDeployDir(projectDir, dir) {
  const rel = projectRelativeDir(projectDir, dir);
  if (!rel) return null;
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  try {
    const manifest = readJsonFile(manifestPath);
    manifest.deploy = { ...(manifest.deploy || {}), dir: rel };
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
    return rel;
  } catch { return null; } // no manifest: nothing to record into
}

// folderKind: what a folder would deploy as — server.js -> "server",
// index.html -> "static", neither -> null.
function folderKind(path) {
  if (existsSync(resolve(path, 'server.js'))) return 'server';
  if (existsSync(resolve(path, 'index.html'))) return 'static';
  return null;
}

// discoverBuilds is the ONE discovery order (deploy.dir aside), shared by
// artifactCandidates and the wrong-folder suggestion:
//   1. Next standalone output (.next/standalone/server.js)
//   2. server bundles found in the project (server.js + package.json)
//   3. the project root as a server app, when it has server.js — server
//      builds always rank ahead of static folders: a root Express app that
//      serves a Vite dist/ is the app, dist/ is only its browser part
//   4. static export: out/, then dist/ (index.html)
//   5. the project root as a static site (index.html), last and only when no
//      build output exists — a Vite project's root index.html is source.
// Each candidate: { via, folder (label for messages), dir (project-relative
// path, the value deploy.dir takes), source, path, kind }. `except` drops the
// folder at that path (the explicit folder already checked).
export function discoverBuilds(projectDir, { except = null } = {}) {
  const list = [];
  const standalone = resolve(projectDir, '.next', 'standalone');
  if (existsSync(resolve(standalone, 'server.js'))) {
    list.push({ via: 'standalone', folder: '.next/standalone', dir: '.next/standalone', source: 'next standalone', path: standalone, kind: 'server' });
  }
  for (const b of findServerBundles(projectDir)) {
    const path = resolve(projectDir, b);
    if (path === standalone) continue;
    list.push({ via: 'bundle', folder: b, dir: b, source: b, path, kind: 'server' });
  }
  const rootKind = folderKind(projectDir);
  const root = { via: 'root', folder: 'the project folder', dir: '.', source: 'project root', path: resolve(projectDir), kind: rootKind };
  if (rootKind === 'server') list.push(root);
  for (const c of ['out', 'dist']) {
    const path = resolve(projectDir, c);
    if (existsSync(resolve(path, 'index.html'))) list.push({ via: 'static', folder: `${c}/`, dir: c, source: `${c}/`, path, kind: 'static' });
  }
  if (rootKind === 'static' && !list.length) list.push(root);
  const skip = except ? resolve(except) : null;
  return skip ? list.filter((c) => c.path !== skip) : list;
}

// artifactCandidates lists the folders deploy could ship:
//   - --dir <path> (expert flag) or deploy.dir in piezas.manifest.json — when
//     set, the ONLY candidate (explicit wins). A recorded deploy.dir that no
//     longer exists falls through to discovery (dirMissing says so).
//   - otherwise discoverBuilds, in its order.
export function artifactCandidates(projectDir, options = {}) {
  const flagDir = typeof options.dir === 'string' && options.dir.trim() ? options.dir.trim() : null;
  const recorded = flagDir ? null : manifestDeployDir(projectDir);
  const explicitDir = flagDir ?? recorded;
  let dirMissing = null;
  if (explicitDir) {
    const path = resolve(projectDir, explicitDir);
    if (existsSync(path) || flagDir) {
      return {
        explicit: true,
        dirMissing,
        list: [{ via: flagDir ? 'dir' : 'manifest', folder: explicitDir, dir: explicitDir, source: explicitDir, path, kind: existsSync(path) ? folderKind(path) : null }],
      };
    }
    dirMissing = recorded;
  }
  return { explicit: false, dirMissing, list: discoverBuilds(projectDir) };
}

// evidenceCache: piezasEvidence memoised per resolved path (and SDK option),
// so one deploy run scans each folder at most once however many times it
// selects. Pass the same cache to every selectArtifact call in a run.
export function evidenceCache() {
  const seen = new Map();
  return (path, opts = {}) => {
    const skip = (opts.exclude || []).map((p) => resolve(p)).sort().join('|');
    const key = `${opts.installedSdk === false ? 'src' : 'all'}:${resolve(path)}:${skip}`;
    if (!seen.has(key)) seen.set(key, piezasEvidence(path, opts));
    return seen.get(key);
  };
}

// Build-output locations: a server bundle under one of these is compiled
// output, so a root server.js beside it is its source entry.
const BUILD_OUTPUT_DIRS = new Set(['build', 'dist', 'out', '.output']);

// bundleBuiltFromRoot: the bundle is the project root's own compiled output —
// it sits in a build-output location, or its package.json name is the root's
// name plus a suffix ("support-app" -> "support-app-runtime").
function bundleBuiltFromRoot(projectDir, bundle) {
  const top = projectRelativeDir(projectDir, bundle.path)?.split('/')[0];
  if (top && BUILD_OUTPUT_DIRS.has(top)) return true;
  const name = (dir) => {
    try {
      const n = readJsonFile(resolve(dir, 'package.json'))?.name;
      return typeof n === 'string' ? n.trim() : '';
    } catch { return ''; }
  };
  const rootName = name(projectDir);
  const bundleName = name(bundle.path);
  return Boolean(rootName) && bundleName.length > rootName.length && bundleName.startsWith(rootName);
}

// selectArtifact decides WHICH folder deploy ships — Piezas evidence is the
// selector, folder order only breaks ties. stageArtifact, detectStaleBuild and
// the deploy messages all use it, so they never disagree. Evidence is only
// ever `true` when a scan found it: an 'unknown' scan (the folder couldn't be
// read) never wins. Server builds (Next standalone, bundles, a root server.js)
// rank ahead of static folders. Candidates are scanned lazily, in order: once
// a server build with evidence is found, only the remaining server builds are
// scanned (to catch two real builds); static folders are not. The project
// root is scanned WITHOUT the other build folders inside it, so a bundle's
// evidence never counts as the root's.
// Returns one of:
//   { status: 'ok', chosen, note, candidates, dirMissing }
//   { status: 'ambiguous', candidates: [folder, ...], dirs: [deploy.dir value, ...] }
//                                                       several server builds use Piezas
//   { status: 'no-piezas-build', candidates }           builds exist; none uses Piezas
//   { status: 'wrong-folder', chosen, suggested }       the explicit folder lacks Piezas; another has it
//   { status: 'none', dirMissing }                      nothing deployable at all
// `evidence` is a (path) => true | false | 'unknown' function (evidenceCache()).
export function selectArtifact(projectDir, options = {}, { evidence = evidenceCache() } = {}) {
  const { explicit, dirMissing, list } = artifactCandidates(projectDir, options);
  const withMissing = dirMissing ? { dirMissing } : {};
  const deployable = list.filter((c) => c.kind);
  if (!deployable.length) return { status: 'none', ...withMissing };
  const rootPath = resolve(projectDir);
  let otherBuilds = null; // build folders inside the root, excluded from its scan
  const uses = (c) => {
    if (!('piezas' in c)) {
      if (c.path === rootPath) {
        otherBuilds ??= discoverBuilds(projectDir).filter((b) => b.path !== rootPath).map((b) => b.path);
        c.piezas = evidence(c.path, { exclude: otherBuilds });
      } else {
        c.piezas = evidence(c.path);
      }
    }
    return c.piezas === true;
  };

  if (explicit) {
    const chosen = deployable[0];
    if (uses(chosen)) return { status: 'ok', chosen, note: null, candidates: deployable };
    // The recorded/typed folder doesn't use Piezas: is another one the app?
    const other = discoverBuilds(projectDir, { except: chosen.path }).find(uses);
    if (other) return { status: 'wrong-folder', chosen, suggested: other.dir, suggestedFolder: other.folder };
    return { status: 'no-piezas-build', candidates: deployable };
  }

  const first = deployable.find(uses);
  if (!first) return { status: 'no-piezas-build', candidates: deployable, ...withMissing };
  // Two or more server builds (bundles, or a root server.js) that both use
  // Piezas: never guess. Next standalone with evidence wins outright (it is
  // the root's own build output) and never reaches this check; a stale
  // standalone without evidence doesn't silence it.
  // The root is a rival to a bundle only on its OWN source: the installed
  // SDK (node_modules) and the other build folders don't count. And a bundle
  // in a build-output location (build/, dist/, out/, .output/), or one whose
  // package.json name is the root's name plus a suffix, is the root's own
  // compiled output — the root server.js is its source entry, not a rival.
  if (first.via === 'bundle' || first.via === 'root') {
    const rootRival = (c) => {
      if (first.via === 'bundle' && bundleBuiltFromRoot(projectDir, first)) return false;
      otherBuilds ??= discoverBuilds(projectDir).filter((b) => b.path !== rootPath).map((b) => b.path);
      return evidence(c.path, { installedSdk: false, exclude: otherBuilds }) === true;
    };
    const rival = (c) => (c.via === 'bundle' && uses(c)) || (c.via === 'root' && c.kind === 'server' && rootRival(c));
    const servers = [first, ...deployable.filter((c) => c !== first && rival(c))];
    if (servers.length > 1) {
      return { status: 'ambiguous', candidates: servers.map((c) => c.folder), dirs: servers.map((c) => c.dir), ...withMissing };
    }
  }
  // One plain line when a build was passed over. A static folder next to the
  // chosen server build is that server's browser part (a cheap kind check,
  // no scan).
  let note = null;
  const passedStatic = first.kind === 'server' ? deployable.find((c) => c.kind === 'static') : null;
  const passedFirst = deployable[0] !== first ? deployable[0] : null;
  if (passedStatic) {
    note = `${passedStatic.folder} is only the browser part of the app; deploying the server build in ${first.folder} instead.`;
  } else if (passedFirst) {
    note = `${passedFirst.folder} doesn't use Piezas; deploying ${first.folder} instead.`;
  }
  return { status: 'ok', chosen: first, note, candidates: deployable, ...withMissing };
}

// stageArtifact assembles the folder selectArtifact chose in a temp dir.
// A folder with server.js is kind "server", one with index.html is "static".
// Returns the staged { kind, source, via, path, note, removed }, or null when
// the selection is not 'ok' (deploy reads selectArtifact for the reason).
export function stageArtifact(projectDir, stagingDir, options, selection = selectArtifact(projectDir, options)) {
  if (selection.status !== 'ok') return null;
  const copyInto = (src) => execSync(`cp -R ${JSON.stringify(src)}/. ${JSON.stringify(stagingDir)}/`);
  const { chosen } = selection;
  copyInto(chosen.path);
  if (chosen.via === 'standalone') {
    const staticDir = resolve(projectDir, '.next', 'static');
    if (existsSync(staticDir)) {
      mkdirSync(resolve(stagingDir, '.next'), { recursive: true });
      execSync(`cp -R ${JSON.stringify(staticDir)} ${JSON.stringify(resolve(stagingDir, '.next', 'static'))}`);
    }
    const publicDir = resolve(projectDir, 'public');
    if (existsSync(publicDir)) {
      execSync(`cp -R ${JSON.stringify(publicDir)} ${JSON.stringify(resolve(stagingDir, 'public'))}`);
    }
  }
  // Every artifact is scrubbed, whatever its shape: no .env or .env.* file
  // (examples included) and no .git, at ANY depth. Build output is not clean
  // by itself: `next build` with output: "standalone" copies the project's
  // .env files into .next/standalone/, and server.js loads them at startup.
  return {
    kind: chosen.kind,
    source: chosen.source,
    via: chosen.via,
    path: chosen.path,
    note: selection.note ?? null,
    ...(selection.dirMissing ? { dirMissing: selection.dirMissing } : {}),
    removed: scrubArtifact(stagingDir, { kind: chosen.kind }),
  };
}

// attestationSummary — the test record as hosting reads it: how many
// scenarios, how many have a real test (covered), passed and failed, when it
// ran. null when there is no readable record.
export function attestationSummary(record) {
  if (!record || typeof record !== 'object' || !Array.isArray(record.scenarios)) return null;
  const list = record.scenarios.filter((s) => s && typeof s === 'object');
  const count = (status) => list.filter((s) => s.status === status).length;
  return {
    version: Number.isInteger(record.version) ? record.version : 2,
    scenarios: list.length,
    // A real test ran: passed, failed, or passed with changed checks.
    covered: count('passed') + count('failed') + count('changed-checks'),
    passed: count('passed'),
    failed: count('failed') + count('changed-checks'),
    ranAt: typeof record.ranAt === 'string' ? record.ranAt : '',
  };
}

// scrubArtifact removes local-only files from a staged artifact, at any depth:
// every .env and .env.* (templates like .env.example too: the running app
// never needs them, and people do put real values in them), every .git, and
// every .piezas (Piezas's own records: the test record travels as deploy
// form fields, never inside the app). A static artifact is the public web
// root, so there every dot-folder goes except .well-known. Symlinks are
// removed as entries, never followed. Returns the removed paths, relative to
// the artifact root, for the one-line notice.
export function scrubArtifact(root, { kind } = {}) {
  const removed = [];
  const walk = (dir) => {
    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      const dotDir = kind === 'static' && entry.isDirectory() && entry.name.startsWith('.') && entry.name !== '.well-known';
      if (entry.name === '.git' || entry.name === '.piezas' || entry.name === '.env' || entry.name.startsWith('.env.') || dotDir) {
        rmSync(full, { recursive: true, force: true });
        removed.push(relative(root, full));
      } else if (entry.isDirectory() && !entry.isSymbolicLink()) {
        walk(full);
      }
    }
  };
  walk(root);
  return removed.sort();
}

// detectStaleBuild (CLI-1): `deploy` ships the LAST build as-is — it never
// builds. That contract is invisible in the happy path (users build right
// before deploying) and bites exactly when a dependency or source file changed
// under an existing build: the deploy silently ships old code. Compare the
// build marker's mtime against the newest source file and warn.
// Returns { stale, buildPath, buildMtimeMs, newestSourcePath, newestSourceMtimeMs }
// or null when there is no separate build to compare (no artifact yet, or the
// project root IS the artifact so "source vs build" is meaningless).
export function detectStaleBuild(projectDir, options = {}, selection = selectArtifact(projectDir, options)) {
  // The build marker is the folder selectArtifact picked (what deploy ships).
  // When no build uses Piezas (deploy stops before this), fall back to the
  // first build in order so the check still answers on its own.
  const pick = selection.status === 'ok' ? selection.chosen
    : selection.status === 'no-piezas-build' ? selection.candidates[0]
      : selection.status === 'wrong-folder' ? selection.chosen : null;
  // The project root IS the source: "source vs build" is meaningless there,
  // however it was picked (discovery, --dir ., deploy.dir ".").
  if (!pick || !pick.kind || resolve(pick.path) === resolve(projectDir)) return null;
  const buildPath = resolve(pick.path, pick.kind === 'server' ? 'server.js' : 'index.html');
  const excludeDir = pick.path;
  const buildMtimeMs = statSync(buildPath).mtimeMs;

  // Newest source file: walk the project, skipping build outputs and noise.
  // Bounded (files + depth) so a huge tree can't stall the deploy.
  const skip = new Set([...DEFAULT_EXCLUDED_DIRS, '.vercel', '.cache']);
  let newest = { path: null, mtimeMs: 0 };
  let budget = 4000;
  const walk = (d, depth) => {
    if (budget <= 0 || depth > 8) return;
    let entries;
    try { entries = readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (budget-- <= 0) return;
      const full = join(d, entry.name);
      if (entry.isDirectory()) {
        if (skip.has(entry.name) || (excludeDir && full === excludeDir)) continue;
        walk(full, depth + 1);
      } else if (entry.isFile()) {
        if (entry.name === '.env' || entry.name.startsWith('.env.')) continue;
        if (!TEXT_EXTENSIONS.has(extname(entry.name))) continue;
        try {
          const m = statSync(full).mtimeMs;
          if (m > newest.mtimeMs) newest = { path: full, mtimeMs: m };
        } catch { /* raced away */ }
      }
    }
  };
  walk(projectDir, 0);
  if (!newest.path) return null;

  // 2s slack: build outputs are written moments after the last source touch.
  return {
    stale: newest.mtimeMs > buildMtimeMs + 2000,
    buildPath,
    buildMtimeMs,
    newestSourcePath: newest.path,
    newestSourceMtimeMs: newest.mtimeMs,
  };
}

// sdkVersionNudge (CLI-1): a fixed @piezas/sdk only reaches production when the
// app updates + rebuilds + redeploys — and nothing tells users a fix exists.
// Best-effort, never blocks: any failure (offline, timeout, no dep) => null.
export async function sdkVersionNudge(projectDir, fetchFn = fetch) {
  let installed;
  try {
    const pkg = readJsonFile(resolve(projectDir, 'package.json'));
    const spec = pkg.dependencies?.['@piezas/sdk'] ?? pkg.devDependencies?.['@piezas/sdk'];
    if (!spec) return null;
    // Local/workspace links track the repo, not npm — a registry nudge is noise.
    if (/^(file:|link:|workspace:)/.test(spec)) return null;
    installed = readJsonFile(
      resolve(projectDir, 'node_modules', '@piezas', 'sdk', 'package.json'),
    ).version;
    if (!installed) return null;
  } catch { return null; }

  try {
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), 2000);
    const res = await netFetch(fetchFn, 'https://registry.npmjs.org/@piezas/sdk/latest', {
      signal: ac.signal,
      headers: { Accept: 'application/json' },
    });
    clearTimeout(timer);
    if (!res.ok) return null;
    const latest = (await res.json())?.version;
    if (!latest) return null;
    const lt = (a, b) => {
      const pa = String(a).split('.').map(Number);
      const pb = String(b).split('.').map(Number);
      for (let i = 0; i < 3; i++) {
        if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) < (pb[i] || 0);
      }
      return false;
    };
    if (!lt(installed, latest)) return null;
    return (
      `  ℹ @piezas/sdk ${installed} is installed; ${latest} is available with fixes.\n` +
      `     npm install @piezas/sdk@latest   then rebuild and deploy again.`
    );
  } catch { return null; }
}

// piezasEvidence: the shared apps server hosts PIEZAS apps, not arbitrary
// sites. A real Piezas app leaves fingerprints in its build — the traced
// @piezas/sdk in standalone output, or api.piezas.ai / PIEZAS_API_KEY
// references in its code. This client check gives instant feedback; the
// server runs the same check authoritatively.
// Returns true (found), false (scanned, none) or 'unknown' (part of the
// folder couldn't be read — a dangling symlink, a permission error — and
// nothing was found in the rest). 'unknown' never counts as evidence when
// choosing which folder ships.
const EVIDENCE_SKIP = new Set(['node_modules', '.git', '.piezas', '.claude', '.codex']);
export function piezasEvidence(dir, { installedSdk = true, exclude = [] } = {}) {
  const skipPaths = new Set(exclude.map((p) => resolve(p)));
  if (installedSdk && existsSync(resolve(dir, 'node_modules', '@piezas', 'sdk', 'package.json'))) {
    return true;
  }
  const markers = ['api.piezas.ai', '@piezas/sdk', 'PIEZAS_API_KEY'];
  const exts = new Set(['.js', '.mjs', '.cjs', '.html', '.json']);
  let budget = 64 * 1024 * 1024; // hard scan bound
  let unreadable = false;
  const walk = (d) => {
    let entries;
    try { entries = readdirSync(d); } catch { unreadable = true; return false; }
    for (const entry of entries) {
      // Third-party noise (the SDK is checked above), and Piezas's own tooling
      // folders, which mention Piezas whether or not the app does.
      if (EVIDENCE_SKIP.has(entry)) continue;
      const full = join(d, entry);
      if (skipPaths.has(full)) continue; // another build folder, judged on its own
      let st;
      try { st = statSync(full); } catch { unreadable = true; continue; }
      if (st.isDirectory()) {
        if (walk(full)) return true;
        continue;
      }
      if (!exts.has(extname(entry).toLowerCase()) || st.size > 4 * 1024 * 1024) continue;
      if ((budget -= st.size) < 0) return false;
      let content;
      try { content = readFileSync(full, 'utf-8'); } catch { unreadable = true; continue; }
      if (markers.some((m) => content.includes(m))) return true;
    }
    return false;
  };
  if (walk(dir)) return true;
  return unreadable ? 'unknown' : false;
}

// ---------------------------------------------------------------------------
// Settings by NAME: what the app reads, compared with what the live app has.
// ---------------------------------------------------------------------------
// The owner cannot know which settings a vibe-coded app needs; deploy can find
// out. It reads the NAMES the built code uses (process.env.X), the names the
// manifest declares, and the names (never the values) in the local .env. Names
// the runtime or Piezas hosting provides are not the owner's to set.
export const PROVIDED_SETTING_NAMES = /^(?:NODE_ENV|NODE_OPTIONS|NODE_DEBUG|PORT|HOST|HOSTNAME|PWD|HOME|PATH|TZ|LANG|USER|SHELL|TERM|CI|DEBUG|TMPDIR|TEMP|TMP|NEXT_[A-Z0-9_]*|__NEXT[A-Z0-9_]*|VERCEL[A-Z0-9_]*|TURBOPACK[A-Z0-9_]*|NPM_[A-Z0-9_]*|PIEZAS_REPORT_BUTTON(?:_CHECK)?|PIEZAS_TEST_[A-Z0-9_]*|PIEZAS_[A-Z]+_URL|PIEZAS_API_URL|PIEZAS_APP_URL|PIEZAS_SSO_SECRET|SAAC_[A-Z0-9_]*|MCP_SERVER_NAME)$/;
// Sign-in settings the app runs without (that sign-in button stays off).
export const SIGN_IN_SETTINGS = {
  GOOGLE_CLIENT_ID: 'Google', GOOGLE_CLIENT_SECRET: 'Google',
  MICROSOFT_CLIENT_ID: 'Microsoft', MICROSOFT_CLIENT_SECRET: 'Microsoft', MICROSOFT_TENANT_ID: 'Microsoft',
};
const SETTING_CODE_EXTS = new Set(['.js', '.mjs', '.cjs', '.py']);
// process.env.X (also process?.env?.X, import.meta.env.X, Bun.env.X),
// process.env["X"], Deno.env.get("X"), and Python's os.environ["X"],
// os.environ.get("X"), os.getenv("X").
const SETTING_READ = /(?:process\??\.env|import\.meta\.env|Bun\.env)\??\.([A-Z][A-Z0-9_]*)\b|(?:process\??\.env|os\.environ)\[\s*["'`]([A-Z][A-Z0-9_]*)["'`]\s*\]|(?:Deno\.env\.get|os\.environ\.get|os\.getenv)\(\s*["'`]([A-Z][A-Z0-9_]*)["'`]/g;
// const { A, B: b, C = 'x' } = process.env
const SETTING_DESTRUCTURE = /\{([^{}]{1,2000})\}\s*=\s*process\.env\b/g;
// A read only in development is not needed live: decided by scope, never by
// line (a minified bundle is one line, and React code in it checks NODE_ENV).
// Only a read inside the body of `if (process.env.NODE_ENV !== 'production')`
// (or `=== 'development'` / `'test'`, either side of the test) counts: its
// braces, or its one statement up to `;`, ending within DEV_BLOCK_MAX
// characters. Anything else is required.
const DEV_GUARD = /\bif\s*\(\s*(?:process\.env\.NODE_ENV\s*(?:!==?\s*["'`]production["'`]|===?\s*["'`](?:development|test)["'`])|["'`]production["'`]\s*!==?\s*process\.env\.NODE_ENV|["'`](?:development|test)["'`]\s*===?\s*process\.env\.NODE_ENV)\s*\)\s*/g;
const DEV_BLOCK_MAX = 4000;

// devOnlyBlocks — [start, end) of each body guarded by a development-only
// NODE_ENV test, by a bounded scan. Strings, comments and regex literals are
// skipped by the shared scanner (setup.js skipLiteral), so an apostrophe in a
// comment ("don't") cannot shift the block's end.
export function devOnlyBlocks(text) {
  const blocks = [];
  for (const m of text.matchAll(DEV_GUARD)) {
    const start = m.index + m[0].length;
    const braced = text[start] === '{';
    let depth = 0;
    const stop = Math.min(text.length, start + DEV_BLOCK_MAX);
    for (let i = start; i < stop; i++) {
      const next = skipLiteral(text, i, stop);
      if (next !== i) {
        // A literal or comment that runs past the bound: no block (never a guess).
        if (next >= stop) break;
        i = next - 1;
        continue;
      }
      const ch = text[i];
      if (ch === '{' || ch === '(' || ch === '[') depth++;
      else if (ch === '}' || ch === ')' || ch === ']') {
        depth--;
        if (braced && depth === 0) { blocks.push([start, i]); break; }
        if (depth < 0) break;
      } else if (!braced && depth === 0 && (ch === ';' || ch === '\n')) { blocks.push([start - 1, i]); break; }
    }
  }
  return blocks;
}

// process.env handed whole to something: a config library that validates it
// (zod's .parse(process.env), envalid's cleanEnv(process.env, …), t3-env's
// runtimeEnv: process.env, dotenv-safe), or code the scan cannot follow (a
// spread, an alias, a computed name).
const WHOLE_ENV_SCHEMA = /\.(?:safeParse|parse|parseAsync|safeParseAsync)\(\s*process\.env\s*\)|\bcleanEnv\(\s*process\.env\b|\b(?:experimental__)?runtimeEnv(?:Strict)?\s*:\s*process\.env\b/;
const WHOLE_ENV_OPAQUE = /\.\.\.\s*process\.env\b(?!\s*\.)|[=(,:]\s*process\.env\s*(?=[;,)\n}]|$)|\bprocess\.env\[\s*(?!["'`])[^\]]/m;
const DOTENV_SAFE = /\bdotenv-safe\b/;
// A schema entry: an UPPER_SNAKE key whose value is a validator call
// (z.string(), str(), Joi.string(), v.string(), …; minified names too).
const SCHEMA_ENTRY = /(?:^|[{,\s])["']?([A-Z][A-Z0-9_]+)["']?\s*:\s*(?=[\w$.]*\(|[\w$]+\.[\w$]+)/g;
const SCHEMA_OPTIONAL = /\.(?:optional|nullish|default|catch)\(|\bdefault\s*:|\bdevDefault\s*:/;
// Where a schema object starts: the object literal handed to a schema builder
// (zod/valibot/yup/Joi object, extend, shape, keys), to envalid's cleanEnv or
// to t3-env's createEnv.
const SCHEMA_OBJECT = /\b(?:object|strictObject|looseObject|extend|shape|keys)\(\s*\{|\bcleanEnv\(\s*process\.env\s*,\s*\{|\bcreateEnv\(\s*\{/g;

// schemaObjects — the text of each schema object literal in a file, so a
// bundled file's other UPPER_SNAKE keys (export maps, error codes) are not
// read as settings.
function schemaObjects(text) {
  const out = [];
  for (const m of text.matchAll(SCHEMA_OBJECT)) {
    const start = m.index + m[0].length - 1;
    let depth = 0;
    for (let i = start; i < text.length; i++) {
      const next = skipLiteral(text, i, text.length);
      if (next !== i) { i = next - 1; continue; }
      if (text[i] === '{') depth++;
      else if (text[i] === '}' && --depth === 0) { out.push(text.slice(start, i + 1)); break; }
    }
  }
  return out;
}

// wholeEnvSchema — { schema: {NAME: optional?} | null, opaque, dotenvSafe }
// for one file: the names a config library is given to check, read from the
// object keys passed to it (every validator-shaped UPPER_SNAKE entry in its
// schema objects; none there, in the whole file, so no setting is dropped),
// each optional only when marked so.
export function wholeEnvSchema(text) {
  const schemaUse = WHOLE_ENV_SCHEMA.test(text);
  const dotenvSafe = DOTENV_SAFE.test(text);
  const opaque = !schemaUse && WHOLE_ENV_OPAQUE.test(text.replace(WHOLE_ENV_SCHEMA, ''));
  if (!schemaUse) return { schema: null, opaque, dotenvSafe };
  const schema = {};
  for (const parts of [schemaObjects(text), [text]]) {
    if (Object.keys(schema).length) break;
    for (const part of parts) for (const m of part.matchAll(SCHEMA_ENTRY)) {
      const valueAt = m.index + m[0].length;
      // The value: up to the next , or } at its own depth (strings skipped).
      let depth = 0;
      let end = Math.min(part.length, valueAt + 2000);
      for (let i = valueAt; i < end; i++) {
        const next = skipLiteral(part, i, end);
        if (next !== i) { i = next - 1; continue; }
        const ch = part[i];
        if (ch === '(' || ch === '[' || ch === '{') depth++;
        else if (ch === ')' || ch === ']' || ch === '}') { if (depth === 0) { end = i; break; } depth--; }
        else if (ch === ',' && depth === 0) { end = i; break; }
      }
      const value = part.slice(valueAt, end);
      const name = m[1];
      schema[name] = (schema[name] ?? true) && SCHEMA_OPTIONAL.test(value);
    }
  }
  return { schema, opaque: Object.keys(schema).length === 0, dotenvSafe };
}

// settingNamesInCode — the setting names a built app reads (process.env.X,
// process.env["X"], or destructured from process.env), from its own code only
// (never node_modules), bounded like piezasEvidence. With { devOnly: true }:
// { names, devOnly } where devOnly holds the names read only inside
// development-only blocks.
export function settingNamesInCode(dir, { devOnly: wantDevOnly = false } = {}) {
  const names = new Set();
  const live = new Set();
  // process.env handed whole to a config library: its schema's names
  // (name -> optional?), and whether some use could not be read at all.
  const schema = new Map();
  let opaque = false;
  let dotenvSafe = false;
  let budget = 64 * 1024 * 1024;
  walkLexical(dir, (full) => {
    if (!SETTING_CODE_EXTS.has(extname(full).toLowerCase())) return undefined;
    let size;
    try { size = statSync(full).size; } catch { return undefined; }
    if (size > 4 * 1024 * 1024) return undefined;
    if ((budget -= size) < 0) return 'stop';
    let text;
    try { text = readFileSync(full, 'utf-8'); } catch { return undefined; }
    const blocks = devOnlyBlocks(text);
    const inDevBlock = (at) => blocks.some(([a, b]) => at > a && at < b);
    // A comment line reads nothing.
    // (A minified line that opens with a closed /*! licence */ is code.)
    const onCommentLine = (at) => {
      const before = text.slice(text.lastIndexOf('\n', at) + 1, at);
      return /^\s*(?:\/\/|#|\*(?!\/))/.test(before) || (/^\s*\/\*/.test(before) && !before.includes('*/'));
    };
    const add = (name, at) => {
      if (onCommentLine(at)) return;
      names.add(name);
      if (!inDevBlock(at)) live.add(name);
    };
    for (const m of text.matchAll(SETTING_READ)) add(m[1] ?? m[2] ?? m[3], m.index);
    for (const m of text.matchAll(SETTING_DESTRUCTURE)) {
      for (const part of m[1].split(',')) {
        const name = part.split(/[:=]/)[0].trim();
        if (/^[A-Z][A-Z0-9_]*$/.test(name)) add(name, m.index);
      }
    }
    if (/process\.env/.test(text) || DOTENV_SAFE.test(text)) {
      const whole = wholeEnvSchema(text);
      if (whole.schema) for (const [name, optional] of Object.entries(whole.schema)) schema.set(name, (schema.get(name) ?? true) && optional);
      opaque ||= whole.opaque;
      dotenvSafe ||= whole.dotenvSafe;
    }
    return undefined;
  });
  const sorted = [...names].sort();
  if (!wantDevOnly) return sorted;
  return {
    names: sorted,
    devOnly: sorted.filter((n) => !live.has(n)),
    schema: Object.fromEntries([...schema.entries()].sort()),
    opaque,
    dotenvSafe,
  };
}

// localSettingNames — the NAMES in the project's local .env files. The values
// are never kept: each line is matched for its name and dropped.
export const LOCAL_SETTING_FILES = ['.env', '.env.local', '.env.production'];
// Names here are a hint, not a requirement: development-only or examples.
export const HINT_SETTING_FILES = ['.env.development', '.env.development.local', '.env.example', '.env.sample', '.env.template'];
export function localSettingNames(projectDir, files = LOCAL_SETTING_FILES) {
  const names = new Set();
  let read = false;
  for (const file of files) {
    let text;
    try { text = readFileSync(join(projectDir, file), 'utf-8'); } catch { continue; }
    read = true;
    for (const line of text.split(/\r?\n/)) {
      const m = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=/.exec(line);
      if (m) names.add(m[1]);
    }
    text = null;
  }
  return { names: [...names].sort(), read };
}

// settingsNeeded — which settings this build needs on the live app (by name):
// required = declared required, plus names the code reads that the local .env
// also has; optional = declared optional, plus sign-in settings the code reads.
// PIEZAS_API_KEY is handled on its own (deploy adds it when it is missing).
// Every other name the code reads (only in .env.development / .env.example,
// in no local file at all, or read only in development) goes to the optional
// line: said once, never a pause. A static build is not scanned: a setting on
// the live app cannot reach code that runs in the browser.
export function settingsNeeded(projectDir, stagedDir, manifest = null, { kind } = {}) {
  const declared = (list) => (Array.isArray(list) ? list.filter((k) => typeof k === 'string' && k.trim()).map((k) => k.trim()) : []);
  const requiredEnv = declared(manifest?.deploy?.requiredEnv);
  const optionalEnv = new Set(declared(manifest?.deploy?.optionalEnv));
  const scan = stagedDir && kind !== 'static';
  const { names: code, devOnly, schema = {}, opaque = false, dotenvSafe = false } = scan ? settingNamesInCode(stagedDir, { devOnly: true }) : { names: [], devOnly: [] };
  const local = scan ? localSettingNames(projectDir) : { names: [], read: false };
  const localSet = new Set(local.names);
  const devOnlySet = new Set(devOnly);
  const ours = (k) => k !== 'PIEZAS_API_KEY' && !PROVIDED_SETTING_NAMES.test(k);
  const required = new Set(requiredEnv.filter((k) => k !== 'PIEZAS_API_KEY'));
  for (const k of code) if (localSet.has(k) && ours(k) && !optionalEnv.has(k) && !SIGN_IN_SETTINGS[k] && !devOnlySet.has(k)) required.add(k);
  // A config library checks process.env as a whole: every name its schema
  // declares is required (the app stops without it) unless marked optional.
  for (const [k, isOptional] of Object.entries(schema)) if (ours(k) && !isOptional && !optionalEnv.has(k)) required.add(k);
  // dotenv-safe requires every name in .env.example.
  if (dotenvSafe) for (const k of localSettingNames(projectDir, ['.env.example']).names) if (ours(k) && !optionalEnv.has(k)) required.add(k);
  const optional = new Set([...optionalEnv].filter((k) => ours(k) && !required.has(k)));
  for (const k of code) if (ours(k) && !required.has(k)) optional.add(k);
  for (const [k, isOptional] of Object.entries(schema)) if (isOptional && ours(k) && !required.has(k)) optional.add(k);
  // process.env handed over in a way the scan cannot read: the local .env's
  // names may be needed (said in the optional line, never a pause).
  const mayNeed = opaque ? local.names.filter((k) => ours(k) && !required.has(k) && !optional.has(k)) : [];
  return { required: [...required].sort(), optional: [...optional].sort(), mayNeed, readLocal: local.read, scanned: Boolean(scan), declaredRequired: requiredEnv };
}

// optionalSettingsLine — one line, no pause, for optional settings the live
// app does not have yet.
export function optionalSettingsLine(names) {
  const providers = [...new Set(names.map((k) => SIGN_IN_SETTINGS[k]).filter(Boolean))];
  const what = providers.length && names.every((k) => SIGN_IN_SETTINGS[k])
    ? `${joinWords(providers)} sign-in stays off until ${names.length === 1 ? 'it is' : 'they are'} set.`
    : `The parts that use ${names.length === 1 ? 'it stay' : 'them stay'} off until ${names.length === 1 ? 'it is' : 'they are'} set.`;
  return `Not set yet (optional): ${names.join(', ')}. ${what}`;
}

// ruleAnswerGone — (key) => is the broken rule this answer was about gone
// from this build? Evidence only:
// - a finding of the full local scan (its key names the kind of leak): that
//   scan read the file (or the file is not in the build) and did not find it;
// - a server response that lists its findings (hardNo is an array) without it;
// - the file it names is not in the build any more;
// - a local database the local scan, which found none at all, would have seen.
// A response with no findings list (a 201 carries none) is no evidence: a
// rule only the server finds keeps its answer.
export function ruleAnswerGone({ localFindings = [], serverFindings, staging, scanned = new Set() }) {
  const local = new Set(hardNoItems(localFindings).map((i) => i.key));
  const listed = Array.isArray(serverFindings) ? new Set(hardNoItems(serverFindings).map((i) => i.key)) : null;
  const localDb = localFindings.some((f) => f.rule === 'local-database');
  return (key) => {
    if (local.has(key) || listed?.has(key)) return false;
    const [rule, path = '', category, digest] = String(key).split('\u0000');
    const inBuild = Boolean(path) && Boolean(staging) && existsSync(join(staging, path));
    // Only the local scan's own keys (they always carry a digest) are judged
    // by what that scan read.
    if (category && digest) return !inBuild || scanned.has(path);
    if (listed) return true;
    if (!inBuild) return true;
    return rule === 'local-database' && !localDb;
  };
}

// mayNeedSettingsLine — the local .env's names, when the app hands its
// settings to code the scan cannot read: maybe needed, never a pause.
export function mayNeedSettingsLine(names) {
  return `Not set yet, and may be needed (Piezas could not tell from the code): ${names.join(', ')}.`;
}

// hasPiezasEvidence: the boolean gate form. Fails OPEN — an 'unknown' scan
// counts as evidence — so it only suits a gate that must not block on
// scanning trouble (the server re-checks). Never use it to choose a folder.
export function hasPiezasEvidence(dir, opts = {}) {
  return piezasEvidence(dir, opts) !== false;
}

// detectOtherRuntime names the ecosystem when a project clearly isn't a
// Node/static app, so the "can't deploy" message can be honest and specific
// instead of offering Next.js advice to a Python developer.
export function detectOtherRuntime(projectDir) {
  const signals = [
    ['requirements.txt', 'Python'],
    ['pyproject.toml', 'Python'],
    ['Pipfile', 'Python'],
    ['go.mod', 'Go'],
    ['Cargo.toml', 'Rust'],
    ['Gemfile', 'Ruby'],
    ['composer.json', 'PHP'],
    ['pom.xml', 'Java'],
    ['build.gradle', 'Java'],
  ];
  for (const [file, runtime] of signals) {
    if (existsSync(resolve(projectDir, file))) return runtime;
  }
  return null;
}

// findNextConfig returns the Next config the project ACTUALLY has (first match
// wins, the way Next itself resolves it). Both the deploy diagnosis and the
// doctor preflight name that exact file — generic advice about "next.config" is
// what left users editing the wrong thing.
export const NEXT_CONFIG_FILES = ['next.config.js', 'next.config.mjs', 'next.config.ts'];

export function findNextConfig(projectDir) {
  for (const name of NEXT_CONFIG_FILES) {
    const path = resolve(projectDir, name);
    if (!existsSync(path)) continue;
    let text = '';
    try { text = readFileSync(path, 'utf-8'); } catch { /* unreadable -> treat as empty */ }
    return { name, path, text };
  }
  return null;
}

// diagnoseNextBuild explains THE deploy-day trap: `npm run build` succeeds,
// `next dev`/`next start` work for days, but next.config never set
// output: 'standalone' — so no .next/standalone/server.js exists and there is
// nothing to ship. Nothing before deploy day needs that line, which is exactly
// why it goes missing. Returns null unless a Next build ran (.next/ present)
// AND a config file exists to name; the generic guidance covers everything else.
export function diagnoseNextBuild(projectDir) {
  if (!existsSync(resolve(projectDir, '.next'))) return null;
  const config = findNextConfig(projectDir);
  if (!config) return null;
  return {
    status: config.text.includes('standalone') ? 'rebuild-needed' : 'standalone-missing',
    configFile: config.name,
  };
}

// collectExplicitEnv: deploy never sends a value from the local .env file —
// the hosted runtime's environment lives in the cloud store (console-managed,
// or staged at app creation). The only env that travels with a deploy is what
// the user consciously types as --env KEY=VALUE (the Heroku config:set
// posture). The .env is opened for one thing only: its setting NAMES
// (localSettingNames), to tell the owner which ones the live app lacks.
// askReportButton — this deploy's Report a problem setting. Never a question
// (Spec 1-A, #33-34): the stored manifest value is the answer (first deploy:
// on). `--report-button on|off` (or `piezas report-button on|off`) changes it
// and saves it as the next default. Returns { ok: true, value: 'on'|'off' }
// or { ok: false, status } for a flag that is neither.
export async function askReportButton(projectDir, options = {}) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  let manifest = null;
  try { manifest = readJsonFile(manifestPath); } catch { manifest = null; }
  const last = manifest?.reportButton === false ? 'off' : 'on';
  let value = last;
  if (options.reportButton !== undefined) {
    value = String(options.reportButton).trim().toLowerCase();
    if (value !== 'on' && value !== 'off') {
      log('  --report-button must be on or off.\n');
      return { ok: false, status: 'report-button-invalid' };
    }
  }
  if (manifest) {
    const before = manifest.reportButton;
    if (value === 'off') manifest.reportButton = false;
    else delete manifest.reportButton;
    if (before !== manifest.reportButton) writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  }
  // Said only when it is off (the owner's choice) or just changed.
  if (value === 'off') log('  Report a problem button: off, as you chose.');
  else if (value !== last) log('  Report a problem button: on.');
  // `piezas report-button on|off` changed it since the last deploy: the live
  // app gets the new value with the next one.
  return { ok: true, value, explicit: options.reportButton !== undefined, changed: manifest?.reportButtonUnsent === true };
}

// clearReportButtonUnsent — the live app has the stored value now.
function clearReportButtonUnsent(projectDir) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  try {
    const manifest = readJsonFile(manifestPath);
    if (manifest?.reportButtonUnsent === undefined) return;
    delete manifest.reportButtonUnsent;
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  } catch { /* best effort */ }
}

export function collectExplicitEnv(options) {
  const sent = {};
  const pairs = Array.isArray(options.envPairs) ? options.envPairs : options.envPairs ? [options.envPairs] : [];
  for (const pair of pairs) {
    const m = /^([A-Za-z_][A-Za-z0-9_]*)=([\s\S]*)$/.exec(String(pair));
    if (m) sent[m[1]] = m[2];
  }
  return sent;
}

// mintAndStageHostedKey mints a live API key for the app (the same
// control-plane call init uses) and stages it into the HOSTED env store —
// bound by durable id, value never shown, never written to any local file.
// Returns { ok, stage, status }: ok=true when the hosted env ends up holding
// PIEZAS_API_KEY; on failure, `stage` names which half broke ('mint' at the
// control plane, or 'stage' at the apps-server) and `status` is its HTTP code,
// so callers can tell the user WHY instead of a bare "could not mint".
//
// Staged to `slug`, the same slug the deploy uses (deploySlugFor). A key that
// was minted but could not be staged is revoked at once; if even that fails,
// its id (never its value) is kept in .piezas/key-mint.json (closed to the AI
// by the guard). The next run removes it before minting again, but only a key
// that is this app's: the id must look like a key id and the control plane
// must say the key belongs to this app (partitionId), else the record is
// dropped and nothing is revoked. A removal that fails stops the minting
// (no second key while the first is live), and the owner is told plainly.
export const KEY_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{2,127}$/;
function readKeyMint(projectDir) {
  try { return JSON.parse(readFileSync(join(projectDir, STATE_DIR, KEY_MINT_FILE), 'utf-8')); } catch { return null; }
}
function writeKeyMint(projectDir, data) {
  try {
    if (!data) { rmSync(join(projectDir, STATE_DIR, KEY_MINT_FILE), { force: true }); return; }
    mkdirSync(join(projectDir, STATE_DIR), { recursive: true });
    writeFileSync(join(projectDir, STATE_DIR, KEY_MINT_FILE), `${JSON.stringify(data, null, 2)}\n`);
  } catch { /* best effort */ }
}

export async function mintAndStageHostedKey(linked, credentials, options, fetchFn, { slug, projectDir } = {}) {
  const env = options.env ?? process.env;
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const keysUrl = `${adminBaseUrl(apiBase)}/v1/tenants/${credentials.tenantId}/api-keys`;
  const http = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const revoke = async (keyId) => {
    if (!keyId) return 0;
    try {
      const res = await fetchJson(fetchFn, `${keysUrl}/${encodeURIComponent(keyId)}`, { ...http, method: 'DELETE' });
      return res.status === 200 || res.status === 204 || res.status === 404 ? true : res.status;
    } catch {
      return 0;
    }
  };
  // A key left behind by an earlier failed try: remove it before minting,
  // only once it is known to be this app's.
  const left = projectDir ? readKeyMint(projectDir) : null;
  // A key minted with no id to remove it by: no second one is minted while
  // it may be live (the owner removes it, or adds the key, in the console).
  if (left?.orphan === true && left.appId === linked.appId) return { ok: false, stage: 'revoke', status: 0, pending: true, orphan: true };
  if (left && left.orphan !== true) {
    const keyId = typeof left.keyId === 'string' ? left.keyId : '';
    let owner = null; // 'this' | 'other' | 'gone' | null (could not tell)
    if (left.appId !== linked.appId || !KEY_ID_PATTERN.test(keyId)) owner = 'other';
    else {
      // The admin API serves no GET for one key (only DELETE on
      // /api-keys/{keyId}): the tenant's list (ApiKeyListResponse: id,
      // partitionId, revokedAt) says whose it is.
      try {
        const res = await fetchJson(fetchFn, keysUrl, http);
        const keys = res.status === 200 && Array.isArray(res.data?.data) ? res.data.data : null;
        if (keys) {
          const found = keys.find((k) => k && k.id === keyId);
          if (!found || found.revokedAt) owner = 'gone';
          else owner = found.partitionId === linked.appId ? 'this' : 'other';
        }
      } catch { owner = null; }
    }
    if (owner === 'other' || owner === 'gone') {
      writeKeyMint(projectDir, null);
      if (owner === 'other' && !ownerAtTerminal(options)) log('  (For the AI: .piezas/key-mint.json named a key that is not this app\'s; it was ignored and nothing was removed.)');
    } else {
      const removed = owner === 'this' ? await revoke(keyId) : 0;
      if (removed !== true) {
        writeKeyMint(projectDir, { ...left, failedAt: new Date().toISOString() });
        return { ok: false, stage: 'revoke', status: typeof removed === 'number' ? removed : 0, pending: true };
      }
      writeKeyMint(projectDir, null);
    }
  }
  const minted = await fetchJson(fetchFn, keysUrl, {
    ...http,
    method: 'POST',
    body: { name: linked.appName, environment: 'live', partitionId: linked.appId },
  });
  if (minted.status !== 201 || typeof minted.data?.key !== 'string' || !minted.data.key) {
    return { ok: false, stage: 'mint', status: minted.status };
  }
  const base = appsBaseUrl(options, env);
  let stagedStatus = 0;
  try {
    const stagedRes = await fetchJson(fetchFn,
      `${base}/v1/deployments/${slug ?? slugifyAppName(linked.appName)}/env?appId=${encodeURIComponent(linked.appId)}`, {
        token: credentials.cliToken,
        method: 'PATCH',
        body: { set: { PIEZAS_API_KEY: minted.data.key } },
        timeoutMs: 8000,
      });
    stagedStatus = stagedRes.status;
  } catch { stagedStatus = 0; }
  if (stagedStatus === 200) return { ok: true, stage: 'stage', status: 200 };
  const keyId = typeof minted.data?.id === 'string' ? minted.data.id : null;
  const revoked = (await revoke(keyId)) === true;
  if (!revoked && projectDir) {
    writeKeyMint(projectDir, keyId
      ? { appId: linked.appId, keyId, at: new Date().toISOString() }
      : { appId: linked.appId, keyId: null, orphan: true, ...(typeof minted.data?.keyPrefix === 'string' ? { keyPrefix: minted.data.keyPrefix } : {}), at: new Date().toISOString() });
  }
  return { ok: false, stage: 'stage', status: stagedStatus, revoked, ...(!revoked ? { pending: true } : {}) };
}

// What the owner reads when the app's own key could not be added (two short
// sentences each), and what the AI reads.
export const KEY_MINT_TEXT = {
  signIn: 'Nothing was put live: your Piezas sign-in has run out. Sign in again, then deploy again.',
  failed: (page) => 'Nothing was put live: the app\'s own Piezas key could not be added. ' +
    `Add one on the app page in the Piezas console: ${page}`,
  forAI: (mint) => {
    if (mint.stage === 'revoke') {
      return `(For the AI: a key Piezas minted earlier for this app ${mint.orphan ? 'came back with no id to remove it by' : `could not be removed (HTTP ${mint.status})`}, so no new key is minted. ` +
        'Do not retry the deploy; pass on the owner line above. Once the owner adds the key on the app page, deploy again.)';
    }
    if (mint.status === 401 || mint.status === 403) return '(For the AI: run `piezas login` (the owner signs in in the browser), then deploy again.)';
    return `(For the AI: the app's key could not be ${mint.stage === 'mint' ? 'created' : 'staged'} (HTTP ${mint.status}). Deploy again once; if it fails again, pass on the owner line above.` +
      `${mint.pending ? ' A minted key could not be removed; the next deploy tries to remove it and mints nothing until it is gone.' : ' No unused key was left behind.'})`;
  },
};

// ensureAppLink resolves this project's durable app identity (the control
// plane app/partition UUID), EB-style: prefer the binding already recorded in
// piezas.manifest.json (deploy.appId, written by init); otherwise pull the
// tenant's app NAMES from the platform and let the user pick — confirming
// identity from the web without any secret involved — then persist the
// binding. Returns null when unlinked and unable to ask.
// LINK_TEXT — what the owner and the AI read when a deploy will not replace a
// live version this project did not put there.
export const LINK_TEXT = {
  live: (name) => `Your app "${name}" already has a live version this project did not put there, so nothing was linked. To replace it, reply "link to ${name}".`,
  unknown: (name) => `Piezas could not check whether your app "${name}" already has a live version, so nothing was linked. To link it anyway, reply "link to ${name}".`,
  forAI: (name) => `(For the AI: only the owner can link this project to "${name}": they reply "link to ${name}" in the chat, or confirm at their own terminal. ` +
    'Tell them so in one sentence, and never edit piezas.manifest.json for this. If they say it is a different app, ask them what to call the new one.)',
};

export async function ensureAppLink(projectDir, options, credentials, fetchFn) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  let manifest = null;
  try { manifest = readJsonFile(manifestPath); } catch { /* no manifest yet */ }
  const env = options.env ?? process.env;
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const ownerHere = ownerAtTerminal(options);
  const promptFn = options.promptFn ?? promptViaTerminal;
  const toSlug = (n) => String(n).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  // What hosting itself says about the app's live version: 'none' (nothing
  // live), 'here' (this project put it there: the hash of the token it wrote
  // on its first deploy), 'elsewhere' (another project did), 'no-record'
  // (hosting keeps no such record), 'unknown' (could not look).
  const hostingSays = async (app) => {
    try {
      const res = await fetchJson(fetchFn, `${appsBaseUrl(options, env)}/v1/deployments/${encodeURIComponent(app.slug ?? toSlug(app.name))}?appId=${encodeURIComponent(app.id)}`, httpOptions);
      if (res.status === 404) return 'none';
      if (res.status !== 200) return 'unknown';
      const here = deployedHereByHosting(projectDir, app.id, res.data);
      return here === null ? 'no-record' : here ? 'here' : 'elsewhere';
    } catch {
      return 'unknown';
    }
  };
  // The live version is not this project's: replaced only on the owner's own
  // word (their terminal, or their "link to <name>" in the chat).
  const confirmReplace = async (app, live, persist) => {
    if (ownerChoseLink(projectDir, app.id)) return persist();
    if (ownerHere) {
      const q = live === 'live'
        ? `  "${app.name}" already has a live version that this project did not put there. Type yes to replace it: `
        : `  Piezas could not check whether "${app.name}" already has a live version. Type yes to link this project to it anyway: `;
      const answer = String((await promptFn(q)) ?? '').trim().toLowerCase();
      if (/^(?:y|yes)$/.test(answer)) return persist();
      log('  Nothing was linked.\n');
      return null;
    }
    writeLinkQuestion(projectDir, app);
    log(`  ${live === 'live' ? LINK_TEXT.live(app.name) : LINK_TEXT.unknown(app.name)}`);
    log(`  ${LINK_TEXT.forAI(app.name)}\n`);
    if (relayAllowed(deployRecordRoot(projectDir))) log(`  (For the AI: ${DEPLOY_RELAY_NOTE})\n`);
    return null;
  };

  if (manifest?.deploy?.appId) {
    const linked = { appId: manifest.deploy.appId, appName: manifest.appName || basename(projectDir) };
    // Hosting's record wins over the manifest: a live version another project
    // put there is not replaced on the manifest's word alone. Without such a
    // record (older hosting) the manifest stands, as before.
    const app = { id: linked.appId, name: linked.appName, slug: deploySlugFor(projectDir, options) };
    if (await hostingSays(app) === 'elsewhere') return confirmReplace(app, 'live', () => linked);
    return linked;
  }

  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const adminBase = adminBaseUrl(apiBase);
  // LIST via my-apps: it returns the CALLER's apps — an admin sees all, a
  // developer sees only granted apps — so the picker works for both roles with
  // no client-side role logic. CREATE still targets /partitions (admin-only).
  const myAppsUrl = `${adminBase}/v1/tenants/${credentials.tenantId}/my-apps`;
  const partitionsUrl = `${adminBase}/v1/tenants/${credentials.tenantId}/partitions`;
  let apps = [];
  let listFailed = false;   // a genuine network failure — the platform was unreachable
  let authFailed = false;   // 401/403 — the session isn't authorized or has expired
  try {
    const res = await fetchJson(fetchFn, myAppsUrl, httpOptions);
    if (res.status === 200 && Array.isArray(res.data?.data)) apps = res.data.data;
    else if (res.status === 401 || res.status === 403) authFailed = true;
    else listFailed = true;
  } catch {
    listFailed = true;
  }

  const interactive = options.interactive && options.promptFn !== null;

  // Never ask what the names already say (Spec Part 2, #9), but never link by
  // a guess either: only an explicit --app, or the app name init wrote into
  // the manifest, links with no prompt. Even then, an app that already runs a
  // live version this project never deployed is not taken over silently.
  const wanted = typeof options.app === 'string' && options.app.trim() ? options.app.trim() : null;
  const matchOf = (name) => {
    const hits = apps.filter((a) => a.slug === toSlug(name) || a.name === name);
    return hits.length === 1 ? hits[0] : null;
  };
  // 'live' | 'unknown' (could not look) | null (nothing live, or this project
  // put it there). Hosting's own record decides; without one, the manifest's
  // record of an earlier deploy (its fields are closed to the AI's edits).
  const neverDeployedHere = !manifest?.deploy?.url;
  const liveElsewhere = async (app) => {
    const says = await hostingSays(app);
    if (says === 'none' || says === 'here') return null;
    if (says === 'elsewhere') return 'live';
    if (!neverDeployedHere) return null;
    return says === 'no-record' ? 'live' : 'unknown';
  };
  // An app with a live version this project never deployed is replaced only
  // on the owner's own word: never from an AI run on its own, whether the
  // name came from --app or from the manifest.
  const linkUnlessLiveElsewhere = async (hit) => {
    const live = await liveElsewhere(hit);
    if (!live) return persistAppLink(manifestPath, manifest, hit);
    return confirmReplace(hit, live, () => persistAppLink(manifestPath, manifest, hit));
  };
  if (wanted) {
    const hit = matchOf(wanted);
    if (hit) return await linkUnlessLiveElsewhere(hit);
  } else if (manifest?.appName) {
    const hit = matchOf(manifest.appName);
    if (hit) return await linkUnlessLiveElsewhere(hit);
  } else {
    // Only the folder name matches: a guess ("website", "app"). Ask at the
    // terminal; otherwise stop with a plain line.
    const hit = matchOf(basename(projectDir));
    if (hit) {
      if (ownerChoseLink(projectDir, hit.id)) return persistAppLink(manifestPath, manifest, hit);
      const live = await liveElsewhere(hit);
      if (ownerHere) {
        const answer = String((await promptFn(`  Is this project your app "${hit.name}"?${live ? ' Its live version will be replaced.' : ''} Type yes to link it: `)) ?? '').trim().toLowerCase();
        if (/^(?:y|yes)$/.test(answer)) return persistAppLink(manifestPath, manifest, hit);
      } else {
        log(`  This folder's name matches your app "${hit.name}", but this project was never linked to it, so nothing was linked.`);
        if (live) {
          writeLinkQuestion(projectDir, hit);
          log(`  ${LINK_TEXT.forAI(hit.name)}\n`);
          if (relayAllowed(deployRecordRoot(projectDir))) log(`  (For the AI: ${DEPLOY_RELAY_NOTE})\n`);
        } else {
          log(`  (For the AI: ask the owner whether this project is "${hit.name}"; if it is, deploy with --app "${hit.name}". Never pick it yourself.)\n`);
        }
        return null;
      }
    }
  }

  // createApp: a fresh account (or a deliberate choice) creates the app right
  // here — same control-plane call init uses. No key is minted (that's init's
  // job); hosting only needs the app record to exist.
  const createApp = async () => {
    // The name is never asked (Spec Part 2, #10): it can be changed in the console.
    const name = wanted || manifest?.appName || basename(projectDir);
    log(`  Creating the app "${name}" (you can rename it any time in the Piezas console).`);
    const res = await fetchJson(fetchFn, partitionsUrl, { ...httpOptions, method: 'POST', body: { name } });
    if (res.status === 201 && res.data?.id) {
      log(`  Created app "${res.data.name}" — it's in your console now.`);
      const link = persistAppLink(manifestPath, manifest, res.data);
      // App creation provisions the key — same behavior as init and the
      // console welcome flow. The hosted env holds it before first boot.
      if (link) {
        const staged = await mintAndStageHostedKey(link, credentials, options, fetchFn, { slug: deploySlugFor(projectDir, options), projectDir });
        if (staged.ok) {
          log('  Minted its API key and staged it in the hosted environment.');
          log('  (For local development, run `npx piezas init` to write a key into .env.)');
          return { ...link, keyStaged: true };
        }
        log(`  Could not mint/stage its API key automatically (${staged.stage} HTTP ${staged.status}) — you'll be asked before deploy.`);
      }
      return link;
    }
    if (res.status === 401) {
      log('  Your session has expired — run `npx piezas login`, then retry.\n');
      return null;
    }
    if (res.status === 403) {
      // Creating an app is admin-only. A developer who reaches here (empty list,
      // or chose "+ Create") is NOT looped on a dead end — tell them the truth
      // and exactly what unblocks them. Point at an admin; don't imply self-serve.
      log('  Only an admin can create an app, so it can\'t be created from here.');
      log('  Ask an admin to create it (in the console, or from their own CLI) and grant');
      log('  you access. Once you\'re granted, `npx piezas deploy` will find it here.\n');
      return null;
    }
    if (res.status === 409) {
      // Name already taken in this tenant — link to the existing app instead.
      try {
        const l = await fetchJson(fetchFn, myAppsUrl, httpOptions);
        const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
        const hit = (l.data?.data ?? []).find((a) => a.slug === slug || a.name === name);
        if (hit) {
          log(`  App "${hit.name}" already exists — linking this project to it.`);
          return persistAppLink(manifestPath, manifest, hit);
        }
      } catch { /* fall through */ }
    }
    log(`  Could not create the app (HTTP ${res.status}) — try again, or create it in the console.\n`);
    return null;
  };

  // Honest, distinct outcomes when the list yielded nothing to auto-pick from.
  // These are checked in order and each is DIFFERENT from a network failure:
  //   authFailed → the session, not the connection (never "check your connection")
  //   listFailed → a genuine network/unreachable failure (keep the old copy)
  //   empty list → NOT an error: fall through to create; a developer's create
  //                403s into the honest "ask your admin" message (no dead-end loop).
  if (authFailed) {
    log('  Your Piezas session isn\'t authorized (it may have expired) — run `npx piezas login`, then retry.\n');
    return null;
  }
  if (listFailed) {
    log(`  Could not reach ${apiBase} to look up your apps — check your connection and retry.\n`);
    return null;
  }

  if (!apps.length) {
    // A brand-new account: create it, no question (AI runs included). A
    // developer with no grants yet gets the honest "ask an admin" (403).
    return await createApp();
  }
  if (interactive) {
    log('  Which app is this project? (identity confirmed from your account — nothing is uploaded)');
    apps.forEach((a, i) => log(`    ${i + 1}) ${a.name}`));
    log(`    ${apps.length + 1}) + Create a new app`);
    const answer = String((await promptFn(`  Choose 1-${apps.length + 1}: `)) ?? '').trim();
    const idx = Number(answer) - 1;
    if (Number.isInteger(idx) && idx >= 0 && idx < apps.length) {
      return persistAppLink(manifestPath, manifest, apps[idx]);
    }
    if (idx === apps.length) {
      return await createApp();
    }
  }

  log('  This project is not linked to an app yet.');
  log('  Run `npx piezas deploy` from a terminal (interactive) to link or create one,');
  log('  or your AI tool can link it by setting this project\'s app id (deploy.appId).\n');
  return null;
}

// persistAppLink records the confirmed identity in the manifest.
export function persistAppLink(manifestPath, manifest, app) {
  try {
    const m = manifest ?? {};
    m.appName = app.name;
    m.deploy = { ...(m.deploy || {}), appId: app.id };
    writeFileSync(manifestPath, `${JSON.stringify(m, null, 2)}\n`);
    log(`  Linked to "${app.name}" (${app.id.slice(0, 8)}…) and saved in this project.`);
  } catch { /* linking is a convenience record; deploy still carries the id */ }
  return { appId: app.id, appName: app.name };
}

// persistDeploySlug records the server-assigned slug + URL in the manifest so
// later `deploy --status/--logs/--delete` target the right deployment.
export function persistDeploySlug(projectDir, slug, url) {
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  try {
    const manifest = readJsonFile(manifestPath);
    manifest.deploy = { ...(manifest.deploy || {}), mode: 'mixed', slug, url };
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  } catch {
    // No manifest (deploy outside an init'd project): skip — slug can still be
    // re-derived from the app name.
  }
}

// ===========================================================================
// Owner pauses: a stop the owner can always answer with "deploy anyway"
// ===========================================================================
//
// The AI advises; the owner decides. A homemade Piezas toolkit, a missing
// Report a problem button and settings the app declares but the live app does
// not have each pause the deploy with a plain explanation and a
// recommendation. The owner — never the AI — can put the version live anyway:
// at the terminal prompt, or by typing "deploy anyway" in their AI tool (the
// plugin records their own message, as for the never-rule pause). The
// confirmation is bound to this app, this exact build and what was found.

export const OWNER_PAUSE_KIND = 'owner-pause';

// ---------------------------------------------------------------------------
// AI first: problems the AI can fix stop the deploy for the AI only, once. The
// owner hears about one only when it is still there on the next deploy (the
// AI could not fix it), inside the pause. A person at the terminal (no AI in
// this run) goes straight to the pause.
// ---------------------------------------------------------------------------
export const AI_FIX_FILE = 'deploy-ai-fixes.json';
export const AI_FIX_TEXT = {
  reportButton: 'Not live yet: your AI tool is adding the Report a problem button first, then it deploys again.',
  sdkCopy: 'Not live yet: your AI tool is switching the app back to the published Piezas toolkit first, then it deploys again.',
};

function readAIFixes(projectDir) {
  try {
    const data = JSON.parse(readFileSync(join(deployRecordRoot(projectDir), STATE_DIR, AI_FIX_FILE), 'utf-8'));
    return data && typeof data === 'object' ? data : {};
  } catch {
    return {};
  }
}

function writeAIFixes(projectDir, data) {
  const root = deployRecordRoot(projectDir);
  try {
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(join(root, STATE_DIR, AI_FIX_FILE), `${JSON.stringify(data, null, 2)}\n`);
  } catch { /* best effort: the owner is asked instead */ }
}

export function clearAIFix(projectDir, kind) {
  const all = readAIFixes(projectDir);
  if (!(kind in all)) return;
  delete all[kind];
  writeAIFixes(projectDir, all);
}

// ownerAtTerminal — a person answers this run at a terminal prompt. Never
// inside an AI tool: one that runs commands in a terminal (Codex unified
// exec, Claude Code's !) could type the answer itself.
export function ownerAtTerminal(options) {
  return options.interactive !== false && Boolean(options.promptFn || (options.interactive === true && process.stdin.isTTY))
    && !inAiTool(options.env ?? process.env);
}

// deployNeedsAIFix — the AI-only stop, or null when the AI already had its try
// at this same problem (or a person runs this at the terminal).
export function deployNeedsAIFix(projectDir, options, fix) {
  if (ownerAtTerminal(options)) return null;
  const all = readAIFixes(projectDir);
  if (all[fix.kind]?.key === fix.key) return null;
  writeAIFixes(projectDir, { ...all, [fix.kind]: { key: fix.key, at: new Date().toISOString() } });
  log('');
  log(`  ${fix.ownerLine}`);
  log(`  (For the AI: ${fix.forAI} Do not ask the owner about this; if it still fails after that, the deploy tells them.)`);
  log('');
  return { exitCode: 1, command: 'deploy', status: fix.status, aiFix: true, ownerCanOverride: false, ...(fix.extra ?? {}) };
}


// artifactDigest — sha256 over the staged build: every file's path and bytes.
export function artifactDigest(dir) {
  const lines = [];
  const walk = (d) => {
    let entries;
    try { entries = readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      const full = join(d, e.name);
      if (e.isSymbolicLink()) continue;
      if (e.isDirectory()) walk(full);
      else if (e.isFile()) {
        let digest;
        try { digest = createHash('sha256').update(readFileSync(full)).digest('hex'); } catch { digest = 'unreadable'; }
        lines.push(`${relative(dir, full).split('\\').join('/')}\u0000${digest}`);
      }
    }
  };
  walk(dir);
  return createHash('sha256').update(lines.sort().join('\n')).digest('hex');
}

export function ownerPauseFingerprint(kind, appId, digest, items = []) {
  return createHash('sha256')
    .update(['owner-pause', kind, `app\u0000${appId ?? ''}`, `artifact\u0000${digest}`, ...[...items].map(String).sort()].join('\n'))
    .digest('hex')
    .slice(0, 24);
}

// ownerPauseApproved — the owner confirmed this exact pause (terminal answer
// in this run, or their own "deploy anyway" recorded by the plugin).
export function ownerPauseApproved(projectDir, options, fingerprint) {
  return (options.ownerAcks ?? []).includes(fingerprint) || testGateApproved(projectDir, fingerprint);
}

// confirmedHardNo — the owner's confirmation of a never-rule pause (what the
// hosting server checks), never an owner-pause or test-gate value.
export function confirmedHardNo(projectDir) {
  const pending = pendingDeployRisk(projectDir);
  const kind = pending?.kind;
  if (kind === OWNER_PAUSE_KIND || kind === 'test-gate') return null;
  // The server's own finding, answered per item by the owner.
  if (pending?.fingerprint && Array.isArray(pending.hardNo) && pending.hardNo.length) {
    const answered = deployItemLookup(projectDir);
    const items = hardNoItems(pending.hardNo);
    if (items.length && items.every((i) => answered(i))) return pending.fingerprint;
  }
  return confirmedDeployRisk(projectDir);
}

// Taking an app down: the owner's own terminal, or the console.
export const UNDEPLOY_TEXT = {
  refused: 'Only the owner can take an app down: from their own terminal, or the app page in the Piezas console. Nothing was taken down.',
  script: 'From a script, also set PIEZAS_UNDEPLOY_CONFIRM to the app\'s name.',
  forAI: '(For the AI: never take an app down yourself, in any form; tell the owner this in one sentence.)',
};

export const OWNER_PAUSE_TEXT = {
  nothingLive: 'Nothing was put live. The version that is already live keeps running.',
  choice: `It's your choice. To put this version live anyway, reply "${DEPLOY_ANYWAY}". Otherwise your AI tool fixes it and tries again.`,
  terminalPrompt: `Type "${DEPLOY_ANYWAY}" to put this version live anyway, or press Enter to stop and fix it first: `,
  stopped: 'Stopped. Your AI tool can fix it, then deploy again.',
  reportButton:
    'The Report a problem button is not in the app yet. It lets the people using your app tell you when something goes ' +
    'wrong, and gives Piezas what it needs to help. Recommended: your AI tool adds it, rebuilds, and tries again.',
  missingEnv: (names, page) => {
    const one = names.length === 1;
    return `Your app uses ${joinWords(names)}, which the live app doesn't have yet. ` +
      `Add ${one ? 'it' : 'them'} on the app page in the Piezas console${page ? `: ${page}` : ''}, then deploy again.`;
  },
  overridden: (what) => `You chose to put this version live anyway: ${what}.`,
};

// deployNeedsTestWork — the AI still has work on the checks (this version is
// not checked yet, or parts fail with rounds left): the stop is for the AI.
// The owner sees one progress line; nothing is asked (Spec 1-B).
export function deployNeedsTestWork(projectDir, gate) {
  // Not a check attempt (only `piezas test` runs count), but the owner's own
  // "deploy anyway" or "keep trying" can still reach it: the override never
  // goes away.
  writeSilentTestGate(projectDir, gate);
  log('');
  log(`  ${progressLine(gate)}`);
  log(`  (For the AI: ${testGateAIOrder(gate)})`);
  const quality = qualityGateVerdict(projectDir);
  const scanAt = Date.parse(quality.attestation?.ranAt);
  const testAt = Date.parse(readTestAttestation(projectDir)?.ranAt);
  if (quality.applies && Number.isFinite(scanAt) && (!Number.isFinite(testAt) || scanAt > testAt)) {
    log(`  (For the AI: ${qualityOrderNote(projectDir, quality)})`);
  }
  log('');
  for (const line of testGateListLines(gate)) log(`  ${line}`);
  log('');
  return {
    exitCode: 1,
    command: 'deploy',
    status: 'tests-not-passing',
    aiFix: true,
    ownerCanOverride: false,
    verdict: gate.verdict,
    round: gate.round,
    fingerprint: gate.fingerprint,
    problems: gate.problems,
    notes: gate.notes,
    items: testGateItems(gate),
    next: testGateAIOrder(gate),
  };
}

// ===========================================================================
// The one pause (Spec 1-D): everything that still needs the owner after the
// AI has tried is one message with one answer. Each group (parts of the app
// after the AI's rounds, rewritten checks, missing settings, a broken rule,
// the homemade toolkit copy, the Report a problem button) lists its items;
// an item the owner already answered ("deploy anyway") for exactly this
// version of it is not asked again. All answered: the deploy goes live with
// one summary line.
// ===========================================================================

export const PAUSE_TEXT = {
  header: (n) => `Paused: ${n} things need you before this goes live.`,
  single: 'Paused before going live.',
  same: (n, noun, day, newNames, newCount) =>
    `Same ${n} ${noun} as last time (you chose to go live without ${n === 1 ? 'it' : 'them'} on ${day})` +
    (newCount ? `, plus ${newCount} new one${newCount === 1 ? '' : 's'}: ${newNames}.` : '.'),
  goingLiveWithout: (n, noun, day, names) => `Going live without ${n} ${noun}, as you chose on ${day}${names ? `: ${names}` : ''}.`,
  changedSince: (day, names) => `You chose "${DEPLOY_ANYWAY}" on ${day}, but the app changed since, so this asks again: ${names}.`,
  // No file names for the owner: where it is goes to the AI.
  rules: (findings) => `${hardNoOwnerWords(findings).join(' ')} Your AI tool can usually fix this.`,
};


function shortDay(iso) {
  const at = new Date(iso);
  return Number.isFinite(at.getTime()) ? at.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '';
}

function itemsNoun(items) {
  const kinds = new Set(items.map((i) => i.kind));
  if (kinds.size === 1 && kinds.has('part')) return items.length === 1 ? 'unchecked part' : 'unchecked parts';
  if (kinds.size === 1 && kinds.has('setting')) return items.length === 1 ? 'missing setting' : 'missing settings';
  if (kinds.size === 1 && kinds.has('rule')) return items.length === 1 ? 'broken rule' : 'broken rules';
  return items.length === 1 ? 'thing' : 'things';
}

// testsPauseGroup — the parts the owner is asked about: after the AI's rounds
// (or at the terminal), each part not answered yet; an unchecked version is
// one item, bound to this exact code.
export function testsPauseGroup(gate) {
  return {
    name: 'tests',
    status: 'tests-not-passing',
    legacy: { fingerprint: gate.fingerprint, pause: 'test-gate' },
    items: testsPauseItems(gate),
    gate,
  };
}

// openPauseGroups — each group with the items still waiting for the owner.
export function openPauseGroups(groups, answerOf) {
  const answered = [];
  const open = [];
  for (const g of groups) {
    if (g.legacyOk) continue;
    const waiting = g.items.filter((i) => {
      const a = answerOf(i);
      if (a) answered.push({ item: i, at: a.at, ...(a.unseen ? { unseen: true } : {}) });
      return !a;
    });
    if (waiting.length) open.push({ ...g, open: waiting });
  }
  return { open, answered };
}

const itemName = (i) => (i.kind === 'part' ? `“${i.title}”` : i.kind === 'version' ? 'checking this version' : i.title);
const itemNames = (items) => items.slice(0, 5).map(itemName).join(', ') + (items.length > 5 ? `, and ${items.length - 5} more` : '');

// pauseMemoLine — "Same N things as last time …": only for what the owner was
// shown and answered (an answer given while nothing was shown is not "the
// same as last time").
export function pauseMemoLine(answered, open) {
  const seen = answered.filter((a) => !a.unseen);
  if (!seen.length || !open.length) return '';
  const last = seen.map((a) => a.at).filter(Boolean).sort().pop();
  const fresh = open.flatMap((g) => g.open);
  return PAUSE_TEXT.same(seen.length, itemsNoun(seen.map((a) => a.item)), shortDay(last), itemNames(fresh), fresh.length);
}

// changedSinceLine — the owner chose "deploy anyway" for an earlier version
// of these things; the code changed after the pause they read, so this
// version asks again.
export function changedSinceLine(open, earlierAnswerOf) {
  const again = open.flatMap((g) => g.open).filter((i) => earlierAnswerOf(i));
  if (!again.length) return '';
  const last = again.map((i) => earlierAnswerOf(i).at).filter(Boolean).sort().pop();
  // At most 25 words: a long list is counted, not named.
  const named = PAUSE_TEXT.changedSince(shortDay(last), itemNames(again));
  return named.split(/\s+/).length <= 25 ? named : PAUSE_TEXT.changedSince(shortDay(last), `${again.length} ${itemsNoun(again)}`);
}

// goingLiveWithoutLine — one line naming what goes live unchecked or unset
// (a long list of parts is counted only).
export function goingLiveWithoutLine(answered) {
  if (!answered.length) return '';
  const last = answered.map((a) => a.at).filter(Boolean).sort().pop();
  const items = answered.map((a) => a.item);
  const named = items.some((i) => i.kind !== 'part') ? itemNames(items) : '';
  return PAUSE_TEXT.goingLiveWithout(answered.length, itemsNoun(items), shortDay(last), named);
}

// pauseView — the test verdict as the owner reads it: only the parts still
// waiting for them.
function pauseView(group) {
  const gate = group.gate;
  if (gate.verdict !== 'not-passing') return gate;
  const waiting = new Set(group.open.map((i) => i.key));
  return { ...gate, problems: gate.problems.filter((p) => waiting.has(p.id)) };
}

export function onePauseLines(groups, memo) {
  const tests = groups.find((g) => g.name === 'tests');
  const others = groups.filter((g) => g.name !== 'tests');
  const lines = [];
  if (groups.length === 1 && tests) {
    const view = pauseView(tests);
    const gateLines = testGateLines(view);
    lines.push(gateLines[0]);
    if (memo) lines.push(memo);
    lines.push(...gateLines.slice(1));
    return lines;
  }
  if (groups.length === 1) {
    lines.push(PAUSE_TEXT.single);
    if (memo) lines.push(memo);
    lines.push(...others[0].render(others[0].open), OWNER_PAUSE_TEXT.nothingLive, OWNER_PAUSE_TEXT.choice);
    return lines;
  }
  lines.push(PAUSE_TEXT.header(groups.length));
  if (memo) lines.push(memo);
  lines.push(OWNER_TEXT.summaryHeader);
  if (tests) {
    const view = pauseView(tests);
    if (view.gaveUp) lines.push(`  ${OWNER_TEXT.gaveUp(view.round)}`);
    const passed = onlyNeedsCheckAgain(view) ? [] : (view.passed ?? []).map((p) => ({ ...p, status: 'passed' }));
    for (const l of summaryLines([...passed, ...view.problems, ...view.notes])) lines.push(`  ${l}`);
    if (view.verdict !== 'not-passing') lines.push(`  ! ${OWNER_TEXT.gateHeader[view.verdict].replace(/^Paused: /, '').replace(/^./, (c) => c.toUpperCase())}`);
  }
  for (const g of others) {
    const [first, ...rest] = g.render(g.open).filter((l) => l !== '');
    lines.push(`  ! ${first}`, ...rest.map((l) => `    ${l.trim()}`));
  }
  lines.push(OWNER_PAUSE_TEXT.nothingLive, '');
  if (tests) lines.push(...gateChoiceLines(pauseView(tests), { others: others.length > 0 }));
  else lines.push(OWNER_PAUSE_TEXT.choice);
  return lines;
}

// deployOnePause — show the one pause; at a terminal, read the one answer.
export async function deployOnePause(projectDir, options, groups, { memo = '' } = {}) {
  const tests = groups.find((g) => g.name === 'tests');
  const single = groups.length === 1 ? groups[0] : null;
  const legacy = groups.map((g) => g.legacy);
  const decide = groups.flatMap((g) => g.open.map(({ kind, key, fp, title }) => ({ kind, key, fp, title })));
  const fingerprint = single
    ? single.legacy.fingerprint
    : createHash('sha256').update(['one-pause', ...legacy.map((l) => l.fingerprint), ...decide.map((i) => `${i.kind}\u0000${i.key}\u0000${i.fp}`).sort()].join('\n')).digest('hex').slice(0, 24);
  const status = single ? single.status : 'paused';
  const lines = onePauseLines(groups, memo);
  // What waits for the owner's own reply (the plugin records it). A shown,
  // unanswered pause is never replaced before this one is relayed.
  try {
    const view = tests ? pauseView(tests) : null;
    writeShownPause(projectDir, {
      kind: tests ? 'test-gate' : OWNER_PAUSE_KIND,
      pause: status,
      fingerprint,
      ...(view ? { verdict: view.verdict, ...(view.gaveUp ? { gaveUp: true } : {}), items: view.problems.map((p, i) => ({ n: i + 1, id: p.id, title: p.title, status: p.status })), list: testGateListLines(view).join('\n') } : {}),
      ...(groups.some((g) => g.name === 'rules') ? { hardNo: groups.find((g) => g.name === 'rules').extra.hardNo } : {}),
      legacy,
      decide,
      // The code this pause was shown for: the owner's answer binds to it.
      sourceFingerprint: currentSource(projectDir),
      message: lines.join('\n'),
      at: new Date().toISOString(),
    });
  } catch { /* the terminal prompt still works */ }

  const canAsk = ownerAtTerminal(options);
  const agentDriven = !canAsk || inAiTool(options.env ?? process.env);
  log('');
  for (const line of lines) log(line ? `  ${line}` : '');
  log('');
  const forAI = groups.map((g) => g.forAI).filter(Boolean);
  const relay = relayAllowed(deployRecordRoot(projectDir));
  if (agentDriven) {
    for (const note of forAI) log(`  (For the AI: ${note} Only the owner's own "${DEPLOY_ANYWAY}" counts; never type it or treat "go ahead" as it.)`);
    if (relay) log(`  (For the AI: ${DEPLOY_RELAY_NOTE})`);
    if (tests) {
      log(`  (For the AI: ${GATE_LIST_NEXT})`);
      log('');
      for (const line of testGateListLines(pauseView(tests))) log(`  ${line}`);
    }
    log('');
  }
  const view = tests ? pauseView(tests) : null;
  const result = {
    exitCode: 1,
    command: 'deploy',
    status,
    ownerCanOverride: true,
    fingerprint,
    ...(agentDriven && relay ? { relay: DEPLOY_RELAY_NOTE } : {}),
    ...(single?.extra ?? {}),
    ...(single ? {} : { groups: groups.map((g) => g.status), ...Object.assign({}, ...groups.map((g) => g.extra ?? {})) }),
    ...(view ? {
      verdict: view.verdict, problems: view.problems, notes: view.notes, items: testGateItems(view),
      next: canAsk ? GATE_LIST_NEXT_TERMINAL : GATE_LIST_NEXT, testFingerprint: view.fingerprint,
    } : {}),
    ...(single?.name === 'tests' ? { fingerprint: view.fingerprint } : {}),
  };
  if (!canAsk) return result;

  const promptFn = options.promptFn ?? promptViaTerminal;
  const prompt = !view ? OWNER_PAUSE_TEXT.terminalPrompt
    : view.verdict !== 'not-passing' ? OWNER_TEXT.terminalPromptRecheck
      : view.problems.some((p) => p.status === 'failed' || p.status === 'not-written') ? OWNER_TEXT.terminalPrompt : OWNER_PAUSE_TEXT.terminalPrompt;
  const answer = String((await promptFn(`  ${prompt}`)) ?? '').trim();
  const testRoot = findProjectRoot(projectDir) ?? resolve(projectDir);
  // The owner answered here (whatever they typed, even nothing): the pause and
  // its rewritten-check question are closed for the chat.
  try { clearCheckChangeAsked(testRoot); } catch { /* best effort */ }
  try { clearPendingDeployRisk(projectDir); } catch { /* best effort */ }
  const items = view ? view.problems.map((p, i) => ({ n: i + 1, id: p.id, title: p.title, status: p.status })) : [];
  const reply = answer ? readGateReply(answer, items) : null;
  const exact = exactDeployAnyway(answer);
  // The quality scan's leftovers, shown with "accept 2" / "accept all": the
  // same words count here as in the chat.
  const leftovers = groups.find((g) => g.name === 'quality' && g.open.some((i) => i.kind === 'finding'));
  const accept = leftovers && !exact ? readAcceptReply(answer) : null;
  if (accept && !accept.bare) {
    const done = qualityOwnerCommand('accept', accept.all ? ['all'] : accept.numbers.map(String), projectDir);
    for (const line of done.output ?? []) log(`  ${line}`);
    log('');
    return done.exitCode === 0 ? deploy(options) : result;
  }
  if (exact || (reply?.choice === 'deploy' && !needsExactWords(decide))) {
    recordPauseAnswer(projectDir, { fingerprint, pause: status, legacy, decide }, 'terminal', answer);
    log('');
    return deploy({
      ...options,
      ownerAcks: [...(options.ownerAcks ?? []), ...legacy.map((l) => l.fingerprint)],
      ...(tests ? { acknowledgeTests: tests.gate.fingerprint } : {}),
    });
  }
  if (view) {
    if (!reply && answer) {
      const waiting = openCheckChanges(testRoot).filter((s) => view.problems.some((p) => p.id === s.id && p.status === 'changed-checks'));
      let said = answer;
      let asked = false;
      if (checkChangeNeedsName(said, waiting)) {
        said = String((await promptFn(`  ${OWNER_TEXT.whichCheck(checkChangeName(waiting[0]))} `)) ?? '').trim();
        asked = true;
      }
      // At the which-check prompt a bare part name is the answer.
      const approved = !waiting.length ? [] : asked ? readWhichCheckReply(said, waiting) : approvedCheckChanges(said, waiting);
      if (approved.length) {
        recordCheckChangeApproval(testRoot, { ...readCheckChange(testRoot), scenarios: approved }, said, 'terminal');
        log(`  ${OWNER_TEXT.checkChangeOk(approved.map((s) => s.title))}\n`);
        return result;
      }
    }
    if (reply?.choice === 'skip') {
      // A typed override ("skip <name>"); never a menu or a follow-up question.
      if (view.verdict !== 'not-passing') {
        log(`  ${OWNER_TEXT.skipNeedsCheck}`);
      } else if (reply.targets.length) {
        recordSkips(testRoot, reply.targets, answer, 'terminal');
        log(`  ${OWNER_TEXT.skipRecorded(reply.targets.map((t) => t.title))}`);
        log('');
        return deploy(options);
      } else {
        log(`  ${OWNER_TEXT.skipUnclear((reply.candidates ?? []).map((c) => c.title))}`);
      }
    }
    if ((reply?.choice === 'keep' || !answer) && view.gaveUp) {
      recordKeepTrying(testRoot, answer || '(Enter)', 'terminal');
      log(`  ${OWNER_TEXT.keepTryingOk}\n`);
      return result;
    }
    log(`  ${OWNER_TEXT.stopped}\n`);
    return result;
  }
  log(`  ${OWNER_PAUSE_TEXT.stopped}\n`);
  return result;
}

// deployNeedsQualityScan — the quality scan stop. Nothing goes live; the AI
// runs the scan (in a separate context) and fixes what it finds, and only the
// owner's own "accept N" sets a problem aside. With the "before publishing"
// setting, "done" now waits for the scan too (the Stop hook).
export function deployNeedsQualityScan(projectDir, quality) {
  markDeployWanted(projectDir);
  markDeployHold(projectDir);
  log('');
  const open = quality.verdict === 'open';
  if (!open) noteDeployScanTry(projectDir, quality.fingerprint);
  log(`  ${open ? QUALITY_TEXT.fixing(quality.open.length, Math.min((quality.attestation?.round ?? 0) + 1, QUALITY_MAX_ROUNDS)) : QUALITY_TEXT.checking}`);
  log(`  (For the AI: ${open
    ? 'fix each open problem without asking the owner, then run `npx piezas quality-scan packet` and the scan again; only the owner\'s own "accept N" sets one aside, never yours.'
    : `run \`npx piezas quality-scan packet\`, then: ${scannerSteps(deployRecordRoot(projectDir))}`} ${qualityOrderNote(projectDir, quality)} ` +
    `Never run the owner's own quality-scan commands yourself. ${QUALITY_TEXT.relayForAI})`);
  if (open) {
    log('');
    for (const f of quality.open) log(`  ${f.n}. ${f.plain}`);
  }
  log('');
  return {
    exitCode: 1,
    command: 'deploy',
    status: open ? 'quality-scan-open' : 'quality-scan-needed',
    aiFix: true,
    ownerCanOverride: false,
    verdict: quality.verdict,
    open: quality.open.map((f) => ({ n: f.n, severity: f.severity, plain: f.plain })),
  };
}

// qualityPauseGroup — the quality scan inside the one pause: what the AI could
// not fix after its rounds (each finding answerable with "accept N" or
// "deploy anyway"), or, at the terminal, a version the scan has not checked.
export function qualityPauseGroup(quality) {
  const open = quality.verdict === 'open';
  return {
    name: 'quality',
    status: open ? 'quality-scan-open' : 'quality-scan-needed',
    legacy: { fingerprint: createHash('sha256').update(['quality', quality.fingerprint ?? '', ...quality.open.map((f) => f.key)].join('\n')).digest('hex').slice(0, 24), pause: 'quality-scan' },
    legacyOk: false,
    items: open
      ? quality.open.map((f) => ({ kind: 'finding', key: f.key, fp: f.key, title: f.plain, n: f.n }))
      : [{ kind: 'unscanned', key: 'scan', fp: String(quality.fingerprint ?? ''), title: 'the quality scan' }],
    render: (items) => (open
      ? [QUALITY_TEXT.left(items.length), ...items.map((i) => `  ${i.n}. ${i.title}`), QUALITY_TEXT.leftHint]
      : [QUALITY_TEXT.notScanned]),
    forAI: open ? 'only the owner\'s own "accept N" or "deploy anyway" sets these aside.' : 'run the quality scan, fix what it finds, then `piezas test` last.',
    extra: { open: quality.open.map((f) => ({ n: f.n, severity: f.severity, plain: f.plain })) },
  };
}

// settingNamesFor — the setting names a build reads (names only, never
// values): every one, sorted, and which of them the app cannot run without
// (`required`, sorted). Both empty when the build was not scanned (a static
// build). The same lists go in the setting-names owner record and in
// ownerItems.
export function settingNamesFor(needed) {
  if (!needed?.scanned) return { settingNames: [], required: [] };
  return { settingNames: [...needed.required, ...needed.optional].sort(), required: [...needed.required].sort() };
}

// ownerItemsFor — what another reader (the MCP's piezas_deploy, as its
// `owner_items`) needs to see the owner's answers as this CLI does: the
// per-item answers in force, every clear, and the build's setting names with
// the required ones. Hosting receives the same object as the `ownerItems`
// upload field.
export function ownerItemsFor(projectDir, needed) {
  return { ...deployItemRecords(projectDir), ...settingNamesFor(needed) };
}

// deployOwnerItems — `piezas deploy --owner-items`: print the ownerItems
// object for this project's build as JSON (for an AI deploying through the
// Piezas connection, which passes it as `owner_items`). Nothing is uploaded,
// nothing is asked, nothing is recorded.
export function deployOwnerItems(options = {}) {
  const projectDir = options.cwd || process.cwd();
  const print = options.print ?? ((text) => console.log(text));
  const selection = selectArtifact(projectDir, options);
  if (selection.status !== 'ok') {
    console.error('  (For the AI: no build of this app to read: build it first (npm run build), or set deploy.dir in piezas.manifest.json.)');
    return { exitCode: 1, command: 'deploy', status: 'no-build' };
  }
  const staging = mkdtempSync(join(tmpdir(), 'piezas-owner-items-'));
  try {
    const staged = stageArtifact(projectDir, staging, options, selection);
    if (!staged) {
      console.error('  (For the AI: no build of this app to read: build it first (npm run build), or set deploy.dir in piezas.manifest.json.)');
      return { exitCode: 1, command: 'deploy', status: 'no-build' };
    }
    let manifest = null;
    try { manifest = readJsonFile(resolve(projectDir, 'piezas.manifest.json')); } catch { /* no manifest */ }
    const ownerItems = ownerItemsFor(projectDir, settingsNeeded(projectDir, staging, manifest, { kind: staged.kind }));
    print(JSON.stringify(ownerItems));
    return { exitCode: 0, command: 'deploy', status: 'owner-items', ownerItems };
  } finally {
    rmSync(staging, { recursive: true, force: true });
  }
}

export async function deploy(options = {}) {
  const env = options.env ?? process.env;
  const projectDir = options.cwd || process.cwd();
  const fetchFn = platformFetch(projectDir, options);
  const sandbox = isSandboxProject(projectDir);
  const base = appsBaseUrl(options, env);

  log('\n  🧱 Piezas deploy\n');

  if (sandbox) log(`  ${SANDBOX_NOTE}\n`);

  if (options.isolated) {
    log('  --isolated gives your app its own infrastructure: a dedicated server,');
    log('  private network, its own database, storage, and access logs — nothing');
    log('  shared with anyone. It\'s how our compliance-heavy clients run today.');
    log('');
    log('  It\'s coming soon. Right now `npx piezas deploy` ships to the shared');
    log('  apps server (--mixed): up to 2 apps free, isolated containers.');
    log('');
    log('  Want early access to isolated mode?  https://app.piezas.ai/contact\n');
    return { exitCode: 1, command: 'deploy', status: 'unsupported-mode' };
  }

  const credentials = platformCredentials(projectDir, env);
  if (!credentials) {
    log(`  ${signInNeededLine(env, options)}\n`);
    return { exitCode: 1, command: 'deploy', status: 'not-logged-in' };
  }
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const slug = deploySlugFor(projectDir, options);
  // The durable identity, if this project is linked; lookups prefer it over
  // the (rename-able) slug.
  const knownAppId = (() => {
    try { return readJsonFile(resolve(projectDir, 'piezas.manifest.json')).deploy?.appId ?? null; } catch { return null; }
  })();
  const idQS = knownAppId ? `?appId=${encodeURIComponent(knownAppId)}` : '';

  // --status / --logs / --delete address an existing deployment and skip packaging.
  if (options.status) {
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, httpOptions);
    if (res.status === 404) {
      log(`  No deployment named "${slug}" — run \`npx piezas deploy\` first.\n`);
      return { exitCode: 1, command: 'deploy', status: 'not-found', slug };
    }
    if (res.status !== 200) {
      log(`  Could not fetch status (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    log(`  ${res.data.slug}: ${res.data.status}`);
    log(`  ${res.data.url}\n`);
    return { exitCode: 0, command: 'deploy', ...res.data };
  }
  if (options.logs) {
    // Bare `--logs` arrives as boolean true — and Number(true) is 1, which
    // would silently tail a single line. Explicit numbers only; else 200.
    const tail = options.logs !== true && Number.isFinite(Number(options.logs)) && Number(options.logs) > 0
      ? Number(options.logs) : 200;
    const res = await fetchJson(fetchFn,
      `${base}/v1/deployments/${slug}/logs?tail=${tail}${knownAppId ? `&appId=${encodeURIComponent(knownAppId)}` : ''}`,
      httpOptions);
    if (res.status !== 200) {
      log(`  Could not fetch logs (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    console.log(res.data.logs || '(no output yet)');
    return { exitCode: 0, command: 'deploy', slug, status: 'logs' };
  }
  if (options.delete) {
    // The owner-only path: one confirmation, the app's name typed (Spec Part
    // 2, #53). Never inside an AI tool, hooked or not, at a terminal or not.
    // PIEZAS_UNDEPLOY_CONFIRM (the app's name, with `--yes "<name>"` naming
    // it too) is honoured only when NO sign of an AI tool is present: no AI
    // host variable, no AI tool in the process chain, a terminal on stdin.
    // Clearing one variable leaves the others, and nothing turns them off.
    let appName = slug;
    try { appName = readJsonFile(resolve(projectDir, 'piezas.manifest.json')).appName || slug; } catch { /* slug */ }
    const aiTool = inAiTool(env);
    const confirmEnv = typeof env.PIEZAS_UNDEPLOY_CONFIRM === 'string' && env.PIEZAS_UNDEPLOY_CONFIRM.trim()
      ? env.PIEZAS_UNDEPLOY_CONFIRM.trim() : null;
    const flagName = typeof options.confirmName === 'string' ? options.confirmName.trim() : null;
    const canAsk = !aiTool && ownerAtTerminal(options);
    if (aiTool || (!canAsk && confirmEnv === null)) {
      log(`  ${UNDEPLOY_TEXT.refused}`);
      if (!aiTool && flagName !== null) log(`  ${UNDEPLOY_TEXT.script}`);
      if (aiTool || !canAsk) log(`  ${UNDEPLOY_TEXT.forAI}`);
      log('');
      return { exitCode: 1, command: 'deploy', status: 'delete-not-confirmed', slug };
    }
    const same = (a, b) => a.toLowerCase().replace(/\s+/g, ' ') === b.toLowerCase().replace(/\s+/g, ' ');
    if (!canAsk && flagName !== null && !same(flagName, confirmEnv)) {
      log('  That is not the app\'s name, so nothing was taken down.\n');
      return { exitCode: 1, command: 'deploy', status: 'delete-not-confirmed', slug };
    }
    const typed = !canAsk ? confirmEnv : String((await (options.promptFn ?? promptViaTerminal)(`  This takes "${appName}" off the internet; the people using it lose it. Type the app's name to take it down: `)) ?? '').trim();
    if (!typed || !(same(typed, appName) || same(typed, slug))) {
      log('  That is not the app\'s name, so nothing was taken down.\n');
      return { exitCode: 1, command: 'deploy', status: 'delete-not-confirmed', slug };
    }
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, { ...httpOptions, method: 'DELETE' });
    if (res.status === 404) {
      log(`  No deployment named "${slug}" — nothing to delete.\n`);
      return { exitCode: 1, command: 'deploy', status: 'not-found', slug };
    }
    if (res.status !== 200) {
      log(`  Could not delete (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}`, slug };
    }
    log(`  Deleted "${slug}" from the apps server — its URL no longer serves.`);
    log('  (The app itself still exists in your console; delete it there if you');
    log('  want the app record and its keys gone too.)\n');
    return { exitCode: 0, command: 'deploy', status: 'deleted', slug };
  }

  // --- the quality scan ------------------------------------------------------
  // Before the testing gate: the scan and its fixes come first, the checks
  // last, on the final code. Only when the OWNER turned it on (either
  // setting): this exact code needs a scan under a day old with nothing open;
  // a problem is set aside only by the owner's own "accept N", and their
  // one-time "go live without the scan" lets exactly this code through once.
  // Off or not chosen: one line, and on.
  // On by default in a Piezas project (Spec 1-C). The scan and its fixes are
  // the AI's work (up to three rounds); what it could not fix joins the one
  // pause. A person at the terminal (no AI in this run) is asked there.
  const quality = qualityGateVerdict(projectDir);
  // An unattended run (CI, or no terminal and no AI tool) the owner allowed
  // with `piezas unattended on`: no quality scan; the checks still decide.
  const unattendedRun = aiHostSignals(env).length === 0 && (isCI(env) || !stdinIsTerminal());
  const unattendedAllowed = unattendedRun && unattendedDeploysOn(projectDir);
  // The owner's answers, per item (one read for the whole run).
  const answerOf = deployItemLookup(projectDir);
  const pauseGroups = [];
  if (!quality.applies) {
    if (quality.setting === 'off') log(`  ${QUALITY_TEXT.deployOff}`);
  } else if (!quality.ok) {
    const group = qualityPauseGroup(quality);
    const allAnswered = group.items.every((i) => answerOf(i));
    const scanRound = Number.isInteger(quality.attestation?.round) ? quality.attestation.round : 0;
    const gaveUp = quality.verdict === 'open' && (scanRound >= QUALITY_MAX_ROUNDS || quality.attestation?.status === 'stopped');
    // With no AI and no person (CI, or a build server with no terminal and no
    // CI variable: Jenkins, CodeBuild, Azure), nobody can run the scan: it is
    // "not run", one item in the pause (like an unchecked version), never a
    // stop that waits for an AI forever.
    const unattended = unattendedRun;
    // A version the scan has not checked: after the AI's tries, it is one item
    // in the pause ("go live without the scan"), never an endless "running the
    // quality scan".
    const triedEnough = quality.verdict !== 'open' && deployScanTries(projectDir, quality.fingerprint) >= QUALITY_DEPLOY_TRIES;
    if (!allAnswered && !gaveUp && !triedEnough && !ownerAtTerminal(options) && !unattended) return deployNeedsQualityScan(projectDir, quality);
    if (unattendedAllowed) log('  Quality scan skipped: unattended deploys are allowed for this project.');
    else pauseGroups.push(group);
  } else if (!quality.skipped) {
    log(`  ${QUALITY_TEXT.deployClean}`);
  }

  // --- the testing gate ------------------------------------------------------
  // A version goes live only with a passing `piezas test` run for this exact
  // code, under a day old. Otherwise: stop, and the OWNER chooses — keep
  // fixing (default), skip a part for now, or deploy anyway. The AI cannot
  // choose for them (the same owner-only confirmation as the Hard No pause).
  const gate = testGateVerdict(projectDir);
  let testGateOverride = null;
  // A passing version ends the AI's silent rounds on the checks. A pause the
  // owner was shown and has not answered stays: their reply is about what
  // they read (it binds to that code), until this deploy goes live or the AI
  // relays a newer pause.
  const waitingGate = gate.ok ? pendingTestGate(projectDir) : null;
  if (waitingGate && (waitingGate.silent || waitingGate.answered)) clearPendingDeployRisk(projectDir);
  // A part that passes ends the owner's earlier answers for it (Spec 1-D):
  // if it breaks again later, they are asked again.
  if (gate.applicable && gate.verdict !== 'missing') {
    try { clearDeployItems(projectDir, 'part', (gate.passed ?? []).map((p) => p.id), 'passed'); } catch { /* best effort */ }
  }
  if (gate.ok && gate.applicable) log(`  Checks passed (${(gate.passed ?? []).length} part${(gate.passed ?? []).length === 1 ? '' : 's'}).`);
  if (!gate.ok) {
    const acknowledged = options.acknowledgeTests === gate.fingerprint || testGateApproved(projectDir, gate.fingerprint);
    // AI first: while the AI still has work on the checks, the stop is the
    // AI's. A person at the terminal is asked straight away (in the pause).
    if (!acknowledged && !ownerAtTerminal(options) && testGateAIWork(gate, (i) => Boolean(answerOf(i)))) {
      return deployNeedsTestWork(projectDir, gate);
    }
    pauseGroups.push({ ...testsPauseGroup(gate), legacyOk: acknowledged });
  }

  // --- the deploy itself ---------------------------------------------------
  // Session preflight (fail fast, clear message). The apps-server accepts this
  // token by SIGNATURE alone, and a linked project reads its appId from the
  // local manifest — so a token whose control-plane SESSION is dead (revoked,
  // or rolled back by a DB restore) stays invisible until the key-mint 401s
  // deep in the flow, after packaging. One cheap authed GET surfaces it here.
  // Only a definitive 401/403 blocks; an unreachable/5xx control plane must
  // never gate a redeploy (the apps-server stays the authoritative enforcer).
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  try {
    // Reach my-apps (any tenant principal can), not partitions (admin-only): a
    // developer's VALID session must not read as "expired" here. A 401/403 from
    // my-apps is therefore a genuinely dead/unauthorized session, worth blocking.
    const ping = await fetchJson(fetchFn,
      `${adminBaseUrl(apiBase)}/v1/tenants/${credentials.tenantId}/my-apps`, httpOptions);
    if (ping.status === 401 || ping.status === 403) {
      log('  Your Piezas session has expired — run `npx piezas login`, then deploy again.');
      log(`  (the control plane rejected the saved token: HTTP ${ping.status})\n`);
      return { exitCode: 1, command: 'deploy', status: 'session-expired', httpStatus: ping.status };
    }
  } catch { /* control plane unreachable — do not gate; downstream calls enforce */ }

  // Identity first (EB-style): confirm WHICH app this is from the platform's
  // own list — by durable id, never by secret — before anything is packaged.
  const linked = await ensureAppLink(projectDir, options, credentials, fetchFn);
  if (!linked) {
    return { exitCode: 1, command: 'deploy', status: 'not-linked' };
  }

  // Hosted-state preflight, BEFORE any packaging: does this app already have a
  // deployment (redeploys are always allowed), and if not, is there a free
  // slot? Refusing here costs milliseconds; refusing after upload costs the
  // user a 50 MB round-trip. The server remains the authoritative enforcer.
  let hostedExists = false;
  let serverKeys = [];
  let hostedAuthFailed = false;   // 401/403 — the session is expired or absent
  try {
    const res = await fetchJson(fetchFn,
      `${base}/v1/deployments/${slug}?appId=${encodeURIComponent(linked.appId)}`, httpOptions);
    if (res.status === 200) {
      hostedExists = true;
      if (Array.isArray(res.data?.envKeys)) serverKeys = res.data.envKeys;
    } else if (res.status === 401 || res.status === 403) {
      hostedAuthFailed = true;
    }
  } catch { /* unreachable -> the server-side checks still hold */ }
  // A rejected session here reads the hosted env as EMPTY, which then misfires
  // the requiredEnv gate as "NOT SET" and blocks the deploy with a misleading
  // env message. ensureAppLink short-circuits on a cached appId, so this
  // preflight is often the FIRST authenticated call — the first place an expired
  // token surfaces. Tell the truth and stop before packaging + a 50 MB upload.
  if (hostedAuthFailed) {
    log('  Your Piezas session isn\'t valid (expired or logged out), so this app\'s');
    log('  hosted settings can\'t be read. Deploying now would wrongly report the');
    log('  environment as empty — run `npx piezas login`, then deploy again.\n');
    return { exitCode: 1, command: 'deploy', status: 'auth-expired' };
  }
  if (!hostedExists) {
    try {
      const lres = await fetchJson(fetchFn, `${base}/v1/deployments`, httpOptions);
      const lim = lres.status === 200 ? lres.data?.limits : null;
      // maxApps <= 0 = unlimited; only positive caps gate.
      if (lim && lim.maxApps > 0 && lim.used >= lim.maxApps) {
        log(`  Your plan already hosts ${lim.used} of ${lim.maxApps} apps — the --mixed limit.`);
        log('  Free a slot (delete an app from its console page), or get early access');
        log('  to dedicated infrastructure: https://app.piezas.ai/contact\n');
        return { exitCode: 1, command: 'deploy', status: 'limit-reached', limits: lim };
      }
    } catch { /* unreachable -> the server-side check still holds */ }
  }

  // The Report a problem button: never asked. The stored answer (first
  // deploy: on) travels as the hosted setting PIEZAS_REPORT_BUTTON, which the
  // app reads at run time (no code change).
  const reportChoice = await askReportButton(projectDir, options);
  if (!reportChoice.ok) return { exitCode: 1, command: 'deploy', status: reportChoice.status };

  // Settings: never a yes/no question. After packaging, deploy compares the
  // NAMES the app uses with the names the live app has (below), and says one
  // line when they match.

  // The test record travels with the deploy, as form fields.
  const attestation = readTestAttestation(projectDir);

  const { mkdtempSync, rmSync, statSync: stat } = await import('fs');
  const { tmpdir } = await import('os');
  const staging = mkdtempSync(join(tmpdir(), 'piezas-deploy-'));
  const tarball = join(tmpdir(), `piezas-artifact-${Date.now()}-${randomBytes(6).toString('hex')}.tar.gz`);
  try {
    log('  Packaging your built app...');
    // Piezas evidence picks the folder (selectArtifact). When deploy can't
    // tell, it is the AI's to settle (deploy.dir, or npm run build), never a
    // question for the owner (Spec Part 2, #40-41).
    let artifactOptions = options;
    // One evidence cache for the whole run: each folder is scanned once.
    const evidence = evidenceCache();
    let selection = selectArtifact(projectDir, options, { evidence });
    if (selection.dirMissing) {
      log(`  This project says the app's build is in ${selection.dirMissing}, but that folder isn't there — looking for the build instead.`);
    }
    if (selection.status === 'ambiguous') {
      const { candidates, dirs } = selection;
      log('  Found more than one build of your app, so deploy can\'t tell which one should go live:');
      candidates.forEach((c, i) => log(`    - ${c}${dirs[i] !== c ? ` ("${dirs[i]}")` : ''}`));
      if (ownerAtTerminal(options)) {
        log('  Run deploy again with --dir and the folder that should go live, for example: piezas deploy --dir ' + `"${dirs[0] ?? candidates[0]}"`);
      } else {
        log('  For the AI tool: set deploy.dir in piezas.manifest.json to the folder that holds');
        log('  the app\'s server build (or pass --dir), then run deploy again.');
      }
      log('');
      return { exitCode: 1, command: 'deploy', status: 'ambiguous-artifact', candidates, dirs };
    }
    if (selection.status === 'wrong-folder') {
      // The explicit folder is not the app, but another one is: say so,
      // plainly. The fix depends on where the folder came from: a command-line
      // folder overrides deploy.dir, so telling that caller to set deploy.dir
      // would loop.
      const { chosen, suggested, suggestedFolder } = selection;
      if (chosen.via === 'dir') {
        log(`  Nothing in the folder you pointed deploy at (${chosen.folder}) uses Piezas.`);
        log(`  Your app looks like it is in ${suggestedFolder} instead. Point deploy at`);
        log(`  "${suggested}" and run it again. Nothing was uploaded.\n`);
      } else {
        log(`  Deploy checked ${chosen.folder}, but nothing in that folder uses Piezas.`);
        log(`  Your app looks like it is in ${suggestedFolder} instead.`);
        log(`  Your AI tool can fix this: set deploy.dir in piezas.manifest.json to "${suggested}",`);
        log('  then run deploy again. Nothing was uploaded.\n');
      }
      return {
        exitCode: 1, command: 'deploy', status: 'not-piezas-app',
        from: chosen.via, packaged: chosen.folder, suggested,
      };
    }
    if (selection.status === 'no-piezas-build') {
      if (selection.status !== 'ok') {
        log('  We couldn\'t find a build of your app that uses Piezas. Deploy ships the last');
        log('  build as-is, so build first (npm run build), then run deploy again. If your');
        log('  build lands somewhere unusual, your AI tool can point Piezas at it');
        log('  (deploy.dir in piezas.manifest.json).');
        // The paid-hosting line only when nothing in the project mentions Piezas.
        if (evidence(projectDir, { installedSdk: false }) === false) {
          log('  If your app doesn\'t use Piezas at all, contact us about paid hosting.');
        }
        log('');
        return {
          exitCode: 1, command: 'deploy', status: 'no-piezas-build',
          candidates: selection.candidates.map((c) => c.folder),
        };
      }
    }
    if (selection.status === 'ok') {
      if (selection.note) log(`  ${selection.note}`);
      else if (selection.chosen.via === 'bundle') log(`  Deploying the server build in ${selection.chosen.folder}.`);
    }
    const staged = stageArtifact(projectDir, staging, artifactOptions, selection);
    if (!staged) {
      // A non-Node project deserves the truth, not Next.js build advice: the
      // shared apps server runs Node and static apps today. Other runtimes
      // arrive with dedicated infrastructure (--isolated / image deploys).
      const otherRuntime = detectOtherRuntime(projectDir);
      if (otherRuntime) {
        log(`  This looks like a ${otherRuntime} app. The shared apps server currently`);
        log('  runs Node.js and static apps — other runtimes are coming with dedicated');
        log('  infrastructure (--isolated).');
        log('');
        log('  Your app can still USE Piezas from any language — every service is a');
        log('  plain HTTPS API (https://api.piezas.ai/<service>/openapi.json). Hosting');
        log('  is the only Node-specific part today.');
        log('');
        log(`  Want ${otherRuntime} hosting early?  https://app.piezas.ai/contact\n`);
        return { exitCode: 1, command: 'deploy', status: 'unsupported-runtime', runtime: otherRuntime };
      }
      // A built Next app that produced no standalone server is not a "build
      // first" problem — the user already built. Name the file and the line.
      // (--dir points the deploy at an explicit folder, so the miss is that
      // folder, not the Next config.)
      const recordedDir = manifestDeployDir(projectDir);
      const usingExplicitDir = (typeof options.dir === 'string' && Boolean(options.dir.trim()))
        || Boolean(recordedDir && existsSync(resolve(projectDir, recordedDir)));
      const nextDiagnosis = usingExplicitDir ? null : diagnoseNextBuild(projectDir);
      if (nextDiagnosis?.status === 'standalone-missing') {
        log(`  Your Next build succeeded, but ${nextDiagnosis.configFile} does not set  output: 'standalone',`);
        log('  so the build never produced .next/standalone/server.js — the bundle deploy ships.');
        log('');
        log('  Fix (one line + rebuild):');
        log(`    1. add    output: 'standalone',   to the config object in ${nextDiagnosis.configFile}`);
        log('    2. npm run build');
        log('    3. npx piezas deploy\n');
        return {
          exitCode: 1,
          command: 'deploy',
          status: 'standalone-missing',
          configFile: nextDiagnosis.configFile,
        };
      }
      if (nextDiagnosis?.status === 'rebuild-needed') {
        log('  Rebuild needed: run  npm run build  then deploy again.');
        log(`  (${nextDiagnosis.configFile} is right — it sets output: 'standalone' — but`);
        log('  .next/standalone/server.js is missing or stale. Deploy ships the build');
        log('  output as-is; it never builds.)\n');
        return {
          exitCode: 1,
          command: 'deploy',
          status: 'rebuild-needed',
          configFile: nextDiagnosis.configFile,
        };
      }
      log('  Nothing deployable found. Build first:');
      log('    server app:  next.config output: "standalone"   then   npm run build');
      log('    static app:  a build that produces out/ or dist/ with index.html');
      log('  (If the build lands in another folder, the AI tool can set deploy.dir in');
      log('  piezas.manifest.json to the folder whose root has server.js or index.html.)\n');
      return { exitCode: 1, command: 'deploy', status: 'no-artifact' };
    }

    // Every server app carries the Report a problem button (contract v6). The
    // tool adds it (`piezas report-button add`). A build without it pauses: the
    // AI recommends adding it; the owner may still put it live anyway.
    const overrides = [];
    let digest = null;
    const buildDigest = () => (digest ??= artifactDigest(staging));
    const button = staged.kind === 'server' ? reportButtonStatus(projectDir) : { applicable: false, ok: true };
    if (button.applicable && !button.ok) {
      // AI first (Spec Part 2, #42): the AI adds it; the owner hears about it
      // only when that did not work, in the pause.
      const aiFirst = deployNeedsAIFix(projectDir, options, {
        kind: 'report-button-missing',
        key: String(button.route ?? ''),
        status: 'report-button-missing',
        ownerLine: AI_FIX_TEXT.reportButton,
        forAI: 'run `piezas report-button add`, finish any step it lists, rebuild, then deploy again.',
        extra: { route: button.route, mounted: button.mounted },
      });
      if (aiFirst) return aiFirst;
      const fingerprint = ownerPauseFingerprint('report-button-missing', linked.appId, buildDigest(), [String(button.route ?? '')]);
      pauseGroups.push({
        name: 'report-button',
        status: 'report-button-missing',
        legacy: { fingerprint, pause: 'report-button-missing' },
        legacyOk: ownerPauseApproved(projectDir, options, fingerprint),
        items: [{ kind: 'report-button', key: 'report-button', fp: String(button.route ?? ''), title: 'the Report a problem button' }],
        render: () => [OWNER_PAUSE_TEXT.reportButton],
        forAI: 'adding it did not work: tell the owner why in one plain sentence.',
        extra: { route: button.route, mounted: button.mounted },
        live: () => overrides.push({ fingerprint, what: 'the Report a problem button is not in the app' }),
      });
    } else if (button.applicable) {
      clearAIFix(projectDir, 'report-button-missing');
      // The button is in the app: an earlier answer for it ends (if it goes
      // missing again later, the owner is asked again).
      try { clearDeployItems(projectDir, 'report-button', ['report-button'], 'in the app'); } catch { /* best effort */ }
    }
    // A homemade Piezas toolkit (contract Rule 11): the project and the
    // packaged build should both use the published @piezas/sdk from npm. The
    // owner hears the risk and the recommendation, and decides.
    const buildSide = sdkProvenance(staging).problems;
    const projectSide = sdkProvenance(projectDir).problems;
    const sdkProblems = [...projectSide, ...buildSide];
    if (sdkProblems.length) {
      const found = [...new Set(sdkProvenanceLines(sdkProblems))];
      // The answer key comes from the build's evidence (what the MCP sees
      // too): sha256 of the sorted, unique "name\0where" lines of the packaged
      // build's findings, first 24 hex (sdkPauseKey). A copy only the project
      // shows keys on the project's own evidence and where each copy came
      // from (sdkProjectPauseKey), never on nothing; the MCP cannot see those
      // and asks again.
      const sdkKey = buildSide.length ? sdkPauseKey(buildSide) : sdkProjectPauseKey(projectSide, projectDir);
      // AI first (Spec Part 2, #43): the AI switches back to the published
      // toolkit; the owner hears about it only if the copy is still there.
      // When the owner allowed outside changes (the copy may be their own
      // doing), the AI is not told to undo it: the owner decides, in the pause.
      const outside = readOutsideOverride(deployRecordRoot(projectDir));
      const ownerAllowedCopy = outside?.by === 'owner' && outside?.via === 'user-prompt';
      const aiFirst = ownerAllowedCopy ? null : deployNeedsAIFix(projectDir, options, {
        kind: 'unpublished-sdk',
        key: sdkKey,
        status: 'unpublished-sdk',
        ownerLine: AI_FIX_TEXT.sdkCopy,
        forAI: 'switch back to the published toolkit: a plain version in package.json (`npm install @piezas/sdk@latest`), ' +
          'delete any vendored copy, reinstall, rebuild, deploy again. If the toolkit lacks something the app needs, say what ' +
          'is missing in one plain sentence when the deploy asks the owner (contract Rule 11).',
        extra: { problems: sdkProblems },
      });
      if (aiFirst) return aiFirst;
      const fingerprint = ownerPauseFingerprint('unpublished-sdk', linked.appId, buildDigest(), found);
      pauseGroups.push({
        name: 'sdk-copy',
        status: 'unpublished-sdk',
        legacy: { fingerprint, pause: 'unpublished-sdk' },
        legacyOk: ownerPauseApproved(projectDir, options, fingerprint),
        items: [{ kind: 'sdk-copy', key: 'sdk-copy', fp: sdkKey, title: 'its own copy of the Piezas toolkit' }],
        // Where the copy came from (paths, package names) is for the AI only.
        render: () => [UNPUBLISHED_SDK_OWNER_TEXT],
        forAI: `switching back to the published toolkit did not work (${found.join('; ')}): tell the owner why in one plain sentence.`,
        extra: { problems: sdkProblems },
        live: () => overrides.push({ fingerprint, what: 'it uses its own copy of the Piezas toolkit, which Piezas support can\'t help with' }),
      });
    } else {
      clearAIFix(projectDir, 'unpublished-sdk');
    }
    // The test record goes as form fields (attestation, attestationDetail),
    // never inside the artifact: a static artifact is served publicly.

    // CLI-1: deploy ships the build AS-IS (it never builds) — surface the two
    // silent traps: a build older than the source, and an outdated SDK that a
    // fix will never reach without update + rebuild + redeploy. Warn, never block.
    const staleness = detectStaleBuild(projectDir, artifactOptions, selection);
    if (staleness?.stale) {
      log('');
      log('  ⚠ Your build looks STALE — source files changed after it was built:');
      log(`     changed:   ${relative(projectDir, staleness.newestSourcePath)}  (${new Date(staleness.newestSourceMtimeMs).toLocaleString()})`);
      log(`     built:     ${relative(projectDir, staleness.buildPath)}  (${new Date(staleness.buildMtimeMs).toLocaleString()})`);
      log('     Deploy ships the build output as-is, so those changes will NOT go live.');
      log('     To include them:  npm run build   then deploy again.');
      log('');
    }
    const nudge = await sdkVersionNudge(projectDir, fetchFn);
    if (nudge) log(nudge);

    execSync(`tar -czf ${JSON.stringify(tarball)} -C ${JSON.stringify(staging)} .`);
    const size = stat(tarball).size;
    const limitMB = resolveMaxArtifactMB(env);
    if (size > limitMB * 1024 * 1024) {
      log(`  Artifact is ${(size / 1024 / 1024).toFixed(0)} MB — the limit is ${limitMB} MB per app.`);
      log('  Large media belongs in the Documents service, not the app bundle.');
      log('  (Piezas hosting has its own size limit; the local cap can be raised with PIEZAS_MAX_ARTIFACT_MB.)\n');
      return { exitCode: 1, command: 'deploy', status: 'too-large' };
    }
    log(`  Packaged ${staged.kind} app from ${staged.source} (${(size / 1024 / 1024).toFixed(1)} MB)`);
    if (staged.removed?.length) {
      const envFiles = staged.removed.filter((p) => /^\.env(?:\.|$)/.test(basename(p)));
      if (envFiles.length) log(`  Left out ${envFiles.join(', ')} (local only), it is never uploaded.`);
    }

    const appName = linked.appName;

    // Env: deploy transmits ONLY values explicitly typed as --env KEY=VALUE.
    // The hosted runtime's environment is the cloud store — PIEZAS_API_KEY is
    // provisioned there when the app is created, and everything else is set
    // in the console (Hosting -> Environment). The local .env file is never
    // read: it belongs to local development.
    const sent = collectExplicitEnv(options);
    const sentNames = Object.keys(sent).sort();
    // Not a secret and not a typed setting: the owner's on/off answer above.
    // Sent when the owner just chose it (the flag, or `piezas report-button
    // on|off` since the last deploy), or when the live app has no value yet: a
    // value set in the console is never overwritten by the default.
    if (reportChoice.explicit || reportChoice.changed || !serverKeys.includes('PIEZAS_REPORT_BUTTON')) sent.PIEZAS_REPORT_BUTTON = reportChoice.value;
    if (sentNames.length) {
      log(`  Env: sending ${sentNames.join(', ')} (typed via --env)`);
      const localish = sentNames.filter((k) => /localhost|127\.0\.0\.1/.test(String(sent[k])));
      if (localish.length) {
        log(`  Warning: ${localish.join(', ')} point${localish.length === 1 ? 's' : ''} at localhost — the hosted app cannot reach your machine.`);
      }
    }

    // Settings, by NAME only (Spec 1-A). What the app needs: declared in the
    // manifest (deploy.requiredEnv / optionalEnv), read by the built code, and
    // named in the local .env (names only, never values). Compared with the
    // live app's names (pulled from the platform) plus typed --env pairs.
    // Missing required: one plain message inside the pause. Missing optional:
    // one line, no pause. The server re-verifies the declared list post-merge.
    let manifestNow = null;
    try { manifestNow = readJsonFile(resolve(projectDir, 'piezas.manifest.json')); } catch { /* no manifest */ }
    const needed = settingsNeeded(projectDir, staging, manifestNow, { kind: staged.kind });
    let required = needed.declaredRequired;
    const effective = new Set([...serverKeys, ...Object.keys(sent)]);
    // A setting the live app has now ends the owner's earlier answers for it.
    try { clearDeployItems(projectDir, 'setting', [...effective], 'set on the live app'); } catch { /* best effort */ }
    // The names this build reads (never values), kept with the owner's
    // records so the MCP's deploy needs no argument for them.
    if (needed.scanned) {
      try {
        const { settingNames: names, required: requiredNames } = settingNamesFor(needed);
        appendOwnerRecord(projectDir, { gate: 'setting-names', by: 'piezas', names, required: requiredNames, at: new Date().toISOString() },
          (a) => a.gate === 'setting-names' && JSON.stringify(a.names) === JSON.stringify(names) && JSON.stringify(a.required) === JSON.stringify(requiredNames));
      } catch { /* best effort */ }
    }
    const missing = needed.required.filter((k) => !effective.has(k));
    const optionalMissing = needed.optional.filter((k) => !effective.has(k));
    // "never the values" is said only when a local settings file was read.
    if (needed.scanned || needed.declaredRequired.length) {
      log(`  Checked the names of your settings${needed.readLocal ? ', never the values' : ''}: ${missing.length ? `missing on the live app: ${missing.join(', ')}` : 'all set'}.`);
    }
    if (serverKeys.length) log(`  Live app settings: ${serverKeys.join(', ')}`);
    if (optionalMissing.length) log(`  ${optionalSettingsLine(optionalMissing)}`);
    const mayNeedMissing = (needed.mayNeed ?? []).filter((k) => !effective.has(k));
    if (mayNeedMissing.length) log(`  ${mayNeedSettingsLine(mayNeedMissing)}`);
    if (missing.length) {
      // Couldn't read ANY hosted env (no deployment record returned) AND every
      // required var reads missing: the frequent cause is a STALE CLI session,
      // not a genuinely-empty environment. The apps-server returns empty rather
      // than 401 for a token whose control-plane session was revoked or rolled
      // back (see the preflight note above), so the real settings are invisible
      // until you re-auth. Lead with login.
      const likelyStaleSession = !hostedExists && serverKeys.length === 0;
      const fingerprint = ownerPauseFingerprint('missing-env', linked.appId, buildDigest(), missing);
      const settingsOk = ownerPauseApproved(projectDir, options, fingerprint);
      if (likelyStaleSession && !settingsOk && missing.some((k) => !answerOf({ kind: 'setting', key: k, fp: k }))) {
        log('');
        log('  Could not read ANY hosted settings for this app. If you already set');
        log('  them, your sign-in is probably out of date: run `npx piezas login`,');
        log('  then deploy again.');
      }
      pauseGroups.push({
        name: 'settings',
        status: 'missing-env',
        legacy: { fingerprint, pause: 'missing-env' },
        legacyOk: settingsOk,
        items: missing.map((k) => ({ kind: 'setting', key: k, fp: k, title: k })),
        render: (open) => [OWNER_PAUSE_TEXT.missingEnv(open.map((i) => i.key), appConsoleUrl(linked.appId))],
        forAI: 'name the missing settings and where the owner sets them; never ask for their values in the chat.',
        extra: { missing, likelyStaleSession, consoleUrl: appConsoleUrl(linked.appId) },
        // The owner chose to go live without them: hosting checks only the
        // settings that are there.
        live: () => {
          required = required.filter((k) => effective.has(k));
          overrides.push({ fingerprint, what: `these settings are not set yet: ${missing.join(', ')}` });
        },
      });
    }

    // The never-rules, checked here on the packaged build before anything is
    // uploaded, the same way the hosting server checks it. An older server
    // without that check still gets this pause. One owner confirmation covers
    // both: the fingerprint is computed the same way on both sides.
    // The pause lists every browser leak (each its own item); what is sent
    // to the server as the owner's confirmation stays the server mirror's
    // fingerprint (it stops at the first leak, as the server does).
    const { findings: localFindings, beyond: leaksBeyond, mirror, scanned: leakScanned } = scanArtifactFindings(staging, staged.kind);
    let hardNoAck = null;
    if (localFindings.length) {
      const fingerprint = hardNoFingerprint(localFindings);
      const serverFingerprint = mirror.length ? hardNoFingerprint(mirror) : null;
      const confirmed = options.acknowledge || confirmedHardNo(projectDir);
      pauseGroups.push({
        name: 'rules',
        status: 'needs-confirmation',
        legacy: { fingerprint, pause: 'hard-no' },
        legacyOk: (confirmed === fingerprint && fingerprint === serverFingerprint) || deployRiskApproved(projectDir, fingerprint),
        items: hardNoItems(localFindings),
        render: (open) => [PAUSE_TEXT.rules(open.map((i) => i.finding))],
        forAI: `where: ${localFindings.map((f) => (f.path ? `${f.path} (${f.detail})` : f.detail)).join('; ')}. Fix it (Piezas records; the key server-side only), or the owner decides.`,
        extra: { hardNo: localFindings },
        live: () => { hardNoAck = serverFingerprint; },
      });
    }

    // --- the one pause ------------------------------------------------------
    // Everything that still needs the owner, in one message with one answer.
    // What they already answered for exactly this version of it is not asked
    // again; all answered, the deploy goes live with one summary line.
    const { open: openGroups, answered: answeredItems } = openPauseGroups(pauseGroups, answerOf);
    if (openGroups.length) {
      const memo = [pauseMemoLine(answeredItems, openGroups), changedSinceLine(openGroups, earlierVersionAnswers(projectDir))].filter(Boolean).join(' ');
      return await deployOnePause(projectDir, options, openGroups, { memo });
    }
    for (const g of pauseGroups) {
      if (g.name === 'tests') testGateOverride = gate;
      else {
        const before = overrides.length;
        g.live?.();
        if (g.legacyOk) for (let i = before; i < overrides.length; i++) overrides[i].byRecord = true;
      }
    }

    // A Piezas SERVER app without PIEZAS_API_KEY in its hosted env would boot
    // and then 401 on every backend call. Never a question (Spec Part 2, #39):
    // deploy mints this app's key and stages it in the live settings, the same
    // provisioning app creation does, in AI runs too. Static apps are exempt
    // (no server-side key), and a typed --env PIEZAS_API_KEY counts.
    if (staged.kind === 'server' && !linked.keyStaged
      && !serverKeys.includes('PIEZAS_API_KEY') && !sent.PIEZAS_API_KEY) {
      const mint = await mintAndStageHostedKey(linked, credentials, options, fetchFn, { slug, projectDir });
      if (mint.ok) {
        log('  Added this app\'s Piezas key to its live settings.');
      } else {
        const signIn = mint.stage !== 'revoke' && (mint.status === 401 || mint.status === 403);
        log(`  ${signIn ? KEY_MINT_TEXT.signIn : KEY_MINT_TEXT.failed(appConsoleUrl(linked.appId))}`);
        if (!ownerAtTerminal(options)) log(`  ${KEY_MINT_TEXT.forAI(mint)}`);
        log('');
        return {
          exitCode: 1, command: 'deploy', status: 'missing-piezas-key',
          mintStatus: mint.status, mintStage: mint.stage,
        };
      }
    }

    const form = new FormData();
    form.set('app', appName);
    form.set('appId', linked.appId);
    form.set('kind', staged.kind);
    form.set('env', JSON.stringify(sent));
    // Always sent, `null` included: the platform must be able to tell "this
    // deploy was never tested" from "this client is too old to say".
    // `attestation` is the summary hosting reads ({version, scenarios,
    // covered, passed, failed, ranAt}, counts only); the full record goes as
    // `attestationDetail`. Both `null` for a deploy that was never tested.
    form.set('attestation', JSON.stringify(attestationSummary(attestation)));
    // The owner's "keep trying" and the AI's check attempts travel with it.
    const testDecisions = testDecisionsSummary(projectDir);
    form.set('attestationDetail', JSON.stringify(attestation ? { ...attestation, ...(testDecisions ? { decisions: testDecisions } : {}) } : null));
    if (testGateOverride) form.set('testGateAcknowledged', testGateOverride.fingerprint);
    // The quality scan's result, counts only (`null` when the owner never
    // chose; hosting does not read it yet).
    const qualitySent = qualitySummary(quality, projectDir);
    form.set('qualityAttestation', JSON.stringify(unattendedAllowed ? { ...qualitySent, unattended: true } : qualitySent));
    // What another reader (the MCP) needs to see the owner's answers as this
    // CLI does: the per-item answers in force and their clears, and the
    // setting names this build reads (names only, never values).
    try {
      form.set('ownerItems', JSON.stringify(ownerItemsFor(projectDir, needed)));
    } catch { /* best effort */ }
    if (required.length) form.set('requiredEnv', JSON.stringify(required));
    // "This project deployed this app": the hash of the project's own token
    // (made on its first deploy of this app), for hosting to keep with the
    // deployment and return on later lookups (ensureAppLink).
    try { form.set('projectLink', deployLinkFor(projectDir, linked.appId)); } catch { /* best effort */ }
    if (typeof options.cmd === 'string' && options.cmd.trim()) form.set('cmd', options.cmd.trim());
    form.set('artifact', new Blob([readFileSync(tarball)]), 'app.tar.gz');
    // The owner's confirmation of exactly the findings they were shown (typed
    // "deploy anyway" in their AI tool, or answered at the terminal prompt).
    // The server's own fingerprint (passed back when it found more than this
    // scan did) wins over the local one.
    const acknowledged = options.acknowledge || hardNoAck || confirmedHardNo(projectDir);
    if (acknowledged) form.set('acknowledgeHardNo', acknowledged);

    log(`  Uploading to ${base} ...`);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), options.deployTimeoutMs ?? DEPLOY_TIMEOUT_MS);
    let res;
    try {
      const raw = await netFetch(fetchFn, `${base}/v1/deployments`, {
        method: 'POST',
        headers: { authorization: `Bearer ${credentials.cliToken}` },
        body: form,
        signal: controller.signal,
      });
      let data;
      try { data = await raw.json(); } catch { data = undefined; }
      res = { status: raw.status, data };
    } finally {
      clearTimeout(timer);
    }

    if (res.status === 401) {
      log('  Your session has expired — run `npx piezas login`, then retry.\n');
      return { exitCode: 1, command: 'deploy', status: 'unauthorized' };
    }
    if (res.status === 409 && res.data?.needsConfirmation) {
      return await deployNeedsConfirmation(projectDir, options, res.data);
    }
    if (res.status !== 201) {
      log(`  Deploy failed (HTTP ${res.status}): ${res.data?.error || 'unknown error'}`);
      if (res.data?.logs) {
        log('  --- app output ---');
        console.log(res.data.logs);
      }
      log('');
      return { exitCode: 1, command: 'deploy', status: `http-${res.status}` };
    }

    // Live: nothing waits for the owner any more.
    clearPendingDeployRisk(projectDir);
    if (reportChoice.changed) clearReportButtonUnsent(projectDir);
    // A broken rule that is fixed: its earlier answers end, so the same rule
    // broken again later is asked again. Only on evidence that it is gone
    // (ruleAnswerGone), never because a response did not mention it.
    try {
      const gone = ruleAnswerGone({ localFindings: [...localFindings, ...leaksBeyond], serverFindings: res.data?.hardNo, staging, scanned: leakScanned });
      clearDeployItems(projectDir, 'rule', liveItemKeys(projectDir, 'rule').filter(gone), 'fixed');
    } catch { /* best effort */ }
    clearDeployWanted(projectDir);
    if (quality.skipped) markSkipUsed(projectDir, quality.fingerprint);
    persistDeploySlug(projectDir, res.data.slug, res.data.url);
    // An explicit --dir is remembered, so it is typed once.
    // Stored project-relative; a folder outside the project is not recorded.
    if (typeof options.dir === 'string' && options.dir.trim()) persistDeployDir(projectDir, options.dir.trim());
    log('');
    log(`  ✓ Live at ${res.data.url}${sandbox ? '  (simulated — nothing was published)' : ''}`);
    // One line for what the owner chose to go live without: the per-item
    // summary; the older wording only for a group answered by its pause-wide
    // record (an older answer).
    if (answeredItems.length) log(`  ${goingLiveWithoutLine(answeredItems)}`);
    const byRecord = new Set(pauseGroups.filter((g) => g.legacyOk).map((g) => g.name));
    if (testGateOverride && byRecord.has('tests')) log(`  ${OWNER_TEXT.overridden(testGateOverride.problems.map((p) => p.title))}`);
    if (quality.skipped) log(`  ${QUALITY_TEXT.skipped}`);
    for (const o of overrides) if (o.byRecord) log(`  ${OWNER_PAUSE_TEXT.overridden(o.what)}`);
    if (gate.notes.length) log(`  ${OWNER_TEXT.notesOnDeploy(gate.notes)}`);
    // The server's never-rule scan (warn mode): live, but the owner must know.
    for (const f of Array.isArray(res.data.hardNo) ? res.data.hardNo : []) {
      const what = f.rule === 'local-database'
        ? `the app keeps its own local database (${f.detail})`
        : `the Piezas key is visible to every visitor (${f.path})`;
      log(`  ⚠ Piezas check: ${what}. Fix this soon — the platform will start refusing it.`);
    }
    log('  Status any time:  npx piezas deploy --status');
    log('  Logs:             npx piezas deploy --logs\n');
    return {
      exitCode: 0,
      command: 'deploy',
      ...res.data,
      testGate: { ok: gate.ok, overridden: Boolean(testGateOverride), fingerprint: testGateOverride?.fingerprint ?? null, notes: gate.notes, problems: testGateOverride?.problems ?? [] },
      qualityScan: qualitySummary(quality),
      ownerOverrides: overrides.map((o) => o.what),
    };
  } catch (error) {
    log(`  Deploy failed: ${error?.message || error}\n`);
    return { exitCode: 1, command: 'deploy', status: 'error' };
  } finally {
    try { rmSync(staging, { recursive: true, force: true }); } catch { /* best-effort */ }
    try { unlinkSync(tarball); } catch { /* may not exist */ }
  }
}

// envCmd implements `piezas env ls|set KEY=VALUE|rm KEY` against the HOSTED
// environment (the cloud store the app actually runs with). ls prints names
// only — values are write-only everywhere, terminal included.
// The app's page on the Piezas console: its Hosting card holds the
// environment editor (write-only values), available before the first deploy.
export function appConsoleUrl(appId) {
  return appId ? `${TARGET.console}/apps/${encodeURIComponent(appId)}` : TARGET.console;
}

// whereToSetLines — where the PERSON sets values themselves. Never through an
// AI chat: a chat can be kept for a long time.
export function whereToSetLines(appId, names) {
  return [
    '  Set them yourself (values never go through an AI chat):',
    `    on the app page: ${appConsoleUrl(appId)}  (Hosting -> Environment)`,
    `    or in your own terminal: npx piezas env set ${names.map((k) => `${k}=...`).join(' ')}`,
  ];
}

// --- Report a problem ------------------------------------------------------
// Every app with a server carries a "Report a problem" button (contract v6).
// Reports land in the app's own records (entity problem_reports, status new).
// `piezas reports` lists the open ones (not yet fixed); `--save` writes them
// into .piezas/reports/ for the AI to fix together and marks them received;
// `--done <id>` marks a fixed one done, which is what takes it off the list.
// It reads the app's own key the way the app does locally (PIEZAS_API_KEY,
// else the project .env) and never prints it.
export const REPORT_ENTITY_SLUG = 'problem_reports';
/** Statuses a report can be in before it is fixed; `piezas reports` shows these. */
export const REPORT_OPEN_STATUSES = ['new', 'received'];
export const REPORT_STATUS_DONE = 'done';

export function appApiBase(projectDir, env) {
  const fromEnv = typeof env.PIEZAS_API_BASE === 'string' && env.PIEZAS_API_BASE.trim() ? env.PIEZAS_API_BASE.trim() : undefined;
  const manifestBase = readManifestSafe(projectDir)?.apiBaseUrl;
  return (fromEnv || (typeof manifestBase === 'string' && manifestBase) || TARGET_HOSTS[savedTarget(env)].api).replace(/\/+$/, '');
}

// Splits `--done a,b c` into ids. Values may repeat or be comma-separated.
export function reportIdsFrom(values) {
  const list = (Array.isArray(values) ? values : [values]).filter((v) => typeof v === 'string');
  return [...new Set(list.flatMap((v) => v.split(',')).map((v) => v.trim()).filter(Boolean))];
}

const REPORT_ID = /^[A-Za-z0-9_-]{1,100}$/;

// Who sent a report, as the app's route saved it: `session` (Piezas sign-in,
// verified), `app` (the app's own sign-in, via identify), `self-reported`
// (typed into the dialog, not verified). Null when nobody is named.
const REPORTER_LABELS = { session: 'signed in', app: 'from the app', 'self-reported': 'self-reported, not verified' };
export function reporterOf(data) {
  const source = typeof data?.reporter_source === 'string' ? data.reporter_source : '';
  if (!REPORTER_LABELS[source]) return null;
  const text = (v) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 200) : null);
  const reporter = { source, id: text(data.reporter_id), email: text(data.reporter_email), name: text(data.reporter_name) };
  return reporter.id || reporter.email || reporter.name ? reporter : null;
}
/** "pat@example.com (signed in)", or null when the report names nobody. */
export function describeReporter(reporter) {
  if (!reporter) return null;
  const who = reporter.email || reporter.name || reporter.id;
  return `${who} (${REPORTER_LABELS[reporter.source]})`;
}

// Signs in with the app's key and finds the problem_reports entity type.
// Returns { fail } with a finished result when it cannot go on.
async function openReports(options, result) {
  const env = options.env ?? process.env;
  const projectDir = options.cwd || process.cwd();
  const fetchFn = options.fetchFn ?? fetch;
  if (isSandboxProject(projectDir)) {
    log('  Practice mode has no real app, so there are no problem reports.\n');
    return { fail: result(options.done ? 1 : 0, 'sandbox', { reports: [] }) };
  }
  const key = (typeof env.PIEZAS_API_KEY === 'string' && env.PIEZAS_API_KEY.trim()) || readEnvKeyValue(resolve(projectDir, '.env'));
  if (!key) {
    log('  This project has no app key yet, so reports cannot be read. Run `npx piezas init` first.\n');
    return { fail: result(1, 'no-key') };
  }
  const apiBase = appApiBase(projectDir, env);
  const exchange = await fetchJson(fetchFn, `${adminBaseUrl(apiBase)}/v1/auth/token`, {
    method: 'POST', body: { api_key: key }, timeoutMs: options.httpTimeoutMs,
  });
  const token = exchange.data?.access_token;
  if (exchange.status !== 200 || !token) {
    log(`  Could not sign in with this app's key (HTTP ${exchange.status}).\n`);
    return { fail: result(1, `http-${exchange.status}`) };
  }
  const entities = `${apiBase}/entities`;
  const http = { token, timeoutMs: options.httpTimeoutMs };
  const schemas = await fetchJson(fetchFn, `${entities}/v1/schemas`, http);
  if (schemas.status !== 200) {
    log(`  Could not read the app's records (HTTP ${schemas.status}).\n`);
    return { fail: result(1, `http-${schemas.status}`) };
  }
  const list = Array.isArray(schemas.data) ? schemas.data : (schemas.data?.data ?? []);
  const schema = list.find((x) => x?.slug === REPORT_ENTITY_SLUG) ?? null;
  return { projectDir, fetchFn, apiBase, entities, http, schema };
}

// At most this many open reports are read (the SDK's MAX_OPEN_REPORTS).
export const MAX_OPEN_REPORTS = 1000;
const REPORTS_PAGE = 100;

export async function reports(options = {}) {
  const result = (exitCode, status, extra = {}) => ({ exitCode, command: 'reports', status, ...extra });
  if (options.done !== undefined) return markReportsDone(options, result);

  const opened = await openReports(options, result);
  if (opened.fail) return opened.fail;
  const { projectDir, fetchFn, apiBase, entities, http, schema } = opened;
  if (!schema) {
    log('  No problem reports yet.\n');
    return result(0, 'none', { reports: [] });
  }
  // Open = not fixed yet: fresh (new) and already pulled (received). A
  // report leaves this list only when it is marked done.
  // Page by page (the records service returns at most 100 at a time), up to
  // MAX_OPEN_REPORTS in all.
  const rows = [];
  let total = 0;
  for (const status of REPORT_OPEN_STATUSES) {
    let offset = 0;
    let statusTotal = 0;
    for (;;) {
      const room = MAX_OPEN_REPORTS - rows.length;
      const qs = new URLSearchParams({ entity_type_id: schema.id, status, limit: String(Math.min(REPORTS_PAGE, Math.max(room, 1))), offset: String(offset) });
      const records = await fetchJson(fetchFn, `${entities}/v1/records?${qs}`, http);
      if (records.status !== 200) {
        log(`  Could not read the problem reports (HTTP ${records.status}).\n`);
        return result(1, `http-${records.status}`);
      }
      const data = Array.isArray(records.data?.data) ? records.data.data : [];
      const said = Number(records.data?.total);
      statusTotal = Number.isFinite(said) ? Math.max(said, offset + data.length) : offset + data.length;
      rows.push(...data.slice(0, Math.max(room, 0)));
      offset += data.length;
      if (!data.length || offset >= statusTotal || rows.length >= MAX_OPEN_REPORTS) break;
    }
    total += statusTotal;
  }
  const truncated = total > rows.length;
  const found = rows.map((r) => ({
    id: r.id,
    status: r.status ?? null,
    message: String(r.data?.message ?? r.title ?? ''),
    page: r.data?.page ?? null,
    browser: r.data?.browser ?? null,
    viewport: r.data?.viewport || null,
    context: (() => { try { return r.data?.context ? JSON.parse(r.data.context) : null; } catch { return null; } })(),
    screenshotId: r.data?.screenshot_document_id || null,
    reportedAt: r.data?.reported_at ?? r.createdAt ?? null,
    reporter: reporterOf(r.data),
  })).sort((a, b) => String(a.reportedAt ?? '').localeCompare(String(b.reportedAt ?? '')));
  if (!found.length) {
    log('  No open problem reports.\n');
    return result(0, 'none', { reports: [] });
  }

  if (truncated) log(`  Showing the first ${MAX_OPEN_REPORTS.toLocaleString('en-US')} open reports (there are ${total.toLocaleString('en-US')}). Mark fixed ones done to see the rest.\n`);
  log(`  ${found.length} open problem report${found.length === 1 ? '' : 's'}:\n`);
  for (const r of found) {
    log(`  - ${r.id}: ${r.message.length > 120 ? `${r.message.slice(0, 117)}...` : r.message}${r.screenshotId ? ' (with screenshot)' : ''}`);
    if (r.page) log(`    on ${r.page}`);
    if (r.reporter) log(`    from ${describeReporter(r.reporter)}`);
  }
  log('');
  if (!options.save) {
    log('  Run `npx piezas reports --save` to collect them into .piezas/reports/.\n');
    return result(0, 'listed', { reports: found, truncated, total });
  }

  const dir = resolve(projectDir, '.piezas', 'reports');
  safeMkdir(dir);
  const saved = [];
  for (const r of found) {
    const name = String(r.id).replace(/[^A-Za-z0-9_-]/g, '_');
    // The screenshot first: it is what the AI should look at before anything.
    let image = null;
    if (r.screenshotId) image = await downloadReportScreenshot(fetchFn, `${apiBase}/documents`, http, r.screenshotId, join(dir, name));
    const lines = [
      `# Problem report ${r.id}`,
      '',
      `- Reported: ${r.reportedAt ?? 'unknown'}`,
      `- Reported by: ${describeReporter(r.reporter) ?? 'not given'}`,
      `- Page: ${r.page ?? 'unknown'}`,
      `- Window: ${r.viewport ?? 'unknown'}`,
      `- Browser: ${r.browser ?? 'unknown'}`,
      `- Screenshot: ${image ? basename(image) : r.screenshotId ? 'could not be downloaded' : 'none'}`,
      '',
      '## What they wrote',
      '',
      r.message,
      '',
    ];
    const errors = r.context?.console ?? [];
    const failed = r.context?.network ?? [];
    if (errors.length) {
      lines.push('## Errors and warnings on the page', '');
      for (const e of errors) lines.push(`- ${e.level ?? 'error'}: ${String(e.message ?? '').slice(0, 300)}`);
      lines.push('');
    }
    if (failed.length) {
      lines.push('## Failed requests', '');
      for (const f of failed) lines.push(`- ${f.method ?? 'GET'} ${f.url ?? '?'} -> ${f.status === 0 ? 'no response' : f.status}`);
      lines.push('');
    }
    lines.push('## When it is fixed', '', `Test the fix, then run \`npx piezas reports --done ${r.id}\`.`, '');
    const file = join(dir, `${name}.md`);
    writeFileSync(file, lines.join('\n'));
    let marked = r.status === 'received';
    if (!marked) {
      const mark = await fetchJson(fetchFn, `${entities}/v1/records/${encodeURIComponent(r.id)}`, { ...http, method: 'PUT', body: { status: 'received' } });
      marked = mark.status === 200;
    }
    saved.push({ ...r, file: relative(projectDir, file), image: image ? relative(projectDir, image) : null, marked });
  }
  log(`  Saved ${saved.length} report${saved.length === 1 ? '' : 's'} to .piezas/reports/.`);
  log('  Look at each <id>.jpg and read each <id>.md, fix the problem and test it.');
  log(`  After fixing, run \`npx piezas reports --done <id>\` (several: --done ${saved.slice(0, 2).map((r) => r.id).join(',') || '<id>,<id>'}).`);
  log('  Reports stay on this list until they are marked done.');
  log('');
  return result(0, 'saved', { reports: saved, truncated, total });
}

// `piezas reports --done <id> [<id>...]`: marks fixed reports done. Each id
// is checked to be a problem report of this app before its status changes, so
// a wrong id can never touch another record.
async function markReportsDone(options, result) {
  const ids = reportIdsFrom(options.done);
  if (!ids.length) {
    log('  Say which reports are fixed: `npx piezas reports --done <id> [<id>...]`.\n');
    return result(1, 'no-ids', { done: [] });
  }
  const opened = await openReports(options, result);
  if (opened.fail) return opened.fail;
  const { fetchFn, entities, http, schema } = opened;
  const outcomes = [];
  for (const id of ids) {
    const fail = (reason, message) => {
      outcomes.push({ id, ok: false, reason });
      log(`  - ${id}: ${message}`);
    };
    if (!REPORT_ID.test(id)) { fail('bad-id', 'not a report id.'); continue; }
    if (!schema) { fail('not-found', 'no such problem report.'); continue; }
    const url = `${entities}/v1/records/${encodeURIComponent(id)}`;
    const record = await fetchJson(fetchFn, url, http);
    if (record.status === 404 || record.status === 400 || (record.status === 200 && record.data?.entityTypeId !== schema.id)) {
      fail('not-found', 'no such problem report.');
      continue;
    }
    if (record.status !== 200) { fail(`http-${record.status}`, `could not be read (HTTP ${record.status}).`); continue; }
    if (record.data?.status === REPORT_STATUS_DONE) {
      outcomes.push({ id, ok: true, already: true });
      log(`  - ${id}: already done.`);
      continue;
    }
    const put = await fetchJson(fetchFn, url, { ...http, method: 'PUT', body: { status: REPORT_STATUS_DONE } });
    if (put.status !== 200) { fail(`http-${put.status}`, `could not be marked done (HTTP ${put.status}).`); continue; }
    outcomes.push({ id, ok: true });
    log(`  - ${id}: marked done.`);
  }
  const failed = outcomes.filter((o) => !o.ok).length;
  log('');
  if (failed) log(`  ${failed} of ${outcomes.length} could not be marked done.\n`);
  else log(`  ${outcomes.length} report${outcomes.length === 1 ? '' : 's'} marked done.\n`);
  return result(failed ? 1 : 0, failed ? (failed === outcomes.length ? 'done-failed' : 'done-partial') : 'done', { done: outcomes });
}

// Downloads a report's screenshot from the app's Documents next to its .md.
// Returns the file path, or null if it could not be fetched.
export async function downloadReportScreenshot(fetchFn, documentsBase, http, documentId, pathWithoutExtension) {
  try {
    const link = await fetchJson(fetchFn, `${documentsBase}/v1/documents/${encodeURIComponent(documentId)}/download-url`, http);
    const url = link.data?.downloadUrl;
    if (link.status !== 200 || !url) return null;
    const response = await netFetch(fetchFn, url);
    if (!response.ok) return null;
    const type = String(response.headers?.get?.('content-type') ?? '');
    const extension = type.includes('png') ? 'png' : type.includes('webp') ? 'webp' : 'jpg';
    const file = `${pathWithoutExtension}.${extension}`;
    writeFileSync(file, Buffer.from(await response.arrayBuffer()));
    return file;
  } catch {
    return null;
  }
}

// `piezas report-button on|off`: saves the owner's choice; the next deploy
// sends it to the live app (PIEZAS_REPORT_BUTTON), even when the live app
// already has a value.
// The owner's choice for unattended deploys (CI, or no terminal and no AI
// tool): on lets such a run go live without the quality scan; the checks
// still decide. Kept with the owner's other records (closed to the AI).
const UNATTENDED_GATE = 'unattended-deploys';
export function unattendedDeploysOn(projectDir) {
  return ownerRecords(projectDir, UNATTENDED_GATE).filter((r) => r.by === 'owner').at(-1)?.setting === 'on';
}
export function unattendedCmd(options = {}) {
  const projectDir = options.cwd || process.cwd();
  const env = options.env ?? process.env;
  const state = options.state;
  if (inAiTool(env)) {
    console.error('  Only the owner can change this, in their own terminal outside the AI tool. Nothing was changed. (For the AI: tell the owner in one sentence to run it themselves.)');
    return { exitCode: 1, command: 'unattended', status: 'refused' };
  }
  if (!stdinIsTerminal()) {
    console.error('  Only the owner can change this, in their own terminal.');
    return { exitCode: 1, command: 'unattended', status: 'refused' };
  }
  if (state !== 'on' && state !== 'off') {
    log(`  Unattended deploys are ${unattendedDeploysOn(projectDir) ? 'on' : 'off'}. Change it with: piezas unattended on (or off).\n`);
    return { exitCode: state === undefined || state === 'status' ? 0 : 2, command: 'unattended', status: unattendedDeploysOn(projectDir) ? 'on' : 'off' };
  }
  appendOwnerRecord(projectDir, { gate: UNATTENDED_GATE, setting: state, by: 'owner', at: new Date().toISOString() });
  log(state === 'on'
    ? '  Saved: unattended deploys are on. They go live without the quality scan; the checks must still pass.\n'
    : '  Saved: unattended deploys are off.\n');
  return { exitCode: 0, command: 'unattended', status: state };
}

export function reportButton(options = {}) {
  const projectDir = options.cwd || process.cwd();
  const manifestPath = resolve(projectDir, 'piezas.manifest.json');
  const state = options.state;
  let manifest;
  try { manifest = readJsonFile(manifestPath); } catch { manifest = null; }
  if (!manifest) {
    log('  No piezas.manifest.json here. Run `npx piezas init` first.\n');
    return { exitCode: 1, command: 'report-button', status: 'no-manifest' };
  }
  if (state !== 'on' && state !== 'off') {
    const current = manifest.reportButton === false ? 'off' : 'on';
    log(`  The Report a problem button is ${current}. Change it with \`npx piezas report-button on\` or \`off\`.\n`);
    return { exitCode: state === undefined ? 0 : 2, command: 'report-button', status: current };
  }
  const before = manifest.reportButton === false ? 'off' : 'on';
  if (state === 'off') manifest.reportButton = false;
  else delete manifest.reportButton;
  if (before !== state) manifest.reportButtonUnsent = true;
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
  log(`  Saved: the Report a problem button is ${state}. Your live app changes with your next deploy.\n`);
  return { exitCode: 0, command: 'report-button', status: state };
}

export async function envCmd(options = {}) {
  const env = options.env ?? process.env;
  const projectDir = options.cwd || process.cwd();
  const fetchFn = platformFetch(projectDir, options);
  const base = appsBaseUrl(options, env);

  if (isSandboxProject(projectDir)) log(`  ${SANDBOX_NOTE}\n`);

  const credentials = platformCredentials(projectDir, env);
  if (!credentials) {
    log(`  ${signInNeededLine(env, options)}\n`);
    return { exitCode: 1, command: 'env', status: 'not-logged-in' };
  }
  const httpOptions = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  const slug = deploySlugFor(projectDir, options);
  const appId = (() => {
    try { return readJsonFile(resolve(projectDir, 'piezas.manifest.json')).deploy?.appId ?? null; } catch { return null; }
  })();
  const idQS = appId ? `?appId=${encodeURIComponent(appId)}` : '';

  const action = options.action;
  if (action === 'check') {
    // Names only, never values: what the app declares it needs
    // (deploy.requiredEnv in piezas.manifest.json, the same list deploy and
    // the hosting server check) against what is set in the hosted environment.
    let required = [];
    try {
      const man = readJsonFile(resolve(projectDir, 'piezas.manifest.json'));
      if (Array.isArray(man?.deploy?.requiredEnv)) required = man.deploy.requiredEnv.filter((k) => typeof k === 'string' && k.trim());
    } catch { /* no manifest -> nothing declared */ }
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, httpOptions);
    if (res.status !== 200 && res.status !== 404) {
      log(`  Could not read the hosted environment (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'env', status: `http-${res.status}` };
    }
    const set = res.status === 200 ? (res.data.envKeys ?? []) : [];
    const missing = required.filter((k) => !set.includes(k));
    if (!missing.length) {
      log(required.length ? `  All ${required.length} required settings are set.\n` : '  This app declares no required settings.\n');
      return { exitCode: 0, command: 'env', status: 'ok', required, missing };
    }
    log(`  Missing settings: ${missing.join(', ')}`);
    for (const line of whereToSetLines(appId, missing)) log(line);
    log('');
    return { exitCode: 1, command: 'env', status: 'missing', required, missing, consoleUrl: appConsoleUrl(appId) };
  }

  if (action === 'ls' || action === undefined) {
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}${idQS}`, httpOptions);
    if (res.status === 404) {
      log('  No hosted environment yet — set a variable (here or in the console) to create it.');
      log('  Expected settings here? Your CLI session may be stale — run `npx piezas login` and retry.\n');
      return { exitCode: 0, command: 'env', status: 'empty', keys: [] };
    }
    if (res.status !== 200) {
      log(`  Could not read the hosted environment (HTTP ${res.status}).\n`);
      return { exitCode: 1, command: 'env', status: `http-${res.status}` };
    }
    const keys = res.data.envKeys ?? [];
    log(`  Hosted env for ${res.data.slug} (${res.data.status}) — names only, values are write-only:`);
    for (const k of keys) log(`    ${k}`);
    if (!keys.length) log('    (none set)');
    log('');
    return { exitCode: 0, command: 'env', status: 'ok', keys };
  }

  if (action === 'set' || action === 'rm') {
    const body = { set: {}, unset: [] };
    const refusedEmpty = [];
    for (const arg of options.args ?? []) {
      if (action === 'set') {
        const m = /^([A-Za-z_][A-Za-z0-9_]*)=([\s\S]*)$/.exec(String(arg));
        if (!m) {
          log(`  Skipping "${arg}" — expected KEY=VALUE.`);
          continue;
        }
        // An empty value is almost always a shell-expansion bug (KEY=$TYPO
        // expands to KEY=) — and it "succeeds" silently, leaving the app to
        // fail in ways that take an evening to trace back here. Refuse unless
        // the emptiness is explicit.
        if (m[2] === '' && !options.allowEmpty) {
          log(`  Refusing to set ${m[1]} to an EMPTY value — usually an unset shell variable.`);
          log(`    Meant it? Re-run with --allow-empty, or remove the variable with: env rm ${m[1]}`);
          refusedEmpty.push(m[1]);
          continue;
        }
        body.set[m[1]] = m[2];
      } else {
        body.unset.push(String(arg));
      }
    }
    // Atomic: one empty value aborts the WHOLE call. Applying the good keys
    // while a script's `&& deploy` sails past the refused one would recreate
    // exactly the silent breakage this guard exists to stop.
    if (refusedEmpty.length) {
      log(`  Nothing was applied — fix the empty value${refusedEmpty.length > 1 ? 's' : ''} and re-run.\n`);
      return { exitCode: 2, command: 'env', status: 'empty-value', refusedEmpty };
    }
    if (!Object.keys(body.set).length && !body.unset.length) {
      log(`  Nothing to ${action === 'set' ? 'set — pass KEY=VALUE' : 'remove — pass the variable name'}.\n`);
      return { exitCode: 2, command: 'env', status: 'usage' };
    }
    const res = await fetchJson(fetchFn, `${base}/v1/deployments/${slug}/env${idQS}`, {
      ...httpOptions, method: 'PATCH', body,
    });
    if (res.status !== 200) {
      log(`  Could not update the hosted environment (HTTP ${res.status}): ${res.data?.error || ''}\n`);
      return { exitCode: 1, command: 'env', status: `http-${res.status}` };
    }
    const what = [...Object.keys(body.set), ...body.unset].join(', ');
    log(`  Hosted env updated (${what}).${res.data.status === 'not deployed' ? ' Staged — in place before first deploy.' : ' App restarted.'}\n`);
    return { exitCode: 0, command: 'env', status: 'ok', keys: res.data.envKeys ?? [] };
  }

  log(`  Unknown env action "${action}" — use ls, check, set KEY=VALUE, or rm KEY.\n`);
  return { exitCode: 2, command: 'env', status: 'usage' };
}

// --- End piezas deploy -----------------------------------------------------

export function detectPackageManager(projectDir) {
  if (existsSync(resolve(projectDir, 'pnpm-lock.yaml'))) return 'pnpm';
  if (existsSync(resolve(projectDir, 'yarn.lock'))) return 'yarn';
  if (existsSync(resolve(projectDir, 'bun.lockb'))) return 'bun';
  return 'npm';
}

// hasSdkDependency reports whether package.json already declares @piezas/sdk
// (e.g. a `file:` tarball pin for testing a local build). Init must not clobber
// such a pin by re-adding the published package from the registry.
export function hasSdkDependency(projectDir) {
  const pkgJsonPath = resolve(projectDir, 'package.json');
  if (!existsSync(pkgJsonPath)) return false;
  try {
    const pkg = JSON.parse(readFileSync(pkgJsonPath, 'utf8'));
    return Boolean(
      pkg?.dependencies?.['@piezas/sdk'] || pkg?.devDependencies?.['@piezas/sdk'],
    );
  } catch {
    return false;
  }
}

